4	int ls_pinmux_pin_setup(unsigned int pin, unsigned int mode)
5	{
6		volatile unsigned int *cfg_base_reg;
7		uint32_t group;
8		uint32_t group_num;
9		uint32_t temp;
10		if (pin < 0 || pin > LS_GPIO_MAX)
11		{
12			printf("Error %s pin not in [0-105] (%d)\r\n", __func__, pin);
13			return -1;
14		}
15	
16		group = (pin >> 4);
17		group_num = (pin & 0xf);
18		group_num <<= 1; // * 2 就是设置pin的初始bit
19	
20		cfg_base_reg = (unsigned int *)LS_GPIO_0_15_MULTI_CFG;
21		cfg_base_reg += group;
22		temp = readl(cfg_base_reg);
23		temp |= (0x3 << group_num);	 // 清 0
24		temp ^= (0x3 << group_num);	 // 清 0
25		temp |= (mode << group_num); // 设置对应的模式
26	
27		// printf("===>base: %p temp: 0x%x \r\n", cfg_base_reg, temp);
28		writel(temp, cfg_base_reg);
29		
30		return 0;
31	}
