54	static int oled_pinctrl_setup(void)
55	{
56	  struct pinctrl_param_s param;
57	  int fd;
58	  int ret;
59	
60	  fd = open("/dev/pinctrl0", O_RDWR);
61	  if (fd < 0)
62	    {
63	      printf("[OLED] ERROR: Failed to open /dev/pinctrl0: %d\n", errno);
64	      return -errno;
65	    }
66	
67	  /* Set GPIO50 (SCL) to ALT1 function (I2C1) */
68	
69	  param.pin = I2C1_SCL_PIN;
70	  param.para.function = 1; /* ALT1 = main function */
71	  ret = ioctl(fd, PINCTRLC_SETFUNCTION, (unsigned long)&param);
72	  if (ret < 0)
73	    {
74	      printf("[OLED] ERROR: PINCTRLC_SETFUNCTION GPIO%d failed: %d\n",
75	             I2C1_SCL_PIN, errno);
76	      close(fd);
77	      return -errno;
78	    }
79	
80	  /* Set GPIO51 (SDA) to ALT1 function (I2C1) */
81	
82	  param.pin = I2C1_SDA_PIN;
83	  param.para.function = 1; /* ALT1 = main function */
84	  ret = ioctl(fd, PINCTRLC_SETFUNCTION, (unsigned long)&param);
85	  if (ret < 0)
86	    {
87	      printf("[OLED] ERROR: PINCTRLC_SETFUNCTION GPIO%d failed: %d\n",
88	             I2C1_SDA_PIN, errno);
89	      close(fd);
90	      return -errno;
91	    }
92	
93	  close(fd);
94	  printf("[OLED] Pinctrl: GPIO%d/GPIO%d set to I2C1 function\n",
95	         I2C1_SCL_PIN, I2C1_SDA_PIN);
96	  return OK;
97	}
