99	static int oled_write_byte(int fd, uint8_t reg, uint8_t data)
100	{
101	  struct i2c_msg_s msg;
102	  struct i2c_transfer_s trans;
103	  uint8_t buf[2];
104	  int ret;
105	
106	  buf[0] = reg;
