110	  msg.addr      = OLED_ADDR;
111	  msg.flags     = 0;
112	  msg.buffer    = buf;
113	  msg.length    = 2;
114	
115	  trans.msgv = &msg;
116	  trans.msgc = 1;
117	
118	  ret = ioctl(fd, I2CIOC_TRANSFER, (unsigned long)&trans);
119	  if (ret < 0)
120	    {
121	      printf("[OLED] I2C WRITE failed: addr=0x%02x reg=0x%02x data=0x%02x "
122	             "ret=%d errno=%d\n", OLED_ADDR, reg, data, ret, errno);
123	    }
