138	static int oled_init(int fd)
139	{
140	  static const uint8_t init_cmds[] =
141	  {
142	    0xae, 0x00, 0x10, 0x40, 0xb0, 0x81, 0xff, 0xa1,
143	    0xa6, 0xa8, 0x3f, 0xc8, 0xd3, 0x00, 0xd5, 0x80,
144	    0xd8, 0x05, 0xd9, 0xf1, 0xda, 0x12, 0xdb, 0x30,
145	    0x8d, 0x14, 0xaf,
146	  };
147	
148	  int i;
149	
150	  for (i = 0; i < (int)(sizeof(init_cmds) / sizeof(init_cmds[0])); i++)
151	    {
152	      int ret = oled_write_cmd(fd, init_cmds[i]);
153	      if (ret < 0)
154	        {
155	          printf("[OLED] init cmd 0x%02x failed: %d\n", init_cmds[i], ret);
156	          return ret;
157	        }
158	    }
159	
160	  return OK;
161	}
