170	static void oled_fill_screen(int fd, uint8_t fill)
171	{
172	  uint8_t page;
173	  uint8_t col;
174	
175	  for (page = 0; page < OLED_PAGES; page++)
176	    {
177	      oled_set_position(fd, 0, page);
178	      for (col = 0; col < OLED_WIDTH; col++)
179	        {
