185	static void oled_show_char(int fd, uint8_t x, uint8_t y,
186	                           char ch, oled_font_e font)
187	{
188	  uint8_t c;
189	  uint8_t i;
190	
191	  if (ch < ' ' || ch > '~')
192	    {
193	      ch = ' ';
194	    }
195	
196	  c = (uint8_t)(ch - ' ');
197	
198	  if (font == FONT8X16)
199	    {
200	      oled_set_position(fd, x, y);
201	      for (i = 0; i < 8; i++)
202	        {
203	          oled_write_data(fd, F8X16[c * 16 + i]);
204	        }
205	
206	      oled_set_position(fd, x, y + 1);
207	      for (i = 0; i < 8; i++)
208	        {
209	          oled_write_data(fd, F8X16[c * 16 + 8 + i]);
210	        }
211	    }
212	  else
213	    {
214	      oled_set_position(fd, x, y);
215	      for (i = 0; i < 6; i++)
216	        {
217	          oled_write_data(fd, F6x8[c][i]);
218	        }
219	    }
220	}
221	
222	static void oled_show_string(int fd, uint8_t x, uint8_t y,
223	                             const char *str, oled_font_e font)
224	{
225	  uint8_t step = (font == FONT8X16) ? 8 : 6;
226	
227	  if (str == NULL)
228	    {
229	      return;
230	    }
231	
232	  while (*str != '\0')
233	    {
234	      oled_show_char(fd, x, y, *str, font);
235	      x += step;
236	      if (x > (OLED_WIDTH - step))
237	        {
238	          x = 0;
239	          y += (font == FONT8X16) ? 2 : 1;
240	          if (y >= OLED_PAGES)
241	            {
242	              break;
243	            }
244	        }
245	
246	      str++;
247	    }
248	}
