250	static void oled_i2c_scan(int fd)
251	{
252	  struct i2c_msg_s msg;
253	  struct i2c_transfer_s trans;
254	  uint8_t buf;
255	  int addr;
256	  int found = 0;
257	
258	  printf("[OLED] Scanning I2C1 bus...\n");
259	
260	  for (addr = 0x03; addr < 0x78; addr++)
261	    {
262	      msg.frequency = OLED_I2C_FREQ;
263	      msg.addr      = addr;
264	      msg.flags     = I2C_M_READ;
265	      msg.buffer    = &buf;
266	      msg.length    = 1;
267	
268	      trans.msgv = &msg;
269	      trans.msgc = 1;
270	
271	      if (ioctl(fd, I2CIOC_TRANSFER, (unsigned long)&trans) == 1)
272	        {
273	          printf("[OLED]   Found device at 0x%02x\n", addr);
274	          found++;
275	        }
276	    }
277	
278	  if (found == 0)
279	    {
280	      printf("[OLED]   No devices found on I2C1!\n");
281	    }
282	  else
283	    {
284	      printf("[OLED]   %d device(s) found\n", found);
285	    }
286	}
