561	static int ls2k300_i2c_setup(struct i2c_master_s *dev)
562	{
563	  struct ls2k300_i2c_priv_s *priv =
564	      (struct ls2k300_i2c_priv_s *)dev;
565	
566	  ls2k300_i2c_hw_config(priv);
567	  return OK;
568	}
