570	static int ls2k300_i2c_shutdown(struct i2c_master_s *dev)
571	{
572	  struct ls2k300_i2c_priv_s *priv =
573	      (struct ls2k300_i2c_priv_s *)dev;
574	
575	  i2c_clr_bits(priv, LS2K300_I2C_CR1, I2C_CR1_PE);
576	  return OK;
577	}
