static int ls2k300_i2c_wait_free_bus(struct ls2k300_i2c_priv_s *priv)
{
  uint32_t elapsed = 0;
  uint32_t status;

  while (elapsed < LS2K300_I2C_TIMEOUT_US)
    {
      status = i2c_getreg(priv, LS2K300_I2C_SR2);
      if (!(status & I2C_SR2_BUSY))
        {
          return OK;
        }

      up_udelay(10);
      elapsed += 10;
    }

  /* Bus stuck in busy state - attempt recovery:
   * 1. Disable I2C peripheral
   * 2. Clear all status flags
   * 3. Re-enable I2C peripheral
   */

  i2c_clr_bits(priv, LS2K300_I2C_CR1, I2C_CR1_PE);
  up_udelay(100);

  /* Clear status registers by reading them */

  i2c_getreg(priv, LS2K300_I2C_SR1);
  i2c_getreg(priv, LS2K300_I2C_SR2);

  /* Re-enable peripheral */

  i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_PE);
  up_udelay(100);

  /* Check if bus is now free */

  status = i2c_getreg(priv, LS2K300_I2C_SR2);
  if (!(status & I2C_SR2_BUSY))
    {
      return OK;
    }

  return -EBUSY;
}

