130	static int AHT20_ReadTempHumiX100(int *tempX100, unsigned int *humiX100)
131	{
132	    uint8_t cmd[] = {AHT20_CMD_TRIGGER, 0x33, 0x00};
133	    uint8_t buf[AHT20_READ_LEN] = {0};
134	    uint32_t humiRaw;
135	    uint32_t tempRaw;
136	    int ret;
137	    int i;
138	
139	    ret = AHT20_Write(cmd, sizeof(cmd));
140	    if (ret != 0) {
141	        printf("[AHT20] trigger failed ret=%d\r\n", ret);
142	        return ret;
143	    }
144	
145	    osDelay(80);
146	
147	    for (i = 0; i < AHT20_MAX_RETRY; i++) {
148	        ret = AHT20_Read(buf, sizeof(buf));
149	        if (ret != 0) {
150	            printf("[AHT20] read failed ret=%d\r\n", ret);
151	            return ret;
152	        }
153	
154	        if ((buf[0] & AHT20_STATUS_BUSY) == 0) {
155	            break;
156	        }
157	        osDelay(10);
158	    }
159	
160	    if (i >= AHT20_MAX_RETRY) {
161	        printf("[AHT20] device busy status=0x%02x\r\n", buf[0]);
162	        return -1;
163	    }
164	
165	    humiRaw = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | ((uint32_t)buf[3] >> 4);
166	    tempRaw = (((uint32_t)buf[3] & 0x0F) << 16) | ((uint32_t)buf[4] << 8) | buf[5];
167	
168	    *humiX100 = (unsigned int)(((uint64_t)humiRaw * 10000U) / AHT20_RESOLUTION);
169	    *tempX100 = (int)(((uint64_t)tempRaw * 20000U) / AHT20_RESOLUTION) - 5000;
170	
171	    return 0;
172	}
