16	#define I2C1_SCL_PIN            50
17	#define I2C1_SDA_PIN            51
18	
19	#define AHT20_ADDR              0x38
20	#define AHT20_CMD_STATUS        0x71
21	#define AHT20_CMD_CALIBRATE     0xBE
22	#define AHT20_CMD_TRIGGER       0xAC
23	#define AHT20_CMD_RESET         0xBA
24	#define AHT20_STATUS_BUSY       0x80
25	#define AHT20_STATUS_CALIB      0x08
26	#define AHT20_READ_LEN          6
27	#define AHT20_MAX_RETRY         10
28	#define AHT20_RESOLUTION        (1U << 20)
29	
30	#define OLED_ADDR               0x3C
31	#define OLED_WIDTH              128
32	#define OLED_PAGES              8
33	#define OLED_I2C_CMD            0x00
34	#define OLED_I2C_DATA           0x40
35	
36	typedef enum {
37	    FONT6X8 = 1,
38	    FONT8X16,
39	} OledFont;
