56	static int AHT20_ReadStatus(uint8_t *status)
57	{
58	    int ret = AHT20_WriteCmd(AHT20_CMD_STATUS);
59	    if (ret != IOT_SUCCESS) {
60	        printf("[AHT20] write status cmd failed ret=%d\r\n", ret);
61	        return ret;
62	    }
63	
64	    ret = AHT20_Read(status, 1);
65	    if (ret != IOT_SUCCESS) {
66	        printf("[AHT20] read status failed ret=%d\r\n", ret);
67	        return ret;
68	    }
69	    return IOT_SUCCESS;
70	}
