72	static int AHT20_Calibrate(void)
73	{
74	    uint8_t status = 0;
75	    uint8_t cmd[] = {AHT20_CMD_CALIBRATE, 0x08, 0x00};
76	    int ret = AHT20_ReadStatus(&status);
77	    if (ret != IOT_SUCCESS) {
78	        return ret;
79	    }
80	
81	    if ((status & AHT20_STATUS_CALIB) != 0) {
82	        return IOT_SUCCESS;
83	    }
84	
85	    ret = AHT20_WriteCmd(AHT20_CMD_RESET);
86	    if (ret != IOT_SUCCESS) {
87	        printf("[AHT20] reset failed ret=%d\r\n", ret);
88	        return ret;
89	    }
90	    osDelay(20);
91	
92	    ret = AHT20_Write(cmd, sizeof(cmd));
93	    if (ret != IOT_SUCCESS) {
94	        printf("[AHT20] calibrate failed ret=%d\r\n", ret);
95	        return ret;
96	    }
97	    osDelay(40);
98	
99	    ret = AHT20_ReadStatus(&status);
100	    if (ret != IOT_SUCCESS) {
101	        return ret;
102	    }
103	
104	    if ((status & AHT20_STATUS_CALIB) == 0) {
105	        printf("[AHT20] calibrate failed status=0x%02x\r\n", status);
106	        return -1;
107	    }
108	    return IOT_SUCCESS;
109	}
110	
111	static int AHT20_ReadTempHumiX100(int *tempX100, unsigned int *humiX100)
112	{
113	    uint8_t cmd[] = {AHT20_CMD_TRIGGER, 0x33, 0x00};
114	    uint8_t buf[AHT20_READ_LEN] = {0};
115	    uint32_t humiRaw;
116	    uint32_t tempRaw;
117	    int ret;
118	    int i;
119	
120	    ret = AHT20_Write(cmd, sizeof(cmd));
121	    if (ret != IOT_SUCCESS) {
122	        printf("[AHT20] trigger failed ret=%d\r\n", ret);
123	        return ret;
124	    }
125	
126	    osDelay(80);
127	
128	    for (i = 0; i < AHT20_MAX_RETRY; i++) {
129	        ret = AHT20_Read(buf, sizeof(buf));
130	        if (ret != IOT_SUCCESS) {
131	            printf("[AHT20] read failed ret=%d\r\n", ret);
132	            return ret;
133	        }
134	
135	        if ((buf[0] & AHT20_STATUS_BUSY) == 0) {
136	            break;
137	        }
138	        osDelay(10);
139	    }
140	
141	    if (i >= AHT20_MAX_RETRY) {
142	        printf("[AHT20] device busy status=0x%02x\r\n", buf[0]);
143	        return -1;
144	    }
145	
146	    humiRaw = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | ((uint32_t)buf[3] >> 4);
147	    tempRaw = (((uint32_t)buf[3] & 0x0F) << 16) | ((uint32_t)buf[4] << 8) | buf[5];
148	
149	    *humiX100 = (unsigned int)(((uint64_t)humiRaw * 10000U) / AHT20_RESOLUTION);
150	    *tempX100 = (int)(((uint64_t)tempRaw * 20000U) / AHT20_RESOLUTION) - 5000;
151	
152	    return IOT_SUCCESS;
153	}
