211	static void OledShowChar(uint8_t x, uint8_t y, char ch, OledFont font)
212	{
213	    uint8_t c;
214	    uint8_t i;
215	
216	    if (ch < ' ' || ch > '~') {
217	        ch = ' ';
218	    }
219	    c = (uint8_t)(ch - ' ');
220	
221	    if (font == FONT8X16) {
222	        OledSetPosition(x, y);
223	        for (i = 0; i < 8; i++) {
224	            OledWriteData(F8X16[c * 16 + i]);
225	        }
226	
227	        OledSetPosition(x, y + 1);
228	        for (i = 0; i < 8; i++) {
229	            OledWriteData(F8X16[c * 16 + 8 + i]);
230	        }
231	    } else {
232	        OledSetPosition(x, y);
233	        for (i = 0; i < 6; i++) {
234	            OledWriteData(F6x8[c][i]);
235	        }
236	    }
237	}
