239	static void OledShowString(uint8_t x, uint8_t y, const char *str, OledFont font)
240	{
241	    uint8_t step = (font == FONT8X16) ? 8 : 6;
242	
243	    if (str == NULL) {
244	        return;
245	    }
246	
247	    while (*str != '\0') {
248	        OledShowChar(x, y, *str, font);
249	        x += step;
250	        if (x > (OLED_WIDTH - step)) {
251	            x = 0;
252	            y += (font == FONT8X16) ? 2 : 1;
253	            if (y >= OLED_PAGES) {
