306	static void OledAht20Task(void *arg)
307	{
308	    (void)arg;
309	
310	    printf("[LOONG-HAT] OLED AHT20 demo start\r\n");
311	
312	    while (LoongHatI2cInit() != IOT_SUCCESS) {
313	        osDelay(1000);
314	    }
315	
316	    while (OledInit() != IOT_SUCCESS) {
317	        osDelay(1000);
318	    }
319	    OledFillScreen(0x00);
320	    OledShowString(0, 0, "OLED AHT20", FONT8X16);
321	    OledShowString(0, 3, "Sensor init...", FONT8X16);
322	
323	    while (AHT20_Calibrate() != IOT_SUCCESS) {
324	        printf("[AHT20] init failed, check VCC/GND/SCL50/SDA51 addr=0x%02x\r\n", AHT20_ADDR);
325	        OledFillScreen(0x00);
326	        OledShowString(0, 0, "AHT20 Error", FONT8X16);
327	        OledShowString(0, 3, "Check wiring", FONT8X16);
328	        osDelay(1000);
329	    }
330	
331	    while (1) {
332	        int tempX100 = 0;
333	        unsigned int humiX100 = 0;
334	
335	        if (AHT20_ReadTempHumiX100(&tempX100, &humiX100) == IOT_SUCCESS) {
336	            OledShowTempHumi(tempX100, humiX100);
337	            printf("[OLED] temperature=%d.%02d C humidity=%u.%02u %%RH\r\n",
338	                tempX100 / 100, (tempX100 < 0 ? -tempX100 : tempX100) % 100,
339	                humiX100 / 100, humiX100 % 100);
340	            osDelay(10000);
341	            continue;
342	        }
343	
344	        OledFillScreen(0x00);
345	        OledShowString(0, 0, "Read Failed", FONT8X16);
346	        OledShowString(0, 3, "Reinit sensor", FONT8X16);
347	        while (AHT20_Calibrate() != IOT_SUCCESS) {
348	            osDelay(1000);
349	        }
350	    }
351	}
