113	    printf("[AHT20] IoTI2cInit ret=%d\r\n", ret);
114	    if (ret != 0) {
115	        return ret;
116	    }
117	
118	    osDelay(20);
119	
120	    ret = AHT20_Calibrate();
121	    if (ret != 0) {
122	        printf("[AHT20] init failed, check VCC/GND/SCL50/SDA51 addr=0x%02x\r\n", AHT20_ADDR);
123	        return ret;
124	    }
125	
126	    printf("[AHT20] detected addr=0x%02x\r\n", AHT20_ADDR);
127	    return 0;
128	}
129	
130	static int AHT20_ReadTempHumiX100(int *tempX100, unsigned int *humiX100)
131	{
132	    uint8_t cmd[] = {AHT20_CMD_TRIGGER, 0x33, 0x00};
133	    uint8_t buf[AHT20_READ_LEN] = {0};
134	    uint32_t humiRaw;
135	    uint32_t tempRaw;
136	    int ret;
137	    int i;
138	
139	    ret = AHT20_Write(cmd, sizeof(cmd));
140	    if (ret != 0) {
141	        printf("[AHT20] trigger failed ret=%d\r\n", ret);
142	        return ret;
143	    }
144	
145	    osDelay(80);
146	
147	    for (i = 0; i < AHT20_MAX_RETRY; i++) {
148	        ret = AHT20_Read(buf, sizeof(buf));
149	        if (ret != 0) {
150	            printf("[AHT20] read failed ret=%d\r\n", ret);
151	            return ret;
152	        }
153	
154	        if ((buf[0] & AHT20_STATUS_BUSY) == 0) {
155	            break;
156	        }
157	        osDelay(10);
158	    }
159	
160	    if (i >= AHT20_MAX_RETRY) {
161	        printf("[AHT20] device busy status=0x%02x\r\n", buf[0]);
162	        return -1;
163	    }
164	
165	    humiRaw = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | ((uint32_t)buf[3] >> 4);
166	    tempRaw = (((uint32_t)buf[3] & 0x0F) << 16) | ((uint32_t)buf[4] << 8) | buf[5];
167	
168	    *humiX100 = (unsigned int)(((uint64_t)humiRaw * 10000U) / AHT20_RESOLUTION);
169	    *tempX100 = (int)(((uint64_t)tempRaw * 20000U) / AHT20_RESOLUTION) - 5000;
170	
171	    return 0;
172	}
173	
174	static void AHT20_Task(void *arg)
175	{
176	    (void)arg;
177	
178	    printf("[LOONG-HAT] AHT20 demo start\r\n");
179	
180	    while (1) {
181	        int tempX100 = 0;
182	        unsigned int humiX100 = 0;
183	
184	        while (AHT20_Init() != 0) {
185	            osDelay(1000);
186	        }
187	
188	        while (AHT20_ReadTempHumiX100(&tempX100, &humiX100) == 0) {
189	            if (tempX100 < 0) {
190	                printf("[AHT20] temperature = -%d.%02d C, humidity = %u.%02u %%RH\r\n",
191	                    (-tempX100) / 100, (-tempX100) % 100, humiX100 / 100, humiX100 % 100);
192	            } else {
193	                printf("[AHT20] temperature = %d.%02d C, humidity = %u.%02u %%RH\r\n",
194	                    tempX100 / 100, tempX100 % 100, humiX100 / 100, humiX100 % 100);
195	            }
196	
197	            osDelay(1000);
198	        }
199	
200	        printf("[AHT20] read failed, reinit sensor\r\n");
201	    }
202	}
203	
204	static void AHT20_Entry(void)
205	{
206	    osThreadAttr_t attr;
207	
208	    printf("[LOONG-HAT] AHT20 entry\r\n");
209	
210	    attr.name = "AHT20Task";
211	    attr.attr_bits = 0U;
212	    attr.cb_mem = NULL;
213	    attr.cb_size = 0U;
214	    attr.stack_mem = NULL;
215	    attr.stack_size = TASK_STACK_SIZE;
216	    attr.priority = TASK_PRIORITY;
217	
218	    if (osThreadNew(AHT20_Task, NULL, &attr) == NULL) {
219	        printf("[LOONG-HAT] create AHT20 task failed\r\n");
220	    }
221	}
222	
223	SYS_RUN(AHT20_Entry);
