162	static void ls2k300_i2c_hw_config(struct ls2k300_i2c_priv_s *priv)
163	{
164	  uint32_t val;
165	  uint32_t ccr = 0;
166	
167	  i2c_set_bits(priv, LS2K300_I2C_CR2, I2C_CR2_FREQ_MASK);
168	  i2c_set_bits(priv, LS2K300_I2C_TRISE, I2C_CR2_FREQ_MASK);
169	
170	  if (priv->frequency <= I2C_SPEED_STANDARD)
171	    {
172	      val = (LS2K300_I2C_INPUT_CLK + 100000 * 2 - 1) / (100000 * 2);
173	    }
174	  else
175	    {
176	      val = (LS2K300_I2C_INPUT_CLK + 400000 * 3 - 1) / (400000 * 3);
177	      ccr |= I2C_CCR_FS;
178	    }
179	
180	  ccr |= val & 0xfff;
181	  i2c_putreg(priv, LS2K300_I2C_CCR, ccr);
182	
183	  i2c_putreg(priv, LS2K300_I2C_CR1, I2C_CR1_PE);
184	}
185	
186	static int ls2k300_i2c_wait_status(struct ls2k300_i2c_priv_s *priv,
187	                                   uint32_t mask, bool set,
188	                                   uint32_t timeout_us)
189	{
190	  uint32_t elapsed = 0;
191	  uint32_t status;
192	
193	  while (elapsed < timeout_us)
194	    {
195	      status = i2c_getreg(priv, LS2K300_I2C_SR1);
196	
197	      if (set && (status & mask))
198	        {
199	          return OK;
200	        }
201	
202	      if (!set && !(status & mask))
203	        {
204	          return OK;
205	        }
206	
207	      up_udelay(10);
208	      elapsed += 10;
209	    }
210	
211	  return -ETIMEDOUT;
212	}
213	
214	static int ls2k300_i2c_wait_free_bus(struct ls2k300_i2c_priv_s *priv)
215	{
216	  uint32_t elapsed = 0;
217	  uint32_t status;
218	
219	  while (elapsed < LS2K300_I2C_TIMEOUT_US)
220	    {
221	      status = i2c_getreg(priv, LS2K300_I2C_SR2);
222	      if (!(status & I2C_SR2_BUSY))
223	        {
224	          return OK;
225	        }
226	
227	      up_udelay(10);
228	      elapsed += 10;
229	    }
230	
231	  /* Bus stuck in busy state - attempt recovery:
232	   * 1. Disable I2C peripheral
233	   * 2. Clear all status flags
234	   * 3. Re-enable I2C peripheral
235	   */
236	
237	  i2c_clr_bits(priv, LS2K300_I2C_CR1, I2C_CR1_PE);
238	  up_udelay(100);
239	
240	  /* Clear status registers by reading them */
241	
242	  i2c_getreg(priv, LS2K300_I2C_SR1);
243	  i2c_getreg(priv, LS2K300_I2C_SR2);
244	
245	  /* Re-enable peripheral */
246	
247	  i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_PE);
248	  up_udelay(100);
249	
250	  /* Check if bus is now free */
251	
252	  status = i2c_getreg(priv, LS2K300_I2C_SR2);
253	  if (!(status & I2C_SR2_BUSY))
254	    {
255	      return OK;
256	    }
257	
258	  return -EBUSY;
259	}
260	
261	static void ls2k300_i2c_clear_addr(struct ls2k300_i2c_priv_s *priv)
262	{
263	  i2c_getreg(priv, LS2K300_I2C_SR1);
264	  i2c_getreg(priv, LS2K300_I2C_SR2);
265	}
266	
267	static int ls2k300_i2c_check_errors(struct ls2k300_i2c_priv_s *priv,
268	                                    uint32_t status)
269	{
270	  if (status & I2C_SR1_ARLO)
271	    {
272	      i2c_clr_bits(priv, LS2K300_I2C_SR1, I2C_SR1_ARLO);
273	      return -EAGAIN;
274	    }
275	
276	  if (status & I2C_SR1_AF)
277	    {
278	      i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_STOP);
279	      i2c_clr_bits(priv, LS2K300_I2C_SR1, I2C_SR1_AF);
280	      return -EIO;
281	    }
282	
283	  if (status & I2C_SR1_BERR)
284	    {
285	      i2c_clr_bits(priv, LS2K300_I2C_SR1, I2C_SR1_BERR);
286	      return -EIO;
287	    }
288	
289	  return OK;
290	}
291	
292	static int ls2k300_i2c_send_addr(struct ls2k300_i2c_priv_s *priv,
293	                                 struct i2c_msg_s *msg)
294	{
295	  uint8_t addr;
296	  int ret;
297	
298	  ret = ls2k300_i2c_wait_status(priv, I2C_SR1_SB, true,
299	                                 LS2K300_I2C_TIMEOUT_US);
300	  if (ret < 0)
301	    {
302	      return ret;
303	    }
304	
305	  if (msg->flags & I2C_M_READ)
306	    {
307	      addr = I2C_READADDR8(msg->addr);
308	    }
309	  else
310	    {
311	      addr = I2C_WRITEADDR8(msg->addr);
312	    }
313	
314	  i2c_putreg(priv, LS2K300_I2C_DR, addr);
315	
316	  ret = ls2k300_i2c_wait_status(priv, I2C_SR1_ADDR, true,
317	                                 LS2K300_I2C_TIMEOUT_US);
318	  if (ret < 0)
319	    {
320	      uint32_t sr1 = i2c_getreg(priv, LS2K300_I2C_SR1);
321	      int err = ls2k300_i2c_check_errors(priv, sr1);
322	      return err < 0 ? err : ret;
323	    }
324	
325	  return OK;
326	}
327	
328	static int ls2k300_i2c_read(struct ls2k300_i2c_priv_s *priv,
329	                            struct i2c_msg_s *msg, bool is_last)
330	{
331	  uint32_t count = msg->length;
332	  FAR uint8_t *buf = msg->buffer;
333	  int ret;
334	
335	  if (count == 0)
336	    {
337	      if (is_last)
338	        {
339	          i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_STOP);
340	        }
341	
342	      ls2k300_i2c_clear_addr(priv);
343	      return OK;
344	    }
345	
346	  if (count == 1)
347	    {
348	      i2c_clr_bits(priv, LS2K300_I2C_CR1, I2C_CR1_ACK | I2C_CR1_POS);
349	
350	      ls2k300_i2c_clear_addr(priv);
351	
352	      if (is_last)
353	        {
354	          i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_STOP);
355	        }
356	
357	      ret = ls2k300_i2c_wait_status(priv, I2C_SR1_RXNE, true,
358	                                     LS2K300_I2C_TIMEOUT_US);
359	      if (ret < 0)
360	        {
361	          return ret;
362	        }
363	
364	      *buf = (uint8_t)i2c_getreg(priv, LS2K300_I2C_DR);
365	      return OK;
366	    }
367	
368	  if (count == 2)
369	    {
370	      i2c_clr_bits(priv, LS2K300_I2C_CR1, I2C_CR1_ACK);
371	      i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_POS);
372	
373	      ls2k300_i2c_clear_addr(priv);
374	
375	      while (!(i2c_getreg(priv, LS2K300_I2C_SR1) & I2C_SR1_BTF))
376	        ;
377	
378	      if (is_last)
379	        {
380	          i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_STOP);
381	        }
382	
383	      i2c_clr_bits(priv, LS2K300_I2C_CR1, I2C_CR1_POS);
384	
385	      *buf++ = (uint8_t)i2c_getreg(priv, LS2K300_I2C_DR);
386	      *buf   = (uint8_t)i2c_getreg(priv, LS2K300_I2C_DR);
387	      return OK;
388	    }
389	
390	  i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_ACK);
391	  i2c_clr_bits(priv, LS2K300_I2C_CR1, I2C_CR1_POS);
392	
393	  ls2k300_i2c_clear_addr(priv);
394	
395	  while (count > 3)
396	    {
397	      ret = ls2k300_i2c_wait_status(priv, I2C_SR1_BTF, true,
398	                                     LS2K300_I2C_TIMEOUT_US);
399	      if (ret < 0)
400	        {
401	          return ret;
402	        }
403	
404	      *buf++ = (uint8_t)i2c_getreg(priv, LS2K300_I2C_DR);
405	      count--;
406	    }
407	
408	  ret = ls2k300_i2c_wait_status(priv, I2C_SR1_BTF, true,
409	                                 LS2K300_I2C_TIMEOUT_US);
410	  if (ret < 0)
411	    {
412	      return ret;
413	    }
414	
415	  i2c_clr_bits(priv, LS2K300_I2C_CR1, I2C_CR1_ACK);
416	
417	  (void)i2c_getreg(priv, LS2K300_I2C_SR1);
418	
419	  if (is_last)
420	    {
421	      i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_STOP);
422	    }
423	
424	  *buf++ = (uint8_t)i2c_getreg(priv, LS2K300_I2C_DR);
425	  *buf++ = (uint8_t)i2c_getreg(priv, LS2K300_I2C_DR);
426	  count -= 2;
427	
428	  while (count > 0)
429	    {
430	      ret = ls2k300_i2c_wait_status(priv, I2C_SR1_RXNE, true,
431	                                     LS2K300_I2C_TIMEOUT_US);
432	      if (ret < 0)
433	        {
434	          return ret;
435	        }
436	
437	      *buf++ = (uint8_t)i2c_getreg(priv, LS2K300_I2C_DR);
438	      count--;
439	    }
440	
441	  return OK;
442	}
443	
444	static int ls2k300_i2c_write(struct ls2k300_i2c_priv_s *priv,
445	                             struct i2c_msg_s *msg, bool is_last)
446	{
447	  uint32_t count = msg->length;
448	  FAR uint8_t *buf = msg->buffer;
449	  int ret;
450	  uint32_t sr1;
451	
452	  ls2k300_i2c_clear_addr(priv);
453	
454	  while (count > 0)
455	    {
456	      i2c_putreg(priv, LS2K300_I2C_DR, *buf++);
457	      count--;
458	
459	      if (count == 0)
460	        {
461	          ret = ls2k300_i2c_wait_status(priv, I2C_SR1_BTF, true,
462	                                         LS2K300_I2C_TIMEOUT_US);
463	          if (ret < 0)
464	            {
465	              return ret;
466	            }
467	
468	          if (is_last)
469	            {
470	              i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_STOP);
471	            }
472	        }
473	      else
474	        {
475	          ret = ls2k300_i2c_wait_status(priv, I2C_SR1_TXE, true,
476	                                         LS2K300_I2C_TIMEOUT_US);
477	          if (ret < 0)
478	            {
479	              return ret;
480	            }
481	        }
482	
483	      sr1 = i2c_getreg(priv, LS2K300_I2C_SR1);
484	      ret = ls2k300_i2c_check_errors(priv, sr1);
485	      if (ret < 0)
486	        {
487	          return ret;
488	        }
489	    }
490	
491	  return OK;
492	}
493	
494	static int ls2k300_i2c_transfer_msg(struct ls2k300_i2c_priv_s *priv,
495	                                    struct i2c_msg_s *msg, bool is_last)
496	{
497	  int ret;
498	  uint32_t sr1;
499	
500	  i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_START);
501	
502	  ret = ls2k300_i2c_send_addr(priv, msg);
503	  if (ret < 0)
504	    {
505	      i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_STOP);
506	      return ret;
507	    }
508	
509	  sr1 = i2c_getreg(priv, LS2K300_I2C_SR1);
510	  ret = ls2k300_i2c_check_errors(priv, sr1);
511	  if (ret < 0)
512	    {
513	      i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_STOP);
514	      return ret;
