536	                                struct i2c_msg_s *msgs, int count)
537	{
538	  struct ls2k300_i2c_priv_s *priv =
539	      (struct ls2k300_i2c_priv_s *)dev;
540	  int ret;
541	  int i;
542	
543	  if (count <= 0 || msgs == NULL)
544	    {
545	      return -EINVAL;
546	    }
547	
548	  ret = nxsem_wait(&priv->sem);
549	  if (ret < 0)
550	    {
551	      return ret;
552	    }
553	
554	  if (msgs[0].frequency != priv->frequency)
555	    {
556	      priv->frequency = msgs[0].frequency;
557	      ls2k300_i2c_hw_config(priv);
558	    }
559	
560	  ret = ls2k300_i2c_wait_free_bus(priv);
561	  if (ret < 0)
562	    {
563	      nxsem_post(&priv->sem);
564	      return ret;
565	    }
566	
567	  for (i = 0; i < count; i++)
568	    {
569	      bool is_last = (i == count - 1);
570	
571	      if (msgs[i].flags & I2C_M_NOSTART)
572	        {
573	          continue;
574	        }
575	
576	      ret = ls2k300_i2c_transfer_msg(priv, &msgs[i], is_last);
577	      if (ret < 0)
578	        {
579	          nxsem_post(&priv->sem);
580	          return ret;
581	        }
582	    }
583	
584	  nxsem_post(&priv->sem);
585	  return count;
