      return ret;
    }

  usleep(100000);  /* 100ms for measurement */

  for (i = 0; i < AHT20_MAX_RETRY; i++)
    {
      ret = sensor_i2c_read(AHT20_ADDR, buf, sizeof(buf));
      if (ret < 0)
        {
          /* Sensor may still be measuring (holds SDA low = NACK),
           * wait and retry instead of giving up immediately.
           */

          usleep(20000);
          continue;
        }

      if ((buf[0] & AHT20_STATUS_BUSY) == 0)
        {
