static int aht20_read_temp_humi(int *temp_x100, unsigned int *humi_x100)
{
  uint8_t cmd[] = {AHT20_CMD_TRIGGER, 0x33, 0x00};
  uint8_t buf[AHT20_READ_LEN] = {0};
  uint32_t humi_raw;
  uint32_t temp_raw;
  int ret;
  int i;

  ret = sensor_i2c_write(AHT20_ADDR, cmd, sizeof(cmd));
  if (ret < 0)
    {
      printf("[AHT20] trigger failed\n");
      return ret;
    }

  /* AHT20 holds SDA low during measurement (~80ms).
   * The I2C controller cannot generate START while SDA is held low.
   * Poll with short delays until the sensor releases the bus.
   */

  for (i = 0; i < AHT20_MAX_RETRY; i++)
    {
      usleep(15000);  /* 15ms between attempts */
      ret = sensor_i2c_read(AHT20_ADDR, buf, sizeof(buf));
      if (ret < 0)
        {
          continue;  /* Still measuring, try again */
        }

      if ((buf[0] & AHT20_STATUS_BUSY) == 0)
        {
          break;  /* Data ready */
        }
    }

  if (i >= AHT20_MAX_RETRY)
    {
      printf("[AHT20] read timeout after %d attempts\n", AHT20_MAX_RETRY);
      return -EBUSY;
    }

