71	{
72	    int redOn = 0;
73	    int greenOn = 0;
74	    int blueOn = 0;
75	    unsigned int blueTick = 0;
76	    KeyState key1 = { KEY1_GPIO, IOT_GPIO_VALUE1 };
77	    KeyState key2 = { KEY2_GPIO, IOT_GPIO_VALUE1 };
