85	        KEY1_GPIO, KEY2_GPIO);
86	
87	    InitLedGpio(LED_RED_GPIO);
88	    InitLedGpio(LED_BLUE_GPIO);
89	    InitLedGpio(LED_GREEN_GPIO);
90	    InitKeyGpio(KEY1_GPIO);
91	    InitKeyGpio(KEY2_GPIO);
92	
93	    key1.lastValue = GetKeyValue(KEY1_GPIO);
94	    key2.lastValue = GetKeyValue(KEY2_GPIO);
95	
96	    while (1) {
