109	        blueTick += KEY_SCAN_DELAY_MS;
110	        if (blueTick >= BLUE_BLINK_INTERVAL_MS) {
111	            blueTick = 0;
112	            blueOn = !blueOn;
113	            SetLed(LED_BLUE_GPIO, blueOn);
114	        }
115	
116	        osDelay(KEY_SCAN_DELAY_MS);
117	    }
118	}
