104	              printf("[LED] ERROR: GPIOC_WRITE(1) failed on GPIO%d: %d\n",
105	                     led_pins[j], errno);
106	            }
107	          else
108	            {
109	              printf("[LED] LED OFF (GPIO%d=HIGH)\n", led_pins[j]);
110	            }
111	        }
112	
113	      up_mdelay(500);
114	    }
115	
116	  /* Leave all LEDs OFF */
117	
118	  for (j = 0; j < LED_COUNT; j++)
119	    {
120	      ret = ioctl(fds[j], GPIOC_WRITE, 1);
121	      if (ret < 0)
122	        {
123	          printf("[LED] ERROR: GPIOC_WRITE(1) final failed on GPIO%d: %d\n",
124	                 led_pins[j], errno);
125	        }
126	      else
127	        {
128	          printf("[LED] LED left OFF (GPIO%d=HIGH)\n", led_pins[j]);
129	        }
130	    }
131	
132	cleanup:
133	  for (i = 0; i < ok; i++)
134	    {
135	      close(fds[i]);
136	    }
137	
138	  printf("[LED] Done.\n\n");
139	  return ret < 0 ? ret : OK;
140	}
