94	
95	static int sensor_i2c_write(uint8_t addr, const uint8_t *data, int len)
96	{
97	  struct i2c_msg_s msg;
98	  struct i2c_transfer_s trans;
99	
100	  msg.frequency = I2C_FREQ;
101	  msg.addr      = addr;
102	  msg.flags     = 0;
103	  msg.buffer    = (FAR uint8_t *)data;
104	  msg.length    = len;
105	
106	  trans.msgv = &msg;
107	  trans.msgc = 1;
108	
109	  return ioctl(g_i2c_fd, I2CIOC_TRANSFER, (unsigned long)&trans);
110	}
111	
112	static void sensor_bus_reset(void)
113	{
114	  if (g_i2c_fd >= 0)
115	    {
116	      close(g_i2c_fd);
117	    }
118	
119	  g_i2c_fd = open(I2C1_PATH, O_RDWR);
120	}
121	
122	static int sensor_i2c_read(uint8_t addr, uint8_t *data, int len)
123	{
124	  struct i2c_msg_s msg;
125	  struct i2c_transfer_s trans;
126	
127	  msg.frequency = I2C_FREQ;
128	  msg.addr      = addr;
129	  msg.flags     = I2C_M_READ;
130	  msg.buffer    = data;
131	  msg.length    = len;
132	
133	  trans.msgv = &msg;
134	  trans.msgc = 1;
135	
136	  return ioctl(g_i2c_fd, I2CIOC_TRANSFER, (unsigned long)&trans);
137	}
