139	/****************************************************************************
140	 * Private Functions - BH1750 Light Sensor
141	 ****************************************************************************/
142	
143	static int bh1750_write_cmd(uint8_t cmd)
144	{
145	  return sensor_i2c_write(g_bh1750_addr, &cmd, 1);
146	}
147	
148	static int bh1750_init(void)
149	{
150	  int ret;
151	
152	  /* Try low address first */
153	
154	  g_bh1750_addr = BH1750_ADDR_LOW;
155	  ret = bh1750_write_cmd(BH1750_POWER_ON);
156	  if (ret < 0)
157	    {
158	      printf("[BH1750] probe addr 0x%02x failed\n", BH1750_ADDR_LOW);
159	      g_bh1750_addr = BH1750_ADDR_HIGH;
160	      ret = bh1750_write_cmd(BH1750_POWER_ON);
161	    }
162	
163	  if (ret < 0)
164	    {
165	      printf("[BH1750] probe addr 0x%02x failed\n", BH1750_ADDR_HIGH);
166	      printf("[BH1750] no ACK, check wiring\n");
167	      return ret;
168	    }
169	
170	  printf("[BH1750] detected addr=0x%02x\n", g_bh1750_addr);
171	  usleep(20000);
172	
173	  ret = bh1750_write_cmd(BH1750_RESET);
174	  if (ret < 0)
175	    {
176	      printf("[BH1750] reset failed\n");
177	      return ret;
178	    }
179	  usleep(20000);
180	
181	  ret = bh1750_write_cmd(BH1750_H_MODE);
182	  if (ret < 0)
183	    {
184	      printf("[BH1750] set H-mode failed\n");
185	      return ret;
186	    }
187	  usleep(180000);
188	
189	  printf("[BH1750] init OK\n");
190	  return OK;
191	}
192	
193	static int bh1750_read_lux(unsigned int *lux_x100)
194	{
195	  uint8_t buf[2] = {0};
196	  int ret;
197	  unsigned int raw;
198	
199	  ret = sensor_i2c_read(g_bh1750_addr, buf, 2);
200	  if (ret < 0)
201	    {
202	      printf("[BH1750] read failed: %d\n", ret);
203	      return ret;
204	    }
205	
206	  raw = ((unsigned int)buf[0] << 8) | buf[1];
207	  *lux_x100 = (raw * 1000 + 6) / 12;
208	
209	  return OK;
210	}
