212	/****************************************************************************
213	 * Private Functions - AHT20 Temperature/Humidity Sensor
214	 ****************************************************************************/
215	
216	static int aht20_write_cmd(uint8_t cmd)
217	{
218	  return sensor_i2c_write(AHT20_ADDR, &cmd, 1);
219	}
220	
221	static int aht20_read_status(uint8_t *status)
222	{
223	  int ret;
224	
225	  ret = aht20_write_cmd(AHT20_CMD_STATUS);
226	  if (ret < 0)
227	    {
228	      printf("[AHT20] write status cmd failed\n");
229	      return ret;
230	    }
231	
232	  ret = sensor_i2c_read(AHT20_ADDR, status, 1);
233	  if (ret < 0)
234	    {
235	      printf("[AHT20] read status failed\n");
236	      return ret;
237	    }
238	
239	  return OK;
240	}
241	
242	static int aht20_calibrate(void)
243	{
244	  uint8_t status = 0;
245	  int ret;
246	
247	  ret = aht20_read_status(&status);
248	  if (ret < 0)
249	    {
250	      return ret;
251	    }
252	
253	  if ((status & AHT20_STATUS_CALIB) != 0)
254	    {
255	      return OK;
256	    }
257	
258	  ret = aht20_write_cmd(AHT20_CMD_RESET);
259	  if (ret < 0)
260	    {
261	      printf("[AHT20] reset failed\n");
262	      return ret;
263	    }
264	  usleep(200000);
265	
266	  /* Send calibrate command: 0xBE 0x08 0x00 (single transaction) */
267	
268	  {
269	    uint8_t cal_cmd[] = {AHT20_CMD_CALIBRATE, 0x08, 0x00};
270	    ret = sensor_i2c_write(AHT20_ADDR, cal_cmd, sizeof(cal_cmd));
271	  }
272	  if (ret < 0)
273	    {
274	      printf("[AHT20] calibrate cmd failed\n");
275	      return ret;
276	    }
277	  usleep(400000);
278	
279	  ret = aht20_read_status(&status);
280	  if (ret < 0)
281	    {
282	      return ret;
283	    }
284	
285	  if ((status & AHT20_STATUS_CALIB) == 0)
286	    {
287	      printf("[AHT20] calibrate failed status=0x%02x\n", status);
288	      return -EIO;
289	    }
290	
291	  return OK;
292	}
293	
294	static int aht20_init(void)
295	{
296	  int ret;
297	
298	  usleep(200000);
299	
300	  ret = aht20_calibrate();
301	  if (ret < 0)
302	    {
303	      printf("[AHT20] init failed, check wiring addr=0x%02x\n", AHT20_ADDR);
304	      return ret;
305	    }
306	
307	  printf("[AHT20] detected addr=0x%02x, init OK\n", AHT20_ADDR);
308	  return OK;
309	}
310	
311	static int aht20_read_temp_humi(int *temp_x100, unsigned int *humi_x100)
312	{
313	  uint8_t cmd[3] = {AHT20_CMD_TRIGGER, 0x33, 0x00};
314	  uint8_t buf[AHT20_READ_LEN] = {0};
315	  uint32_t humi_raw;
316	  uint32_t temp_raw;
317	  int ret;
318	  int i;
319	
320	  /* Send trigger command: 0xAC 0x33 0x00 (must be single transaction) */
321	
322	  ret = sensor_i2c_write(AHT20_ADDR, cmd, 3);
323	  if (ret < 0)
324	    {
325	      printf("[AHT20] trigger failed\n");
326	      return ret;
327	    }
328	
329	  /* AHT20 holds SDA low during measurement (~80ms).
330	   * Wait first, then poll if still busy.
331	   */
332	
333	  usleep(80000);  /* 80ms for measurement, same as demo */
334	
335	  for (i = 0; i < AHT20_MAX_RETRY; i++)
336	    {
337	      ret = sensor_i2c_read(AHT20_ADDR, buf, sizeof(buf));
338	      if (ret < 0)
339	        {
340	          usleep(10000);  /* 10ms retry delay */
341	          continue;  /* Still measuring, retry */
342	        }
343	      ret = sensor_i2c_read(AHT20_ADDR, buf, sizeof(buf));
344	      if (ret < 0)
345	        {
346	          continue;  /* Still measuring, retry */
347	        }
348	
349	      if ((buf[0] & AHT20_STATUS_BUSY) == 0)
350	        {
351	          break;  /* Data ready */
352	        }
353	    }
354	
355	  if (ret < 0)
356	    {
357	      printf("[AHT20] read timeout\n");
358	      return ret;
359	    }
360	
361	  if (i >= AHT20_MAX_RETRY)
362	    {
363	      printf("[AHT20] device busy status=0x%02x\n", buf[0]);
364	      return -EBUSY;
365	    }
366	
367	  humi_raw = ((uint32_t)buf[1] << 12) |
368	             ((uint32_t)buf[2] << 4)  |
369	             ((uint32_t)buf[3] >> 4);
370	  temp_raw = (((uint32_t)buf[3] & 0x0F) << 16) |
371	             ((uint32_t)buf[4] << 8) |
372	             buf[5];
373	
374	  *humi_x100 = (unsigned int)(((uint64_t)humi_raw * 10000U) /
375	                AHT20_RESOLUTION);
376	  *temp_x100 = (int)(((uint64_t)temp_raw * 20000U) /
377	                AHT20_RESOLUTION) - 5000;
378	
379	  return OK;
380	}
