406	static int oled_init_device(void)
407	{
408	  static const uint8_t init_cmds[] =
409	  {
410	    0xae, 0x00, 0x10, 0x40, 0xb0, 0x81, 0xff, 0xa1,
411	    0xa6, 0xa8, 0x3f, 0xc8, 0xd3, 0x00, 0xd5, 0x80,
412	    0xd8, 0x05, 0xd9, 0xf1, 0xda, 0x12, 0xdb, 0x30,
413	    0x8d, 0x14, 0xaf,
