438	static void oled_fill_screen(uint8_t fill)
439	{
440	  uint8_t page;
441	  uint8_t col;
442	
443	  for (page = 0; page < OLED_PAGES; page++)
444	    {
445	      oled_set_position(0, page);
446	      for (col = 0; col < OLED_WIDTH; col++)
447	        {
448	          oled_write_data(fill);
449	        }
450	    }
451	}
