453	static void oled_show_char(uint8_t x, uint8_t y, char ch, oled_font_e font)
454	{
455	  uint8_t c;
456	  uint8_t i;
457	
458	  if (ch < ' ' || ch > '~')
459	    {
460	      ch = ' ';
461	    }
462	
463	  c = (uint8_t)(ch - ' ');
464	
465	  if (font == FONT8X16)
466	    {
467	      oled_set_position(x, y);
468	      for (i = 0; i < 8; i++)
469	        {
470	          oled_write_data(F8X16[c * 16 + i]);
471	        }
472	
473	      oled_set_position(x, y + 1);
474	      for (i = 0; i < 8; i++)
475	        {
476	          oled_write_data(F8X16[c * 16 + 8 + i]);
477	        }
478	    }
479	  else
480	    {
481	      oled_set_position(x, y);
482	      for (i = 0; i < 6; i++)
483	        {
484	          oled_write_data(F6x8[c][i]);
485	        }
486	    }
487	}
488	
489	static void oled_show_string(uint8_t x, uint8_t y,
490	                             const char *str, oled_font_e font)
491	{
492	  uint8_t step = (font == FONT8X16) ? 8 : 6;
493	
494	  if (str == NULL)
495	    {
496	      return;
497	    }
498	
499	  while (*str != '\0')
500	    {
501	      oled_show_char(x, y, *str, font);
502	      x += step;
503	      if (x > (OLED_WIDTH - step))
504	        {
505	          x = 0;
506	          y += (font == FONT8X16) ? 2 : 1;
507	          if (y >= OLED_PAGES)
508	            {
509	              break;
510	            }
511	        }
512	
513	      str++;
514	    }
515	}
