564	/****************************************************************************
565	 * Public Functions
566	 ****************************************************************************/
567	
568	int test_sensor_oled(void)
569	{
570	  int temp_x100 = 0;
571	  unsigned int humi_x100 = 0;
572	  unsigned int lux_x100 = 0;
573	  int bh1750_ok = 0;
574	  int aht20_ok = 0;
575	  int oled_ok = 0;
576	  int ret;
577	  int loop_count = 0;
578	
579	  printf("[SENSOR] === BH1750 + AHT20 + OLED Test ===\n");
580	  printf("[SENSOR] I2C1: SCL=GPIO50 SDA=GPIO51\n");
581	  printf("[SENSOR] Devices: BH1750(0x23/0x5C) AHT20(0x38) OLED(0x3C)\n\n");
582	
583	  /* Open I2C1 */
584	
585	  printf("[SENSOR] Opening %s...\n", I2C1_PATH);
586	  g_i2c_fd = open(I2C1_PATH, O_RDWR);
587	  if (g_i2c_fd < 0)
588	    {
589	      printf("[SENSOR] ERROR: open %s failed: errno=%d\n",
590	             I2C1_PATH, errno);
591	      return -errno;
592	    }
593	
594	  printf("[SENSOR] I2C1 opened, fd=%d\n\n", g_i2c_fd);
595	
596	  /* Initialize BH1750 */
597	
598	  printf("[SENSOR] Init BH1750...\n");
599	  ret = bh1750_init();
600	  if (ret < 0)
601	    {
602	      printf("[SENSOR] BH1750 init FAILED (will skip light readings)\n\n");
603	    }
604	  else
605	    {
606	      bh1750_ok = 1;
607	    }
608	
609	  /* Initialize AHT20 */
610	
611	  printf("[SENSOR] Init AHT20...\n");
612	  ret = aht20_init();
613	  if (ret < 0)
614	    {
615	      printf("[SENSOR] AHT20 init FAILED (will skip temp/humi readings)\n\n");
616	    }
617	  else
618	    {
619	      aht20_ok = 1;
620	    }
621	
622	  /* Initialize OLED */
623	
624	  printf("[SENSOR] Init OLED...\n");
625	  ret = oled_init_device();
626	  if (ret < 0)
627	    {
628	      printf("[SENSOR] OLED init FAILED\n");
629	      close(g_i2c_fd);
630	      return ret;
631	    }
632	  oled_ok = 1;
633	
634	  /* Show initial screen */
635	
636	  oled_fill_screen(0x00);
637	  oled_show_string(16, 0, "Loong Hat", FONT8X16);
638	  oled_show_string(0, 3, "Sensors Ready", FONT8X16);
639	  usleep(1000000);
640	
641	  /* Main loop - matching HarmonyOS demo approach:
642	   * Read AHT20 → display on OLED → wait → repeat.
643	   * No bus recovery, no extra delays between devices.
644	   */
645	
646	  printf("\n[SENSOR] Starting sensor loop (every %d sec)...\n\n",
647	         SENSOR_INTERVAL_SEC);
648	
649	  while (loop_count < 30)
650	    {
651	      temp_x100 = 0;
652	      humi_x100 = 0;
653	      lux_x100 = 0;
654	
655	      /* Reset bus before AHT20 (NuttX driver needs this, unlike HarmonyOS) */
656	
657	      sensor_bus_reset();
658	      usleep(100000);
659	
660	      /* Read AHT20 */
661	
662	      if (aht20_ok)
