/****************************************************************************
 * apps/examples/ls_driver_test/test_sensor_oled.c
 *
 * BH1750 light sensor + SSD1306 OLED display
 * Ported from HarmonyOS loong_hat demo for NuttX.
 *
 * Hardware (LOONG-HAT):
 *   - I2C1 SCL: GPIO50, SDA: GPIO51
 *   - BH1750 addr: 0x23 (or 0x5C)
 *   - OLED   addr: 0x3C
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/ioctl.h>
#include <stdio.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <string.h>
#include <stdint.h>

#include <nuttx/i2c/i2c_master.h>

#include "ls_driver_test.h"
#include "oled_fonts.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define I2C1_PATH           "/dev/i2c1"
#define I2C_FREQ            I2C_SPEED_STANDARD

/* BH1750 definitions */

#define BH1750_ADDR_LOW     0x23
#define BH1750_ADDR_HIGH    0x5c
#define BH1750_POWER_ON     0x01
#define BH1750_RESET        0x07
#define BH1750_H_MODE       0x10

/* OLED definitions */

#define OLED_ADDR           0x3c
#define OLED_WIDTH          128
#define OLED_PAGES          8
#define OLED_I2C_CMD        0x00
#define OLED_I2C_DATA       0x40

/* Display update interval (seconds) */

#define SENSOR_INTERVAL_SEC 2

/****************************************************************************
 * Private Types
 ****************************************************************************/

typedef enum
{
  FONT6X8 = 1,
  FONT8X16,
} oled_font_e;

/****************************************************************************
 * Private Data
 ****************************************************************************/

static int g_i2c_fd = -1;
static uint8_t g_bh1750_addr = BH1750_ADDR_LOW;

/****************************************************************************
 * Private Functions - I2C Helper
 ****************************************************************************/

static int sensor_i2c_write(uint8_t addr, const uint8_t *data, int len)
{
  struct i2c_msg_s msg;
  struct i2c_transfer_s trans;

  msg.frequency = I2C_FREQ;
  msg.addr      = addr;
  msg.flags     = 0;
  msg.buffer    = (FAR uint8_t *)data;
  msg.length    = len;

  trans.msgv = &msg;
  trans.msgc = 1;

  return ioctl(g_i2c_fd, I2CIOC_TRANSFER, (unsigned long)&trans);
}

static int sensor_i2c_read(uint8_t addr, uint8_t *data, int len)
{
  struct i2c_msg_s msg;
  struct i2c_transfer_s trans;

  msg.frequency = I2C_FREQ;
  msg.addr      = addr;
  msg.flags     = I2C_M_READ;
  msg.buffer    = data;
  msg.length    = len;

  trans.msgv = &msg;
  trans.msgc = 1;

  return ioctl(g_i2c_fd, I2CIOC_TRANSFER, (unsigned long)&trans);
}

/****************************************************************************
 * Private Functions - BH1750 Light Sensor
 ****************************************************************************/

static int bh1750_write_cmd(uint8_t cmd)
{
  return sensor_i2c_write(g_bh1750_addr, &cmd, 1);
}

static int bh1750_init(void)
{
  int ret;

  /* Try low address first */

  g_bh1750_addr = BH1750_ADDR_LOW;
  ret = bh1750_write_cmd(BH1750_POWER_ON);
  if (ret < 0)
    {
      printf("[BH1750] probe addr 0x%02x failed\n", BH1750_ADDR_LOW);
      g_bh1750_addr = BH1750_ADDR_HIGH;
      ret = bh1750_write_cmd(BH1750_POWER_ON);
    }

  if (ret < 0)
    {
      printf("[BH1750] probe addr 0x%02x failed\n", BH1750_ADDR_HIGH);
      printf("[BH1750] no ACK, check wiring\n");
      return ret;
    }

  printf("[BH1750] detected addr=0x%02x\n", g_bh1750_addr);
  usleep(20000);

  ret = bh1750_write_cmd(BH1750_RESET);
  if (ret < 0)
    {
      printf("[BH1750] reset failed\n");
      return ret;
    }
  usleep(20000);

  ret = bh1750_write_cmd(BH1750_H_MODE);
  if (ret < 0)
    {
      printf("[BH1750] set H-mode failed\n");
      return ret;
    }
  usleep(180000);

  printf("[BH1750] init OK\n");
  return OK;
}

static int bh1750_read_lux(unsigned int *lux_x100)
{
  uint8_t buf[2] = {0};
  int ret;
  unsigned int raw;

  ret = sensor_i2c_read(g_bh1750_addr, buf, 2);
  if (ret < 0)
    {
      printf("[BH1750] read failed: %d\n", ret);
      return ret;
    }

  raw = ((unsigned int)buf[0] << 8) | buf[1];
  *lux_x100 = (raw * 1000 + 6) / 12;

  return OK;
}

/****************************************************************************
 * Private Functions - OLED Display
 ****************************************************************************/

static int oled_write_byte(uint8_t reg, uint8_t data)
{
  uint8_t buf[2];

  buf[0] = reg;
  buf[1] = data;

  return sensor_i2c_write(OLED_ADDR, buf, 2);
}

static int oled_write_cmd(uint8_t cmd)
{
  return oled_write_byte(OLED_I2C_CMD, cmd);
}

static int oled_write_data(uint8_t data)
{
  return oled_write_byte(OLED_I2C_DATA, data);
}

static int oled_init_device(void)
{
  static const uint8_t init_cmds[] =
  {
    0xae, 0x00, 0x10, 0x40, 0xb0, 0x81, 0xff, 0xa1,
    0xa6, 0xa8, 0x3f, 0xc8, 0xd3, 0x00, 0xd5, 0x80,
    0xd8, 0x05, 0xd9, 0xf1, 0xda, 0x12, 0xdb, 0x30,
    0x8d, 0x14, 0xaf,
  };
  int i;

  for (i = 0; i < (int)(sizeof(init_cmds) / sizeof(init_cmds[0])); i++)
    {
      int ret = oled_write_cmd(init_cmds[i]);
      if (ret < 0)
        {
          printf("[OLED] init cmd 0x%02x failed: %d\n", init_cmds[i], ret);
          return ret;
        }
    }

  printf("[OLED] init OK\n");
  return OK;
}

static void oled_set_position(uint8_t x, uint8_t y)
{
  oled_write_cmd(0xb0 + y);
  oled_write_cmd(x & 0x0f);
  oled_write_cmd(((x & 0xf0) >> 4) | 0x10);
}

static void oled_fill_screen(uint8_t fill)
{
  uint8_t page;
  uint8_t col;

  for (page = 0; page < OLED_PAGES; page++)
    {
      oled_set_position(0, page);
      for (col = 0; col < OLED_WIDTH; col++)
        {
          oled_write_data(fill);
        }
    }
}

static void oled_show_char(uint8_t x, uint8_t y, char ch, oled_font_e font)
{
  uint8_t c;
  uint8_t i;

  if (ch < ' ' || ch > '~')
    {
      ch = ' ';
    }

  c = (uint8_t)(ch - ' ');

  if (font == FONT8X16)
    {
      oled_set_position(x, y);
      for (i = 0; i < 8; i++)
        {
          oled_write_data(F8X16[c * 16 + i]);
        }

      oled_set_position(x, y + 1);
      for (i = 0; i < 8; i++)
        {
          oled_write_data(F8X16[c * 16 + 8 + i]);
        }
    }
  else
    {
      oled_set_position(x, y);
      for (i = 0; i < 6; i++)
        {
          oled_write_data(F6x8[c][i]);
        }
    }
}

static void oled_show_string(uint8_t x, uint8_t y,
                             const char *str, oled_font_e font)
{
  uint8_t step = (font == FONT8X16) ? 8 : 6;

  if (str == NULL)
    {
      return;
    }

  while (*str != '\0')
    {
      oled_show_char(x, y, *str, font);
      x += step;
      if (x > (OLED_WIDTH - step))
        {
          x = 0;
          y += (font == FONT8X16) ? 2 : 1;
          if (y >= OLED_PAGES)
            {
              break;
            }
        }

      str++;
    }
}

/****************************************************************************
 * Private Functions - Display Helpers
 ****************************************************************************/

static void format_lux(char *buf, size_t len, unsigned int lux_x100)
{
  snprintf(buf, len, "Lux: %u.%02u", lux_x100 / 100, lux_x100 % 100);
}

static void oled_show_light_data(unsigned int lux_x100)
{
  char line[22];

  format_lux(line, sizeof(line), lux_x100);

  oled_fill_screen(0x00);
  oled_show_string(16, 0, "Loong Hat", FONT8X16);
  oled_show_string(0, 3, line, FONT8X16);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int test_sensor_oled(void)
{
  unsigned int lux_x100 = 0;
  int bh1750_ok = 0;
  int oled_ok = 0;
  int ret;
  int loop_count = 0;

  printf("[SENSOR] === BH1750 + OLED Test ===\n");
  printf("[SENSOR] I2C1: SCL=GPIO50 SDA=GPIO51\n");
  printf("[SENSOR] Devices: BH1750(0x23/0x5C) OLED(0x3C)\n\n");

  /* Open I2C1 */

  printf("[SENSOR] Opening %s...\n", I2C1_PATH);
  g_i2c_fd = open(I2C1_PATH, O_RDWR);
  if (g_i2c_fd < 0)
    {
      printf("[SENSOR] ERROR: open %s failed: errno=%d\n",
             I2C1_PATH, errno);
      return -errno;
    }

  printf("[SENSOR] I2C1 opened, fd=%d\n\n", g_i2c_fd);

  /* Initialize BH1750 */

  printf("[SENSOR] Init BH1750...\n");
  ret = bh1750_init();
  if (ret < 0)
    {
      printf("[SENSOR] BH1750 init FAILED (will skip light readings)\n\n");
    }
  else
    {
      bh1750_ok = 1;
    }

  /* Initialize OLED */

  printf("[SENSOR] Init OLED...\n");
  ret = oled_init_device();
  if (ret < 0)
    {
      printf("[SENSOR] OLED init FAILED\n");
      close(g_i2c_fd);
      return ret;
    }
  oled_ok = 1;

  /* Show initial screen */

  oled_fill_screen(0x00);
  oled_show_string(16, 0, "Loong Hat", FONT8X16);
  oled_show_string(0, 3, "Sensor Ready", FONT8X16);
  usleep(1000000);

  /* Main loop */

  printf("\n[SENSOR] Starting sensor loop (every %d sec)...\n\n",
         SENSOR_INTERVAL_SEC);

  while (loop_count < 30)
    {
      lux_x100 = 0;

      /* Read BH1750 */

      if (bh1750_ok)
        {
          ret = bh1750_read_lux(&lux_x100);
          if (ret < 0)
            {
              printf("[BH1750] read failed, reinit...\n");
              usleep(500000);
              bh1750_ok = (bh1750_init() == 0);
            }
          else
            {
              printf("[BH1750] light = %u.%02u lux\n",
                     lux_x100 / 100, lux_x100 % 100);
            }
        }

      /* Update OLED */

      if (oled_ok)
        {
          oled_show_light_data(lux_x100);
        }

      loop_count++;
      printf("[SENSOR] --- loop %d done ---\n", loop_count);
      sleep(SENSOR_INTERVAL_SEC);
    }

  /* Cleanup */

  if (oled_ok)
    {
      oled_fill_screen(0x00);
      oled_show_string(0, 3, "  Test Done!", FONT8X16);
    }

  printf("\n[SENSOR] Test complete (%d iterations)\n", loop_count);
  close(g_i2c_fd);
  g_i2c_fd = -1;

  return OK;
}

/****************************************************************************
 * apps/examples/ls_driver_test/test_key.c
 *
 * Key + LED test, ported from HarmonyOS loong_hat 02_KEY demo.
 *
 * Function:
 *   - KEY1 (GPIO87) toggles red LED   (GPIO72)
 *   - KEY2 (GPIO86) toggles green LED (GPIO73)
 *   - Blue LED (GPIO88) blinks every 500ms
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/ioctl.h>
#include <stdbool.h>
#include <stdio.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>

#include <nuttx/arch.h>
#include <nuttx/ioexpander/gpio.h>

#include "ls_driver_test.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define LED_RED_GPIO            72
#define LED_BLUE_GPIO           88
#define LED_GREEN_GPIO          73
#define KEY1_GPIO               87
#define KEY2_GPIO               86

#define KEY_SCAN_DELAY_MS       10
#define KEY_DEBOUNCE_MS         20
#define BLUE_BLINK_INTERVAL_MS  500
#define KEY_TEST_DURATION_MS    30000

/****************************************************************************
 * Private Types
 ****************************************************************************/

typedef struct
{
  int fd;
  bool last_value;
} key_state_s;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static int init_led_gpio(int gpio)
{
  int ret;
  char path[32];
  int fd;

  ret = pinctrl_set_gpio_function(gpio);
  if (ret < 0)
    {
      printf("[KEY] ERROR: pinctrl failed for GPIO%d\n", gpio);
      return ret;
    }

  snprintf(path, sizeof(path), "/dev/gpio%d", gpio);
  fd = open(path, O_RDWR);
  if (fd < 0)
    {
      printf("[KEY] ERROR: open %s failed: %d\n", path, errno);
      return -errno;
    }

  ret = ioctl(fd, GPIOC_SETPINTYPE, (unsigned long)GPIO_OUTPUT_PIN);
  if (ret < 0)
    {
      printf("[KEY] ERROR: GPIOC_SETPINTYPE(OUTPUT) on GPIO%d: %d\n",
             gpio, errno);
      close(fd);
      return -errno;
    }

  /* LED off (high = off for active-low) */

  ioctl(fd, GPIOC_WRITE, 1);
  return fd;
}

static int init_key_gpio(int gpio)
{
  int ret;
  char path[32];
  int fd;

  ret = pinctrl_set_gpio_function(gpio);
  if (ret < 0)
    {
      printf("[KEY] ERROR: pinctrl failed for GPIO%d\n", gpio);
      return ret;
    }

  snprintf(path, sizeof(path), "/dev/gpio%d", gpio);
  fd = open(path, O_RDWR);
  if (fd < 0)
    {
      printf("[KEY] ERROR: open %s failed: %d\n", path, errno);
      return -errno;
    }

  ret = ioctl(fd, GPIOC_SETPINTYPE, (unsigned long)GPIO_INPUT_PIN);
  if (ret < 0)
    {
      printf("[KEY] ERROR: GPIOC_SETPINTYPE(INPUT) on GPIO%d: %d\n",
             gpio, errno);
      close(fd);
      return -errno;
    }

  return fd;
}

static bool get_key_value(int fd)
{
  bool value = true;

  ioctl(fd, GPIOC_READ, (unsigned long)(uintptr_t)&value);
  return value;
}

static int is_key_pressed(key_state_s *key)
{
  bool value = get_key_value(key->fd);

  /* Detect falling edge: HIGH -> LOW = press */

  if (!value && key->last_value)
    {
      up_mdelay(KEY_DEBOUNCE_MS);
      value = get_key_value(key->fd);
      if (!value)
        {
          key->last_value = value;
          return 1;
        }
    }

  key->last_value = value;
  return 0;
}

static void set_led(int fd, int on)
{
  /* Active-low: 0 = ON, 1 = OFF */

  ioctl(fd, GPIOC_WRITE, on ? 0 : 1);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int test_key(void)
{
  int fd_red;
  int fd_blue;
  int fd_green;
  int fd_key1;
  int fd_key2;
  key_state_s key1;
  key_state_s key2;
  int red_on = 0;
  int green_on = 0;
  int blue_on = 0;
  unsigned int blue_tick = 0;
  unsigned int total_tick = 0;

  printf("[KEY] === Key + LED Test (loong_hat 02_KEY) ===\n");
  printf("[KEY] KEY1(GPIO%d) -> toggle red LED(GPIO%d)\n",
         KEY1_GPIO, LED_RED_GPIO);
  printf("[KEY] KEY2(GPIO%d) -> toggle green LED(GPIO%d)\n",
         KEY2_GPIO, LED_GREEN_GPIO);
  printf("[KEY] Blue LED(GPIO%d) blinks every %dms\n",
         LED_BLUE_GPIO, BLUE_BLINK_INTERVAL_MS);
  printf("[KEY] Test duration: %d seconds\n\n",
         KEY_TEST_DURATION_MS / 1000);

  /* Initialize LEDs */

  fd_red = init_led_gpio(LED_RED_GPIO);
  if (fd_red < 0)
    {
      return fd_red;
    }

  fd_blue = init_led_gpio(LED_BLUE_GPIO);
  if (fd_blue < 0)
    {
      close(fd_red);
      return fd_blue;
    }

  fd_green = init_led_gpio(LED_GREEN_GPIO);
  if (fd_green < 0)
    {
      close(fd_red);
      close(fd_blue);
      return fd_green;
    }

  /* Initialize keys */

  fd_key1 = init_key_gpio(KEY1_GPIO);
  if (fd_key1 < 0)
    {
      close(fd_red);
      close(fd_blue);
      close(fd_green);
      return fd_key1;
    }

  fd_key2 = init_key_gpio(KEY2_GPIO);
  if (fd_key2 < 0)
    {
      close(fd_red);
      close(fd_blue);
      close(fd_green);
      close(fd_key1);
      return fd_key2;
    }

  /* Read initial key states */

  key1.fd = fd_key1;
  key1.last_value = get_key_value(fd_key1);
  key2.fd = fd_key2;
  key2.last_value = get_key_value(fd_key2);

  printf("[KEY] Initial: KEY1=%s KEY2=%s\n",
         key1.last_value ? "HIGH" : "LOW",
         key2.last_value ? "HIGH" : "LOW");
  printf("[KEY] Ready. Press keys to test...\n\n");

  /* Main loop - scan keys, blink blue LED */

  while (total_tick < KEY_TEST_DURATION_MS)
    {
      /* Check KEY1 - toggle red LED */

      if (is_key_pressed(&key1))
        {
          red_on = !red_on;
          set_led(fd_red, red_on);
          printf("[KEY] KEY1 pressed, red %s\n",
                 red_on ? "ON" : "OFF");
        }

      /* Check KEY2 - toggle green LED */

      if (is_key_pressed(&key2))
        {
          green_on = !green_on;
          set_led(fd_green, green_on);
          printf("[KEY] KEY2 pressed, green %s\n",
                 green_on ? "ON" : "OFF");
        }

      /* Blink blue LED */

      blue_tick += KEY_SCAN_DELAY_MS;
      if (blue_tick >= BLUE_BLINK_INTERVAL_MS)
        {
          blue_tick = 0;
          blue_on = !blue_on;
          set_led(fd_blue, blue_on);
        }

      up_mdelay(KEY_SCAN_DELAY_MS);
      total_tick += KEY_SCAN_DELAY_MS;
    }

  /* Turn off all LEDs */

  set_led(fd_red, 0);
  set_led(fd_green, 0);
  set_led(fd_blue, 0);

  printf("\n[KEY] Test complete. All LEDs off.\n");

  close(fd_key2);
  close(fd_key1);
  close(fd_green);
  close(fd_blue);
  close(fd_red);

  return OK;
}

