35	#define BREATH_LED_GPIO        72
36	#define BREATH_TASK_STACK_SIZE 2048
37	#define BREATH_TASK_PRIORITY   osPriorityNormal
38	#define BREATH_PWM_PERIOD_US   2000
39	#define BREATH_STEP_PERCENT    2
40	#define BREATH_STEP_CYCLES     6
41	
42	/*
43	 * LOONG-HAT Servo Connector signals are routed through the 40-pin header:
44	 * HAT GPIO11 -> 40-pin 38 -> LS2K300 GPIO62
45	 * HAT GPIO6  -> 40-pin 40 -> LS2K300 GPIO60
46	 * HAT GPIO61 -> 40-pin 15 -> LS2K300 GPIO81
47	 * HAT GPIO63 -> 40-pin 16 -> LS2K300 GPIO70
48	 */
49	static const unsigned int g_servoGpios[] = {
50	    62,
51	    60,
52	    81,
53	    70,
54	};
55	
56	static void BlueLedInit(void)
57	{
58	    (void)ls_pinmux_pin_setup(BLUE_LED_GPIO, LS_PINMUX_MODE_AS_GPIO);
59	    (void)IoTGpioInit(BLUE_LED_GPIO);
60	    (void)IoTGpioSetDir(BLUE_LED_GPIO, IOT_GPIO_DIR_OUT);
61	    (void)IoTGpioSetOutputVal(BLUE_LED_GPIO, IOT_GPIO_VALUE1);
62	}
63	
64	static void BreathLedInit(void)
65	{
66	    (void)ls_pinmux_pin_setup(BREATH_LED_GPIO, LS_PINMUX_MODE_AS_GPIO);
67	    (void)IoTGpioInit(BREATH_LED_GPIO);
68	    (void)IoTGpioSetDir(BREATH_LED_GPIO, IOT_GPIO_DIR_OUT);
69	    (void)IoTGpioSetOutputVal(BREATH_LED_GPIO, IOT_GPIO_VALUE0);
70	}
71	
72	static void TaskYield(void)
73	{
74	    (void)osThreadYield();
75	}
76	
77	static void BreathLedOutputDuty(uint32_t dutyPercent)
78	{
79	    uint32_t highUs;
80	
81	    if (dutyPercent == 0) {
82	        (void)IoTGpioSetOutputVal(BREATH_LED_GPIO, IOT_GPIO_VALUE0);
83	        LOS_UDelay(BREATH_PWM_PERIOD_US);
84	        TaskYield();
85	        return;
86	    }
87	
88	    if (dutyPercent >= 100) {
89	        (void)IoTGpioSetOutputVal(BREATH_LED_GPIO, IOT_GPIO_VALUE1);
90	        LOS_UDelay(BREATH_PWM_PERIOD_US);
91	        TaskYield();
92	        return;
93	    }
94	
95	    highUs = (BREATH_PWM_PERIOD_US * dutyPercent) / 100;
96	    (void)IoTGpioSetOutputVal(BREATH_LED_GPIO, IOT_GPIO_VALUE1);
97	    LOS_UDelay(highUs);
98	    (void)IoTGpioSetOutputVal(BREATH_LED_GPIO, IOT_GPIO_VALUE0);
99	    LOS_UDelay(BREATH_PWM_PERIOD_US - highUs);
100	    TaskYield();
101	}
102	
103	static void BreathLedHoldDuty(uint32_t dutyPercent)
104	{
105	    for (uint32_t i = 0; i < BREATH_STEP_CYCLES; i++) {
106	        BreathLedOutputDuty(dutyPercent);
107	    }
108	}
109	
110	static void BreathLedTask(void *arg)
111	{
112	    (void)arg;
113	
114	    printf("[LOONG-HAT-PWM] breath LED GPIO%d software PWM start\r\n", BREATH_LED_GPIO);
115	    BreathLedInit();
116	
117	    while (1) {
118	        for (uint32_t duty = 0; duty <= 100; duty += BREATH_STEP_PERCENT) {
119	            BreathLedHoldDuty(duty);
120	        }
121	
122	        for (uint32_t duty = 100; duty > 0; duty -= BREATH_STEP_PERCENT) {
123	            BreathLedHoldDuty(duty);
124	        }
125	    }
126	}
127	
128	static void ServoGpioInit(void)
129	{
130	    for (uint32_t i = 0; i < sizeof(g_servoGpios) / sizeof(g_servoGpios[0]); i++) {
131	        (void)ls_pinmux_pin_setup(g_servoGpios[i], LS_PINMUX_MODE_AS_GPIO);
132	        (void)IoTGpioInit(g_servoGpios[i]);
133	        (void)IoTGpioSetDir(g_servoGpios[i], IOT_GPIO_DIR_OUT);
134	        (void)IoTGpioSetOutputVal(g_servoGpios[i], IOT_GPIO_VALUE0);
135	    }
136	}
137	
138	static void ServoSetOutput(IotGpioValue value)
139	{
140	    for (uint32_t i = 0; i < sizeof(g_servoGpios) / sizeof(g_servoGpios[0]); i++) {
141	        (void)IoTGpioSetOutputVal(g_servoGpios[i], value);
142	    }
143	}
144	
145	static void ServoOutputPulse(uint16_t pulseUs)
146	{
147	    ServoSetOutput(IOT_GPIO_VALUE1);
148	    LOS_UDelay(pulseUs);
149	    ServoSetOutput(IOT_GPIO_VALUE0);
150	    LOS_UDelay(SERVO_PERIOD_US - pulseUs);
151	    TaskYield();
152	}
153	
154	static void ServoHoldPulse(uint16_t pulseUs, uint32_t cycles)
155	{
156	    printf("[LOONG-HAT-PWM] servo pulse %uus\r\n", pulseUs);
157	
158	    for (uint32_t i = 0; i < cycles; i++) {
159	        ServoOutputPulse(pulseUs);
160	    }
161	}
162	
163	static void ServoTask(void *arg)
164	{
165	    (void)arg;
166	
167	    printf("[LOONG-HAT-PWM] servo loop demo start\r\n");
168	    printf("[LOONG-HAT-PWM] blue LED GPIO%d power indicator on\r\n", BLUE_LED_GPIO);
169	    printf("[LOONG-HAT-PWM] servo connector LS GPIO: %u/%u/%u/%u\r\n",
170	        g_servoGpios[0], g_servoGpios[1], g_servoGpios[2], g_servoGpios[3]);
171	
172	    BlueLedInit();
173	    ServoGpioInit();
174	
175	    while (1) {
176	        ServoHoldPulse(SERVO_FORWARD_PULSE_US, SERVO_HALF_TURN_CYCLES);
177	        ServoHoldPulse(SERVO_STOP_PULSE_US, SERVO_STOP_CYCLES);
178	        ServoHoldPulse(SERVO_REVERSE_PULSE_US, SERVO_HALF_TURN_CYCLES);
179	        ServoHoldPulse(SERVO_STOP_PULSE_US, SERVO_STOP_CYCLES);
180	    }
181	}
182	
183	static void ServoEntry(void)
184	{
185	    osThreadAttr_t servoAttr = {
186	        .name = "ServoTask",
187	        .attr_bits = 0U,
188	        .cb_mem = NULL,
189	        .cb_size = 0U,
190	        .stack_mem = NULL,
191	        .stack_size = SERVO_TASK_STACK_SIZE,
192	        .priority = SERVO_TASK_PRIORITY,
193	    };
194	    osThreadAttr_t breathAttr = {
195	        .name = "BreathLedTask",
196	        .attr_bits = 0U,
197	        .cb_mem = NULL,
198	        .cb_size = 0U,
199	        .stack_mem = NULL,
200	        .stack_size = BREATH_TASK_STACK_SIZE,
201	        .priority = BREATH_TASK_PRIORITY,
202	    };
203	
204	    if (osThreadNew(ServoTask, NULL, &servoAttr) == NULL) {
205	        printf("[LOONG-HAT-PWM] create servo task failed\r\n");
206	    }
207	
208	    if (osThreadNew(BreathLedTask, NULL, &breathAttr) == NULL) {
209	        printf("[LOONG-HAT-PWM] create breath LED task failed\r\n");
210	    }
211	}
212	
213	SYS_RUN(ServoEntry);
