60	static int init_led_gpio(int gpio)
61	{
62	  int ret;
63	  char path[32];
64	  int fd;
65	
66	  ret = pinctrl_set_gpio_function(gpio);
67	  if (ret < 0)
68	    {
69	      printf("[KEY] ERROR: pinctrl failed for GPIO%d\n", gpio);
70	      return ret;
71	    }
72	
73	  snprintf(path, sizeof(path), "/dev/gpio%d", gpio);
74	  fd = open(path, O_RDWR);
75	  if (fd < 0)
76	    {
77	      printf("[KEY] ERROR: open %s failed: %d\n", path, errno);
78	      return -errno;
79	    }
80	
81	  ret = ioctl(fd, GPIOC_SETPINTYPE, (unsigned long)GPIO_OUTPUT_PIN);
82	  if (ret < 0)
83	    {
84	      printf("[KEY] ERROR: GPIOC_SETPINTYPE(OUTPUT) on GPIO%d: %d\n",
85	             gpio, errno);
86	      close(fd);
87	      return -errno;
88	    }
89	
90	  /* LED off (high = off for active-low) */
91	
92	  ioctl(fd, GPIOC_WRITE, 1);
93	  return fd;
94	}
95	
96	static int init_key_gpio(int gpio)
97	{
98	  int ret;
99	  char path[32];
100	  int fd;
101	
102	  ret = pinctrl_set_gpio_function(gpio);
103	  if (ret < 0)
104	    {
105	      printf("[KEY] ERROR: pinctrl failed for GPIO%d\n", gpio);
106	      return ret;
107	    }
108	
109	  snprintf(path, sizeof(path), "/dev/gpio%d", gpio);
110	  fd = open(path, O_RDWR);
111	  if (fd < 0)
112	    {
113	      printf("[KEY] ERROR: open %s failed: %d\n", path, errno);
114	      return -errno;
115	    }
116	
117	  ret = ioctl(fd, GPIOC_SETPINTYPE, (unsigned long)GPIO_INPUT_PIN);
118	  if (ret < 0)
119	    {
120	      printf("[KEY] ERROR: GPIOC_SETPINTYPE(INPUT) on GPIO%d: %d\n",
121	             gpio, errno);
122	      close(fd);
123	      return -errno;
124	    }
125	
126	  return fd;
127	}
128	
129	static bool get_key_value(int fd)
130	{
131	  bool value = true;
132	
133	  ioctl(fd, GPIOC_READ, (unsigned long)(uintptr_t)&value);
134	  return value;
135	}
136	
137	static int is_key_pressed(key_state_s *key)
138	{
139	  bool value = get_key_value(key->fd);
140	
141	  /* Detect falling edge: HIGH -> LOW = press */
142	
143	  if (!value && key->last_value)
144	    {
145	      up_mdelay(KEY_DEBOUNCE_MS);
146	      value = get_key_value(key->fd);
147	      if (!value)
148	        {
149	          key->last_value = value;
150	          return 1;
151	        }
152	    }
153	
154	  key->last_value = value;
155	  return 0;
156	}
157	
158	static void set_led(int fd, int on)
159	{
160	  /* Active-low: 0 = ON, 1 = OFF */
161	
162	  ioctl(fd, GPIOC_WRITE, on ? 0 : 1);
163	}
