/****************************************************************************
 * apps/examples/ls_driver_test/test_adc_pwm.c
 *
 * ADC + PWM + OLED combined test
 * References: loong_hat 06_MCP3204 (ADC) + 10_PWM (servo)
 *
 * Function:
 *   - 4 PWM outputs: 0.5V / 1.0V / 1.5V / 2.0V (via duty cycle)
 *   - 3 ADC channels: CH1, CH2, CH3 continuous sampling
 *   - OLED displays raw + voltage for each channel
 *
 * PWM channels (servo connectors on LOONG-HAT):
 *   PWM0 (GPIO62) -> 0.5V  (duty 15.15%)
 *   PWM1 (GPIO60) -> 1.0V  (duty 30.30%)
 *   PWM2 (GPIO81) -> 1.5V  (duty 45.45%)
 *   PWM3 (GPIO70) -> 2.0V  (duty 60.61%)
 *
 * ADC channels (0~1.8V range, 12-bit):
 *   CH1, CH2, CH3
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/ioctl.h>
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <string.h>
#include <stdint.h>

#include <nuttx/timers/pwm.h>
#include <nuttx/analog/adc.h>
#include <nuttx/analog/ioctl.h>
#include <nuttx/i2c/i2c_master.h>

#include "ls_driver_test.h"
#include "oled_fonts.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* PWM */

#define PWM_COUNT           4
#define PWM_FREQUENCY       50      /* 50Hz for servo */
#define PWM_MAX_DUTY        10000   /* duty in 0.01% units */

/* Voltage to duty (assuming 3.3V supply, duty = voltage / 3.3V * 10000) */

#define PWM_DUTY_0V5        1515    /* 0.5V / 3.3V * 10000 */
#define PWM_DUTY_1V0        3030    /* 1.0V / 3.3V * 10000 */
#define PWM_DUTY_1V5        4545    /* 1.5V / 3.3V * 10000 */
#define PWM_DUTY_2V0        6061    /* 2.0V / 3.3V * 10000 */

/* ADC */

#define ADC_DEV_PATH        "/dev/adc0"
#define ADC_MAX_VOLTAGE     1800    /* 1.8V reference */
#define ADC_RESOLUTION      4096    /* 12-bit */
#define ADC_CHANNELS        3

/* OLED */

#define I2C1_PATH           "/dev/i2c1"
#define I2C_FREQ            I2C_SPEED_STANDARD
#define OLED_ADDR           0x3c
#define OLED_WIDTH          128
#define OLED_PAGES          8
#define OLED_I2C_CMD        0x00
#define OLED_I2C_DATA       0x40

/* Test */

#define SAMPLE_INTERVAL_MS  1000
#define SAMPLE_ROUNDS       30

/****************************************************************************
 * Private Types
 ****************************************************************************/

typedef enum
{
  FONT6X8 = 1,
  FONT8X16,
} oled_font_e;

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const char *g_pwm_paths[PWM_COUNT] =
{
  "/dev/pwm0", "/dev/pwm1", "/dev/pwm2", "/dev/pwm3",
};

static const unsigned int g_pwm_duty[PWM_COUNT] =
{
  PWM_DUTY_0V5, PWM_DUTY_1V0, PWM_DUTY_1V5, PWM_DUTY_2V0,
};

static const char *g_pwm_voltage[PWM_COUNT] =
{
  "0.5V", "1.0V", "1.5V", "2.0V",
};

static int g_i2c_fd = -1;

/****************************************************************************
 * Private Functions - PWM
 ****************************************************************************/

static int pwm_init_and_start(int index)
{
  int fd;
  int ret;
  struct pwm_info_s info;

  fd = open(g_pwm_paths[index], O_RDONLY);
  if (fd < 0)
    {
      printf("[ADC_PWM] ERROR: open %s failed: %d\n",
             g_pwm_paths[index], errno);
      return -errno;
    }

  info.frequency = PWM_FREQUENCY;
  info.duty      = g_pwm_duty[index];

  ret = ioctl(fd, PWMIOC_SETCHARACTERISTICS,
              (unsigned long)(uintptr_t)&info);
  if (ret < 0)
    {
      printf("[ADC_PWM] ERROR: PWMIOC_SETCHARACTERISTICS on %s: %d\n",
             g_pwm_paths[index], errno);
      close(fd);
      return -errno;
    }

  ret = ioctl(fd, PWMIOC_START, 0);
  if (ret < 0)
    {
      printf("[ADC_PWM] ERROR: PWMIOC_START on %s: %d\n",
             g_pwm_paths[index], errno);
      close(fd);
      return -errno;
    }

  printf("[ADC_PWM] PWM%d started: %s (duty=%u/10000)\n",
         index, g_pwm_voltage[index], g_pwm_duty[index]);
  return fd;
}

static void pwm_stop_all(int *fds)
{
  int i;

  for (i = 0; i < PWM_COUNT; i++)
    {
      if (fds[i] >= 0)
        {
          ioctl(fds[i], PWMIOC_STOP, 0);
          close(fds[i]);
          fds[i] = -1;
        }
    }
}

/****************************************************************************
 * Private Functions - ADC
 ****************************************************************************/

static int adc_read_channels(int fd, int32_t *raw, int *mv)
{
  struct adc_msg_s sample[ADC_CHANNELS];
  ssize_t nbytes;
  int ret;
  int i;

  /* Initialize output */

  for (i = 0; i < ADC_CHANNELS; i++)
    {
      raw[i] = 0;
      mv[i] = 0;
    }

  ret = ioctl(fd, ANIOC_TRIGGER, 0);
  if (ret < 0)
    {
      printf("[ADC_PWM] ERROR: ANIOC_TRIGGER: %d\n", errno);
      return -errno;
    }

  usleep(10000);

  nbytes = read(fd, sample, sizeof(sample));
  if (nbytes < 0)
    {
      printf("[ADC_PWM] ERROR: ADC read: %d\n", errno);
      return -errno;
    }

  if (nbytes == 0)
    {
      return -EAGAIN;
    }

  for (i = 0; i < (int)(nbytes / sizeof(struct adc_msg_s)); i++)
    {
      int ch = sample[i].am_channel;
      if (ch >= 0 && ch < ADC_CHANNELS)
        {
          raw[ch] = sample[i].am_data;
          mv[ch] = (int)((int64_t)sample[i].am_data *
                    ADC_MAX_VOLTAGE / ADC_RESOLUTION);
        }
    }

  return OK;
}

/****************************************************************************
 * Private Functions - I2C + OLED
 ****************************************************************************/

static int oled_i2c_write(uint8_t addr, const uint8_t *data, int len)
{
  struct i2c_msg_s msg;
  struct i2c_transfer_s trans;

  msg.frequency = I2C_FREQ;
  msg.addr      = addr;
  msg.flags     = 0;
  msg.buffer    = (FAR uint8_t *)data;
  msg.length    = len;

  trans.msgv = &msg;
  trans.msgc = 1;

  return ioctl(g_i2c_fd, I2CIOC_TRANSFER, (unsigned long)&trans);
}

static int oled_write_byte(uint8_t reg, uint8_t data)
{
  uint8_t buf[2];

  buf[0] = reg;
  buf[1] = data;

  return oled_i2c_write(OLED_ADDR, buf, 2);
}

static int oled_write_cmd(uint8_t cmd)
{
  return oled_write_byte(OLED_I2C_CMD, cmd);
}

static int oled_write_data(uint8_t data)
{
  return oled_write_byte(OLED_I2C_DATA, data);
}

static int oled_init_device(void)
{
  static const uint8_t init_cmds[] =
  {
    0xae, 0x00, 0x10, 0x40, 0xb0, 0x81, 0xff, 0xa1,
    0xa6, 0xa8, 0x3f, 0xc8, 0xd3, 0x00, 0xd5, 0x80,
    0xd8, 0x05, 0xd9, 0xf1, 0xda, 0x12, 0xdb, 0x30,
    0x8d, 0x14, 0xaf,
  };
  int i;

  for (i = 0; i < (int)(sizeof(init_cmds) / sizeof(init_cmds[0])); i++)
    {
      int ret = oled_write_cmd(init_cmds[i]);
      if (ret < 0)
        {
          printf("[ADC_PWM] ERROR: OLED init cmd 0x%02x: %d\n",
                 init_cmds[i], ret);
          return ret;
        }
    }

  return OK;
}

static void oled_set_position(uint8_t x, uint8_t y)
{
  oled_write_cmd(0xb0 + y);
  oled_write_cmd(x & 0x0f);
  oled_write_cmd(((x & 0xf0) >> 4) | 0x10);
}

static void oled_fill_screen(uint8_t fill)
{
  uint8_t page;
  uint8_t col;

  for (page = 0; page < OLED_PAGES; page++)
    {
      oled_set_position(0, page);
      for (col = 0; col < OLED_WIDTH; col++)
        {
          oled_write_data(fill);
        }
    }
}

static void oled_show_char(uint8_t x, uint8_t y, char ch, oled_font_e font)
{
  uint8_t c;
  uint8_t i;

  if (ch < ' ' || ch > '~')
    {
      ch = ' ';
    }

  c = (uint8_t)(ch - ' ');

  if (font == FONT8X16)
    {
      oled_set_position(x, y);
      for (i = 0; i < 8; i++)
        {
          oled_write_data(F8X16[c * 16 + i]);
        }

      oled_set_position(x, y + 1);
      for (i = 0; i < 8; i++)
        {
          oled_write_data(F8X16[c * 16 + 8 + i]);
        }
    }
  else
    {
      oled_set_position(x, y);
      for (i = 0; i < 6; i++)
        {
          oled_write_data(F6x8[c][i]);
        }
    }
}

static void oled_show_string(uint8_t x, uint8_t y,
                             const char *str, oled_font_e font)
{
  uint8_t step = (font == FONT8X16) ? 8 : 6;

  if (str == NULL)
    {
      return;
    }

  while (*str != '\0')
    {
      oled_show_char(x, y, *str, font);
      x += step;
      if (x > (OLED_WIDTH - step))
        {
          x = 0;
          y += (font == FONT8X16) ? 2 : 1;
          if (y >= OLED_PAGES)
            {
              break;
            }
        }

      str++;
    }
}

/****************************************************************************
 * Private Functions - OLED Display
 ****************************************************************************/

static void oled_show_adc_data(int32_t *raw, int *mv)
{
  char line[22];
  int i;

  oled_fill_screen(0x00);
  oled_show_string(16, 0, "ADC Monitor", FONT8X16);

  for (i = 0; i < ADC_CHANNELS; i++)
    {
      snprintf(line, sizeof(line), "CH%d: %4d %4dmV",
               i + 1, (int)raw[i], mv[i]);
      oled_show_string(0, 2 + i * 2, line, FONT8X16);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int test_adc_pwm(void)
{
  int pwm_fds[PWM_COUNT];
  int adc_fd;
  int oled_ok = 0;
  int32_t raw[ADC_CHANNELS];
  int mv[ADC_CHANNELS];
  int ret;
  int i;
  int round;

  printf("[ADC_PWM] === ADC + PWM + OLED Test ===\n");
  printf("[ADC_PWM] PWM: 4 channels (0.5V/1.0V/1.5V/2.0V)\n");
  printf("[ADC_PWM] ADC: 3 channels (CH1/CH2/CH3)\n");
  printf("[ADC_PWM] OLED: I2C1 addr=0x3C\n\n");

  /* Initialize PWM outputs */

  printf("[ADC_PWM] Starting PWM outputs...\n");
  for (i = 0; i < PWM_COUNT; i++)
    {
      pwm_fds[i] = -1;
    }

  for (i = 0; i < PWM_COUNT; i++)
    {
      pwm_fds[i] = pwm_init_and_start(i);
      if (pwm_fds[i] < 0)
        {
          printf("[ADC_PWM] PWM%d init failed\n", i);
          pwm_stop_all(pwm_fds);
          return pwm_fds[i];
        }
    }

  /* Open ADC */

  printf("[ADC_PWM] Opening ADC %s...\n", ADC_DEV_PATH);
  adc_fd = open(ADC_DEV_PATH, O_RDONLY);
  if (adc_fd < 0)
    {
      printf("[ADC_PWM] ERROR: open %s: %d\n", ADC_DEV_PATH, errno);
      pwm_stop_all(pwm_fds);
      return -errno;
    }

  /* Open I2C and init OLED */

  printf("[ADC_PWM] Opening I2C1...\n");
  g_i2c_fd = open(I2C1_PATH, O_RDWR);
  if (g_i2c_fd < 0)
    {
      printf("[ADC_PWM] ERROR: open %s: %d\n", I2C1_PATH, errno);
      close(adc_fd);
      pwm_stop_all(pwm_fds);
      return -errno;
    }

  ret = oled_init_device();
  if (ret < 0)
    {
      printf("[ADC_PWM] OLED init failed\n");
      close(g_i2c_fd);
      close(adc_fd);
      pwm_stop_all(pwm_fds);
      return ret;
    }
  oled_ok = 1;

  oled_fill_screen(0x00);
  oled_show_string(16, 0, "ADC + PWM", FONT8X16);
  oled_show_string(0, 3, "Sampling...", FONT8X16);
  usleep(1000000);

  /* Main sampling loop */

  printf("[ADC_PWM] Sampling %d rounds, interval %dms...\n\n",
         SAMPLE_ROUNDS, SAMPLE_INTERVAL_MS);

  for (round = 0; round < SAMPLE_ROUNDS; round++)
    {
      ret = adc_read_channels(adc_fd, raw, mv);
      if (ret < 0)
        {
          printf("[ADC_PWM] ADC read failed (round %d)\n", round + 1);
        }
      else
        {
          printf("[ADC_PWM] Round %2d:", round + 1);
          for (i = 0; i < ADC_CHANNELS; i++)
            {
              printf("  CH%d=%4dmV", i + 1, mv[i]);
            }
          printf("\n");

          if (oled_ok)
            {
              oled_show_adc_data(raw, mv);
            }
        }

      usleep(SAMPLE_INTERVAL_MS * 1000);
    }

  /* Cleanup */

  if (oled_ok)
    {
      oled_fill_screen(0x00);
      oled_show_string(0, 3, "  Test Done!", FONT8X16);
    }

  printf("\n[ADC_PWM] Test complete (%d rounds)\n", round);

  close(g_i2c_fd);
  g_i2c_fd = -1;
  close(adc_fd);
  pwm_stop_all(pwm_fds);

  return OK;
}

