31	static void MCP3204_SetOutput(unsigned int pin, IotGpioValue value)
32	{
33	    (void)IoTGpioSetOutputVal(pin, value);
34	    MCP3204_SpiDelay();
35	}
36	
37	static uint8_t MCP3204_TransferByte(uint8_t tx)
38	{
39	    uint8_t rx = 0;
40	    int bit;
41	
42	    for (bit = 7; bit >= 0; bit--) {
43	        IotGpioValue miso = IOT_GPIO_VALUE0;
44	
45	        MCP3204_SetOutput(MCP3204_MOSI_PIN, ((tx >> bit) & 0x01U) ? IOT_GPIO_VALUE1 : IOT_GPIO_VALUE0);
46	        MCP3204_SetOutput(MCP3204_SCK_PIN, IOT_GPIO_VALUE1);
47	        (void)IoTGpioGetInputVal(MCP3204_MISO_PIN, &miso);
48	        rx = (uint8_t)((rx << 1) | (miso == IOT_GPIO_VALUE1 ? 1U : 0U));
49	        MCP3204_SetOutput(MCP3204_SCK_PIN, IOT_GPIO_VALUE0);
50	    }
51	
52	    return rx;
53	}
