55	static void MCP3204_Init(void)
56	{
57	    ls_pinmux_pin_setup(MCP3204_SCK_PIN, LS_PINMUX_MODE_AS_GPIO);
58	    ls_pinmux_pin_setup(MCP3204_MISO_PIN, LS_PINMUX_MODE_AS_GPIO);
59	    ls_pinmux_pin_setup(MCP3204_MOSI_PIN, LS_PINMUX_MODE_AS_GPIO);
60	    ls_pinmux_pin_setup(MCP3204_CS_PIN, LS_PINMUX_MODE_AS_GPIO);
61	
62	    (void)IoTGpioInit(MCP3204_SCK_PIN);
63	    (void)IoTGpioInit(MCP3204_MISO_PIN);
64	    (void)IoTGpioInit(MCP3204_MOSI_PIN);
65	    (void)IoTGpioInit(MCP3204_CS_PIN);
66	
67	    (void)IoTGpioSetDir(MCP3204_SCK_PIN, IOT_GPIO_DIR_OUT);
68	    (void)IoTGpioSetDir(MCP3204_MISO_PIN, IOT_GPIO_DIR_IN);
69	    (void)IoTGpioSetDir(MCP3204_MOSI_PIN, IOT_GPIO_DIR_OUT);
70	    (void)IoTGpioSetDir(MCP3204_CS_PIN, IOT_GPIO_DIR_OUT);
71	
72	    MCP3204_SetOutput(MCP3204_CS_PIN, IOT_GPIO_VALUE1);
73	    MCP3204_SetOutput(MCP3204_SCK_PIN, IOT_GPIO_VALUE0);
74	    MCP3204_SetOutput(MCP3204_MOSI_PIN, IOT_GPIO_VALUE0);
