77	    printf("[MCP3204] pins: SCK GPIO%d, MISO GPIO%d, MOSI GPIO%d, CS GPIO%d\r\n",
78	        MCP3204_SCK_PIN, MCP3204_MISO_PIN, MCP3204_MOSI_PIN, MCP3204_CS_PIN);
79	    printf("[MCP3204] Vref=%u.%03u V\r\n", MCP3204_VREF_MV / 1000, MCP3204_VREF_MV % 1000);
80	}
