82	static int MCP3204_ReadRaw(uint8_t channel, uint16_t *raw)
83	{
84	    uint8_t rx1 = 0;
85	    uint8_t rx2 = 0;
86	
87	    if (channel >= MCP3204_CHANNEL_NUM || raw == NULL) {
88	        return -1;
89	    }
90	
91	    MCP3204_SetOutput(MCP3204_CS_PIN, IOT_GPIO_VALUE0);
92	    (void)MCP3204_TransferByte(0x06);
93	    rx1 = MCP3204_TransferByte((uint8_t)(channel << 6));
94	    rx2 = MCP3204_TransferByte(0x00);
95	    MCP3204_SetOutput(MCP3204_CS_PIN, IOT_GPIO_VALUE1);
96	
97	    *raw = (uint16_t)((((uint16_t)rx1 & 0x0FU) << 8) | rx2);
98	    return 0;
99	}
100	
101	static int MCP3204_ReadRawAverage(uint8_t channel, uint16_t *raw)
102	{
103	    uint32_t sum = 0;
104	    uint16_t value = 0;
105	    int ret;
106	    unsigned int i;
107	
108	    for (i = 0; i < MCP3204_SAMPLE_COUNT; i++) {
109	        ret = MCP3204_ReadRaw(channel, &value);
110	        if (ret != 0) {
111	            return ret;
112	        }
113	        sum += value;
114	        osDelay(2);
115	    }
116	
117	    *raw = (uint16_t)((sum + (MCP3204_SAMPLE_COUNT / 2)) / MCP3204_SAMPLE_COUNT);
118	    return 0;
119	}
120	
121	static uint32_t MCP3204_RawToMv(uint16_t raw)
122	{
123	    return ((uint32_t)raw * MCP3204_VREF_MV + (MCP3204_ADC_MAX / 2)) / MCP3204_ADC_MAX;
124	}
125	
126	static void MCP3204_Task(void *arg)
127	{
128	    (void)arg;
129	
130	    printf("[LOONG-HAT] MCP3204 ADC voltage detector start\r\n");
131	    MCP3204_Init();
132	
133	    while (1) {
134	        uint16_t raw = 0;
135	        uint32_t mv;
136	
137	        if (MCP3204_ReadRawAverage(MCP3204_DETECT_CH, &raw) == 0) {
138	            mv = MCP3204_RawToMv(raw);
139	            printf("[MCP3204] CH0 raw=%u voltage=%u.%03u V\r\n", raw, mv / 1000, mv % 1000);
140	        }
141	        osDelay(1000);
142	    }
143	}
