145	static void MCP3204_Entry(void)
146	{
147	    osThreadAttr_t attr;
148	
149	    printf("[LOONG-HAT] MCP3204 entry\r\n");
150	
151	    attr.name = "MCP3204Task";
152	    attr.attr_bits = 0U;
153	    attr.cb_mem = NULL;
154	    attr.cb_size = 0U;
155	    attr.stack_mem = NULL;
156	    attr.stack_size = TASK_STACK_SIZE;
157	    attr.priority = TASK_PRIORITY;
158	
159	    if (osThreadNew(MCP3204_Task, NULL, &attr) == NULL) {
160	        printf("[LOONG-HAT] create MCP3204 task failed\r\n");
161	    }
162	}
163	
164	SYS_RUN(MCP3204_Entry);
