/****************************************************************************
 * apps/examples/ls_driver_test/test_adc_pwm.c
 *
 * MCP3204 ADC + PWM + OLED test for LS2K300.
 *
 * Uses software SPI (GPIO bit-bang) to read MCP3204 ADC channels CH1/CH2/CH3.
 * Outputs 4 PWM servo voltages: 0.5V, 1.0V, 1.5V, 2.0V.
 * Displays ADC data on SSD1306 OLED.
 *
 * SPI0 pins:
 *   SCK  = GPIO64 (output)
 *   MISO = GPIO65 (input)
 *   MOSI = GPIO66 (output)
 *   CS   = GPIO67 (output, active low)
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/ioctl.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>

#include <nuttx/arch.h>
#include <nuttx/ioexpander/gpio.h>
#include <nuttx/i2c/i2c_master.h>

#include "ls_driver_test.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* MCP3204 SPI GPIO pins */

#define MCP3204_SCK_PIN         64
#define MCP3204_MISO_PIN        65
#define MCP3204_MOSI_PIN        66
#define MCP3204_CS_PIN          67

/* MCP3204 parameters */

#define MCP3204_CHANNEL_NUM     4
#define MCP3204_ADC_MAX         4095U
#define MCP3204_VREF_MV        3300U
#define MCP3204_SAMPLE_COUNT    8

/* Channels to read */

#define ADC_CH1                 1
#define ADC_CH2                 2
#define ADC_CH3                 3
#define ADC_NUM_CHANNELS        3

/* PWM configuration */

#define PWM_SERVO_COUNT         4
#define PWM_MAX_DUTY           10000

/* OLED */

#define OLED_I2C_ADDR          0x3C
#define OLED_WIDTH             128
#define OLED_HEIGHT            64
#define OLED_PAGES             (OLED_HEIGHT / 8)
#define OLED_DATA_MODE         0x40
#define OLED_CMD_MODE          0x00

/* Test iterations */

#define TEST_ROUNDS            30
#define DELAY_MS               1000

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const char *g_pwm_paths[PWM_SERVO_COUNT] =
{
  "/dev/pwm0",
  "/dev/pwm1",
  "/dev/pwm2",
  "/dev/pwm3"
};

static const float g_pwm_voltages[PWM_SERVO_COUNT] =
{
  0.5f, 1.0f, 1.5f, 2.0f
};

static const char *g_channel_labels[ADC_NUM_CHANNELS] =
{
  "CH1", "CH2", "CH3"
};

/****************************************************************************
 * Private Functions - GPIO
 ****************************************************************************/

static int gpio_open_out(int gpio)
{
  char path[32];
  int fd;
  int ret;

  ret = pinctrl_set_gpio_function(gpio);
  if (ret < 0)
    {
      return ret;
    }

  snprintf(path, sizeof(path), "/dev/gpio%d", gpio);
  fd = open(path, O_RDWR);
  if (fd < 0)
    {
      return -errno;
    }

  ret = ioctl(fd, GPIOC_SETPINTYPE, (unsigned long)GPIO_OUTPUT_PIN);
  if (ret < 0)
    {
      close(fd);
      return -errno;
    }

  return fd;
}

static int gpio_open_in(int gpio)
{
  char path[32];
  int fd;
  int ret;

  ret = pinctrl_set_gpio_function(gpio);
  if (ret < 0)
    {
      return ret;
    }

  snprintf(path, sizeof(path), "/dev/gpio%d", gpio);
  fd = open(path, O_RDWR);
  if (fd < 0)
    {
      return -errno;
    }

  ret = ioctl(fd, GPIOC_SETPINTYPE, (unsigned long)GPIO_INPUT_PIN);
  if (ret < 0)
    {
      close(fd);
      return -errno;
    }

  return fd;
}

static inline void gpio_write(int fd, int value)
{
  ioctl(fd, GPIOC_WRITE, value);
}

static inline int gpio_read(int fd)
{
  bool value = false;
  ioctl(fd, GPIOC_READ, (unsigned long)(uintptr_t)&value);
  return value ? 1 : 0;
}

/****************************************************************************
 * Private Functions - MCP3204 Software SPI
 ****************************************************************************/

static int g_fd_sck;
static int g_fd_miso;
static int g_fd_mosi;
static int g_fd_cs;

static void spi_delay(void)
{
  volatile int i;
  for (i = 0; i < 20; i++);
}

static void spi_set_output(int fd, int value)
{
  gpio_write(fd, value);
  spi_delay();
}

static uint8_t spi_transfer_byte(uint8_t tx)
{
  uint8_t rx = 0;
  int bit;

  for (bit = 7; bit >= 0; bit--)
    {
      int miso;

      spi_set_output(g_fd_mosi, (tx >> bit) & 0x01);
      spi_set_output(g_fd_sck, 1);
      miso = gpio_read(g_fd_miso);
      rx = (uint8_t)((rx << 1) | (miso ? 1 : 0));
      spi_set_output(g_fd_sck, 0);
    }

  return rx;
}

static int mcp3204_init(void)
{
  printf("[MCP3204] Software SPI init\n");
  printf("[MCP3204] SCK=GPIO%d MISO=GPIO%d MOSI=GPIO%d CS=GPIO%d\n",
         MCP3204_SCK_PIN, MCP3204_MISO_PIN,
         MCP3204_MOSI_PIN, MCP3204_CS_PIN);

  g_fd_sck = gpio_open_out(MCP3204_SCK_PIN);
  if (g_fd_sck < 0)
    {
      printf("[MCP3204] ERROR: open SCK GPIO%d: %d\n",
             MCP3204_SCK_PIN, g_fd_sck);
      return g_fd_sck;
    }

  g_fd_miso = gpio_open_in(MCP3204_MISO_PIN);
  if (g_fd_miso < 0)
    {
      printf("[MCP3204] ERROR: open MISO GPIO%d: %d\n",
             MCP3204_MISO_PIN, g_fd_miso);
      close(g_fd_sck);
      return g_fd_miso;
    }

  g_fd_mosi = gpio_open_out(MCP3204_MOSI_PIN);
  if (g_fd_mosi < 0)
    {
      printf("[MCP3204] ERROR: open MOSI GPIO%d: %d\n",
             MCP3204_MOSI_PIN, g_fd_mosi);
      close(g_fd_sck);
      close(g_fd_miso);
      return g_fd_mosi;
    }

  g_fd_cs = gpio_open_out(MCP3204_CS_PIN);
  if (g_fd_cs < 0)
    {
      printf("[MCP3204] ERROR: open CS GPIO%d: %d\n",
             MCP3204_CS_PIN, g_fd_cs);
      close(g_fd_sck);
      close(g_fd_miso);
      close(g_fd_mosi);
      return g_fd_cs;
    }

  /* CS high, SCK low, MOSI low */

  spi_set_output(g_fd_cs, 1);
  spi_set_output(g_fd_sck, 0);
  spi_set_output(g_fd_mosi, 0);

  printf("[MCP3204] Vref=%u mV\n", MCP3204_VREF_MV);
  return 0;
}

static void mcp3204_deinit(void)
{
  close(g_fd_cs);
  close(g_fd_mosi);
  close(g_fd_miso);
  close(g_fd_sck);
}

static int mcp3204_read_raw(uint8_t channel, uint16_t *raw)
{
  uint8_t rx1;
  uint8_t rx2;

  if (channel >= MCP3204_CHANNEL_NUM || raw == NULL)
    {
      return -EINVAL;
    }

  spi_set_output(g_fd_cs, 0);

  /* Start bit (1) + single-ended mode (1) + D2=0 */

  spi_transfer_byte(0x06);

  /* D1 D0 = channel bits */

  rx1 = spi_transfer_byte((uint8_t)(channel << 6));

  /* Clock out remaining data */

  rx2 = spi_transfer_byte(0x00);

  spi_set_output(g_fd_cs, 1);

  /* 12-bit result: [rx1 low 4 bits][rx2 all 8 bits] */

  *raw = (uint16_t)((((uint16_t)rx1 & 0x0FU) << 8) | rx2);
  return 0;
}

static int mcp3204_read_average(uint8_t channel, uint16_t *raw)
{
  uint32_t sum = 0;
  uint16_t value = 0;
  int ret;
  int i;

  for (i = 0; i < MCP3204_SAMPLE_COUNT; i++)
    {
      ret = mcp3204_read_raw(channel, &value);
      if (ret != 0)
        {
          return ret;
        }

      sum += value;
      up_mdelay(2);
    }

  *raw = (uint16_t)((sum + (MCP3204_SAMPLE_COUNT / 2)) / MCP3204_SAMPLE_COUNT);
  return 0;
}

static uint32_t mcp3204_raw_to_mv(uint16_t raw)
{
  return ((uint32_t)raw * MCP3204_VREF_MV + (MCP3204_ADC_MAX / 2)) /
         MCP3204_ADC_MAX;
}

/****************************************************************************
 * Private Functions - PWM
 ****************************************************************************/

static int pwm_set_voltage(int index, float voltage)
{
  int fd;
  struct pwm_info_s info;
  int duty;

  fd = open(g_pwm_paths[index], O_RDONLY);
  if (fd < 0)
    {
      printf("[ADC] ERROR: open %s failed: %d\n",
             g_pwm_paths[index], errno);
      return -errno;
    }

  /* Get current PWM config */

  if (ioctl(fd, PWMIOC_GETCHARACTERISTICS, (unsigned long)(uintptr_t)&info) < 0)
    {
      printf("[ADC] ERROR: PWMIOC_GETCHARACTERISTICS failed: %d\n", errno);
      close(fd);
      return -errno;
    }

  /* 50Hz, duty = Vout / 3.3V * 10000 */

  info.frequency = 50;
  duty = (int)(voltage / 3.3f * PWM_MAX_DUTY);
  if (duty < 0)
    {
      duty = 0;
    }

  if (duty > PWM_MAX_DUTY)
    {
      duty = PWM_MAX_DUTY;
    }

  info.duty = duty;

  if (ioctl(fd, PWMIOC_SETCHARACTERISTICS, (unsigned long)(uintptr_t)&info) < 0)
    {
      printf("[ADC] ERROR: PWMIOC_SETCHARACTERISTICS failed: %d\n", errno);
      close(fd);
      return -errno;
    }

  close(fd);
  return 0;
}

