 * Public Functions
 ****************************************************************************/

int test_adc_pwm(void)
{
  int ret;
  int i;
  int round;

  uint16_t raw[ADC_NUM_CHANNELS];
  uint32_t mv[ADC_NUM_CHANNELS];
  uint8_t channels[ADC_NUM_CHANNELS] = { ADC_CH1, ADC_CH2, ADC_CH3 };

  printf("[ADC] === MCP3204 ADC + PWM + OLED Test ===\n");
  printf("[ADC] PWM outputs: ");
  for (i = 0; i < PWM_SERVO_COUNT; i++)
    {
      printf("%s=%.1fV ", g_pwm_paths[i], g_pwm_voltages[i]);
    }

  printf("\n[ADC] ADC channels: CH1 CH2 CH3 (via MCP3204 SPI)\n");
  printf("[ADC] Rounds: %d\n\n", TEST_ROUNDS);

  /* Init PWM outputs */

  for (i = 0; i < PWM_SERVO_COUNT; i++)
    {
      ret = pwm_set_voltage(i, g_pwm_voltages[i]);
      if (ret < 0)
        {
          printf("[ADC] WARN: PWM%d set failed: %d\n", i, ret);
        }
    }

  printf("[ADC] PWM outputs configured\n");

  /* Init MCP3204 SPI */

  ret = mcp3204_init();
  if (ret < 0)
    {
      printf("[ADC] ERROR: MCP3204 init failed: %d\n", ret);
      return ret;
    }

  /* Init OLED */

  ret = oled_init_device();
  if (ret < 0)
    {
      printf("[ADC] ERROR: OLED init failed: %d\n", ret);
      mcp3204_deinit();
      return ret;
    }

  /* Main loop */

  for (round = 0; round < TEST_ROUNDS; round++)
    {
      /* Read ADC channels */

      for (i = 0; i < ADC_NUM_CHANNELS; i++)
        {
          ret = mcp3204_read_average(channels[i], &raw[i]);
          if (ret != 0)
            {
              printf("[ADC] ERROR: read CH%d failed: %d\n",
                     channels[i], ret);
              raw[i] = 0;
            }

          mv[i] = mcp3204_raw_to_mv(raw[i]);
        }

      /* Serial output */

      printf("[ADC] %3d: CH1=%4u(%u.%03uV) CH2=%4u(%u.%03uV) "
             "CH3=%4u(%u.%03uV)\n",
             round + 1,
             raw[0], mv[0] / 1000, mv[0] % 1000,
             raw[1], mv[1] / 1000, mv[1] % 1000,
             raw[2], mv[2] / 1000, mv[2] % 1000);

      /* Update OLED */

      oled_show_adc_data(raw, mv);

      up_mdelay(DELAY_MS);
    }

  /* Cleanup */

  mcp3204_deinit();

  printf("\n[ADC] Test complete.\n");
  return OK;
}

