108	/*
109	 * @brief: 传输出错时立即复位控制器传输状态：
110	 *         1. 挂起可能仍在进行的传输（清 CSTART/AUTOSUS）；
111	 *         2. CTSIZE(CR4) 写 0 强制本次传输结束，TSIZE(CR3) 复位为 0，
112	 *            防止残留的大 CTSIZE 被后续传输继承导致 EOT 永不置位；
113	 *         3. 清残留 W1C 状态标志；
114	 *         4. 排空 RXFIFO，避免残留数据干扰下一次读取；
115	 *         5. 立即把 CS(GPIO67) 拉高释放 MCP3204。
116	 */
117	static void MCP3204_SpiAbort(void)
118	{
119	    volatile uint32_t *cr1 = MCP3204_SpiReg(LS_SPI_IO_CR1);
120	    volatile uint32_t *sr1 = MCP3204_SpiReg(LS_SPI_IO_SR1);
121	    uint32_t val;
122	    uint32_t i;
123	
124	    val = readl(cr1);
125	    val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
126	    writel(val, cr1);
127	
128	    writel(0, MCP3204_SpiReg(LS_SPI_IO_CR4));
129	    writel(0, MCP3204_SpiReg(LS_SPI_IO_CR3));
130	
131	    LOS_UDelay(10);
132	
133	    writel(LS_SPI_SR1_W1C_FLAGS, sr1);
134	
135	    for (i = 0; i < 4; i++) {
136	        if (readl(sr1) & LS_SPI_SR1_RXE) {
137	            break;
138	        }
139	        (void)readb(MCP3204_SpiReg(LS_SPI_IO_DR));
140	    }
141	
142	    MCP3204_SpiCsSet(1);
143	    LOS_UDelay(1);
144	}
