146	/* Full-duplex single byte transfer on SPI2, SPI mode 0, 8-bit frame. */
147	static int MCP3204_SpiXferByte(uint8_t tx, uint8_t *rx)
148	{
149	    volatile uint32_t *cr1 = MCP3204_SpiReg(LS_SPI_IO_CR1);
150	    volatile uint32_t *sr1 = MCP3204_SpiReg(LS_SPI_IO_SR1);
151	    uint32_t val;
152	
153	    /* 使能 SPI 控制器 */
154	    val = readl(cr1);
155	    val |= LS_SPI_CR1_SPE;
156	    writel(val, cr1);
157	
158	    /* 挂起可能仍在进行的传输：清 CSTART/AUTOSUS，保证每次都有干净的 0->1 上升沿 */
159	    val = readl(cr1);
160	    val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
161	    writel(val, cr1);
162	
163	    /* 清残留状态标志位（W1C） */
164	    writel(LS_SPI_SR1_W1C_FLAGS, sr1);
165	
166	    /* CR3 TSIZE: 单次传输帧数 = TSIZE+1 = 1 帧 */
167	    writel(0, MCP3204_SpiReg(LS_SPI_IO_CR3));
168	
169	    /* 等待 TXFIFO 可写 */
170	    if (MCP3204_SpiWaitFlag(LS_SPI_SR1_TXA, 0) != 0) {
171	        printf("[MCP3204] TXA timeout\r\n");
172	        MCP3204_SpiAbort();
173	        return -1;
174	    }
175	
176	    /* 写入待发送字节 */
177	    writeb(tx, MCP3204_SpiReg(LS_SPI_IO_DR));
178	
179	    /* 启动一帧传输：只置 CSTART，不置 AUTOSUS。
180	     * 手册 10.2.1 描述 AUTOSUS=1 是"传完当前传输后重新载入 TSIZE 继续传输"，
181	     * 会让 EOT(bit15) 永不置位而超时；AUTOSUS=0 则传完即挂起并置 EOT。 */
182	    val = readl(cr1);
183	    val |= LS_SPI_CR1_CSTART;
184	    writel(val, cr1);
185	
186	    /* 等待传输结束 */
187	    if (MCP3204_SpiWaitFlag(LS_SPI_SR1_EOT, 1) != 0) {
188	        printf("[MCP3204] EOT timeout: SR1=0x%08x CR1=0x%08x\r\n",
189	            readl(sr1), readl(cr1));
190	        MCP3204_SpiAbort();
191	        return -1;
192	    }
193	
194	    /* 等待 RXFIFO 有数据 */
195	    if (MCP3204_SpiWaitFlag(LS_SPI_SR1_RXA, 0) != 0) {
196	        printf("[MCP3204] RXA timeout\r\n");
197	        MCP3204_SpiAbort();
198	        return -1;
199	    }
200	
201	    if (rx != NULL) {
202	        *rx = readb(MCP3204_SpiReg(LS_SPI_IO_DR));
203	    } else {
204	        (void)readb(MCP3204_SpiReg(LS_SPI_IO_DR));
205	    }
206	    return 0;
207	}
