209	static void MCP3204_Init(void)
210	{
211	    uint32_t brint;
212	
213	    /* 数据脚 GPIO64/65/66 复用为 spi2_clk/spi2_miso/spi2_mosi（主功能），
214	     * 片选 GPIO67 使用软件 GPIO 方式控制。 */
215	    ls_pinmux_pin_setup(MCP3204_SCK_PIN, LS_PINMUX_MODE_AS_MAIN_FUNC);
216	    ls_pinmux_pin_setup(MCP3204_MISO_PIN, LS_PINMUX_MODE_AS_MAIN_FUNC);
217	    ls_pinmux_pin_setup(MCP3204_MOSI_PIN, LS_PINMUX_MODE_AS_MAIN_FUNC);
218	
219	    ls_pinmux_pin_setup(MCP3204_CS_PIN, LS_PINMUX_MODE_AS_GPIO);
220	    IoTGpioInit(MCP3204_CS_PIN);
221	    IoTGpioSetDir(MCP3204_CS_PIN, IOT_GPIO_DIR_OUT);
222	    MCP3204_SpiCsSet(1);
223	
224	    /* 确保 SPI2/3 模块时钟门控打开（CHIP_CTRL05 0x16000114 bits[18:17]，缺省 0x3）。
225	     * 复位/U-Boot 配置可能将其关掉，若模块无时钟，传输永不完成，EOT 永不置位。 */
226	    {
227	        volatile uint32_t *cfg5 = (volatile uint32_t *)LS_GENERAL_CFG5;
228	        writel(readl(cfg5) | (0x3u << 17), cfg5);
229	    }
230	
231	    /* CFG3: 主模式、标准全双工（MISO 输入 / MOSI 输出）、软件片选模式 */
232	    writel(LS_SPI_CFG3_MSTR | LS_SPI_CFG3_DIE | LS_SPI_CFG3_DOE | LS_SPI_CFG3_SSMODE_SW,
233	           MCP3204_SpiReg(LS_SPI_IO_CFG3));
234	
235	    /* CFG1: SPI Mode 0（CPOL=0, CPHA=0），8bit 帧 */
236	    writel(LS_SPI_CFG1_DSIZE_8BIT, MCP3204_SpiReg(LS_SPI_IO_CFG1));
237	
238	    /* CFG2: 波特率分频 BRINT = APB时钟 / 目标SPI时钟 */
239	    brint = MCP3204_SPI_APB_HZ / MCP3204_SPI_CLOCK_HZ;
240	    if (brint < 2) {
241	        brint = 2;
242	    }
243	    if (brint > 255) {
244	        brint = 255;
245	    }
246	    writel(brint << LS_SPI_CFG2_BRINT_SHIFT, MCP3204_SpiReg(LS_SPI_IO_CFG2));
247	
248	    /* CR1: 使能 SPI（须在 CFGx 配置完成后写） */
249	    writel(LS_SPI_CR1_SPE, MCP3204_SpiReg(LS_SPI_IO_CR1));
250	
251	    printf("[MCP3204] hardware SPI2 init, mode=0, sclk=%uHz\r\n", MCP3204_SPI_CLOCK_HZ);
252	    printf("[MCP3204] SPI2 base=0x%lx, pins: SCK GPIO%d, MISO GPIO%d, MOSI GPIO%d, CS GPIO%d\r\n",
253	        (unsigned long)LS_SPI2_BASE,
254	        MCP3204_SCK_PIN, MCP3204_MISO_PIN, MCP3204_MOSI_PIN, MCP3204_CS_PIN);
255	    printf("[MCP3204] Vref=%u.%03u V\r\n", MCP3204_VREF_MV / 1000, MCP3204_VREF_MV % 1000);
256	}
