258	static int MCP3204_ReadRaw(uint8_t channel, uint16_t *raw)
259	{
260	    uint8_t rxHi = 0;
261	    uint8_t rxLo = 0;
262	
263	    if (channel >= MCP3204_CHANNEL_NUM || raw == NULL) {
264	        return -1;
265	    }
266	
267	    MCP3204_SpiCsSet(0);
268	    LOS_UDelay(1);
269	    if (MCP3204_SpiXferByte(0x06, NULL) != 0 ||
270	        MCP3204_SpiXferByte((uint8_t)(channel << 6), &rxHi) != 0 ||
271	        MCP3204_SpiXferByte(0x00, &rxLo) != 0) {
272	        MCP3204_SpiCsSet(1);
273	        return -1;
274	    }
275	    MCP3204_SpiCsSet(1);
276	    LOS_UDelay(1);
277	
278	    *raw = (uint16_t)((((uint16_t)rxHi & 0x0FU) << 8) | rxLo);
279	    return 0;
280	}
281	
282	static int MCP3204_ReadRawAverage(uint8_t channel, uint16_t *raw)
283	{
284	    uint32_t sum = 0;
285	    uint16_t value = 0;
286	    int ret;
287	    unsigned int i;
288	
289	    for (i = 0; i < MCP3204_SAMPLE_COUNT; i++) {
290	        ret = MCP3204_ReadRaw(channel, &value);
291	        if (ret != 0) {
292	            return ret;
293	        }
294	        sum += value;
295	        osDelay(2);
296	    }
297	
298	    *raw = (uint16_t)((sum + (MCP3204_SAMPLE_COUNT / 2)) / MCP3204_SAMPLE_COUNT);
299	    return 0;
300	}
301	
302	static uint32_t MCP3204_RawToMv(uint16_t raw)
303	{
304	    return ((uint32_t)raw * MCP3204_VREF_MV + (MCP3204_ADC_MAX / 2)) / MCP3204_ADC_MAX;
305	}
