/****************************************************************************
 * apps/examples/ls_driver_test/test_adc_pwm.c
 *
 * MCP3204 ADC (hardware SPI2) + PWM + OLED test for LS2K300.
 *
 * Uses LS2K300 hardware SPI2 controller to read MCP3204 ADC channels
 * CH1/CH2/CH3. CS (GPIO67) is software GPIO controlled.
 *
 * Outputs 4 PWM servo voltages: 0.5V, 1.0V, 1.5V, 2.0V.
 * Displays ADC data on SSD1306 OLED.
 *
 * SPI0 40Pin -> LS2K300 SPI2 controller:
 *   SPI2_CLK  = GPIO64 (MAIN_FUNC, hardware clock)
 *   SPI2_MISO = GPIO65 (MAIN_FUNC, data in)
 *   SPI2_MOSI = GPIO66 (MAIN_FUNC, data out)
 *   CSN1      = GPIO67 (GPIO, software CS)
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/ioctl.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <stdint.h>

#include <nuttx/arch.h>
#include <nuttx/ioexpander/gpio.h>
#include <nuttx/i2c/i2c_master.h>

#include "ls_driver_test.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* SPI2 controller base (uncached, PHYS 0x1610c000) */

#define SPI2_BASE               (0x8000000000000000UL | 0x1610c000UL)

/* GENERAL_CFG5 for SPI2/3 clock gate */

#define LS_GENERAL_CFG5_ADDR    (0x8000000000000000UL | 0x16000114UL)

/* SPI IO register offsets (LS2K300 manual ch.10) */

#define LS_SPI_IO_CR1           0x00
#define LS_SPI_IO_CR3           0x08
#define LS_SPI_IO_CR4           0x0c
#define LS_SPI_IO_SR1           0x14
#define LS_SPI_IO_CFG1          0x20
#define LS_SPI_IO_CFG2          0x24
#define LS_SPI_IO_CFG3          0x28
#define LS_SPI_IO_DR            0x40

/* CR1 bits */

#define LS_SPI_CR1_SPE          (1U << 0)
#define LS_SPI_CR1_CSTART       (1U << 1)
#define LS_SPI_CR1_AUTOSUS      (1U << 2)

/* CFG1: 8-bit frame (DSIZE=7), MSB first, CPOL=0 CPHA=0 (mode 0) */

#define LS_SPI_CFG1_DSIZE_8BIT  (7U << 8)

/* CFG2: baud ratio divider */

#define LS_SPI_CFG2_BRINT_SHIFT 8

/* CFG3: master, full duplex, software CS */

#define LS_SPI_CFG3_MSTR        (1U << 0)
#define LS_SPI_CFG3_DIE         (1U << 2)
#define LS_SPI_CFG3_DOE         (1U << 3)
#define LS_SPI_CFG3_SSMODE_SW   (1U << 8)

/* SR1 status bits */

#define LS_SPI_SR1_RXA          (1U << 0)
#define LS_SPI_SR1_TXA          (1U << 1)
#define LS_SPI_SR1_RXE          (1U << 4)
#define LS_SPI_SR1_OVR          (1U << 8)
#define LS_SPI_SR1_UDR          (1U << 9)
#define LS_SPI_SR1_CRCE         (1U << 10)
#define LS_SPI_SR1_MODF         (1U << 11)
#define LS_SPI_SR1_EOT          (1U << 15)

#define LS_SPI_SR1_W1C_FLAGS    (LS_SPI_SR1_EOT | LS_SPI_SR1_MODF | \
                                 LS_SPI_SR1_CRCE | LS_SPI_SR1_UDR | \
                                 LS_SPI_SR1_OVR)

/* APB device clock ~200MHz, MCP3204 max 1.2MHz, use 1MHz */

#define SPI_APB_HZ              (200UL * 1000000UL)
#define SPI_CLOCK_HZ            1000000UL
#define SPI_WAIT_TIMEOUT_US     10000U

/* MCP3204 GPIO pins */

#define MCP3204_CS_PIN          67

/* MCP3204 parameters */

#define MCP3204_CHANNEL_NUM     4
#define MCP3204_ADC_MAX         4095U
#define MCP3204_VREF_MV        3300U
#define MCP3204_SAMPLE_COUNT    8

/* Channels to read */

#define ADC_CH1                 1
#define ADC_CH2                 2
#define ADC_CH3                 3
#define ADC_NUM_CHANNELS        3

/* PWM */

#define PWM_SERVO_COUNT         4
#define PWM_MAX_DUTY           10000

/* OLED */

#define OLED_I2C_ADDR          0x3C
#define OLED_WIDTH             128
#define OLED_HEIGHT            64
#define OLED_PAGES             (OLED_HEIGHT / 8)
#define OLED_DATA_MODE         0x40
#define OLED_CMD_MODE          0x00

/* Test */

#define TEST_ROUNDS            30
#define DELAY_MS               1000

/* Register access helpers */

#define SPI_REG32(off) (*(volatile uint32_t *)(SPI2_BASE + (off)))
#define CFG5_REG      (*(volatile uint32_t *)LS_GENERAL_CFG5_ADDR)

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const char *g_pwm_paths[PWM_SERVO_COUNT] =
{
  "/dev/pwm0", "/dev/pwm1", "/dev/pwm2", "/dev/pwm3"
};

static const float g_pwm_voltages[PWM_SERVO_COUNT] =
{
  0.5f, 1.0f, 1.5f, 2.0f
};

static const char *g_channel_labels[ADC_NUM_CHANNELS] =
{
  "CH1", "CH2", "CH3"
};

static int g_fd_cs = -1;

/****************************************************************************
 * Private Functions - SPI2 Hardware Controller
 ****************************************************************************/

static int spi2_wait_flag(uint32_t flag, int clear)
{
  uint32_t val;
  uint32_t i;

  for (i = 0; i < SPI_WAIT_TIMEOUT_US; i++)
    {
      val = SPI_REG32(LS_SPI_IO_SR1);
      if (val & flag)
        {
          if (clear)
            {
              SPI_REG32(LS_SPI_IO_SR1) = flag;
            }

          return 0;
        }

      up_udelay(1);
    }

  return -1;
}

static void spi2_abort(void)
{
  uint32_t val;
  uint32_t i;

  /* Suspend any ongoing transfer */

  val = SPI_REG32(LS_SPI_IO_CR1);
  val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
  SPI_REG32(LS_SPI_IO_CR1) = val;

  /* Force transfer end */

  SPI_REG32(LS_SPI_IO_CR4) = 0;
  SPI_REG32(LS_SPI_IO_CR3) = 0;
  up_udelay(10);

  /* Clear W1C status flags */

  SPI_REG32(LS_SPI_IO_SR1) = LS_SPI_SR1_W1C_FLAGS;

  /* Drain RXFIFO */

  for (i = 0; i < 4; i++)
    {
      if (SPI_REG32(LS_SPI_IO_SR1) & LS_SPI_SR1_RXE)
        {
          break;
        }

      (void)(uint8_t)SPI_REG32(LS_SPI_IO_DR);
    }

  /* Release CS */

  ioctl(g_fd_cs, GPIOC_WRITE, 1);
  up_udelay(1);
}

static int spi2_xfer_byte(uint8_t tx, uint8_t *rx)
{
  uint32_t val;

  /* Enable SPI */

  val = SPI_REG32(LS_SPI_IO_CR1);
  val |= LS_SPI_CR1_SPE;
  SPI_REG32(LS_SPI_IO_CR1) = val;

  /* Clear any pending transfer state */

  val = SPI_REG32(LS_SPI_IO_CR1);
  val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
  SPI_REG32(LS_SPI_IO_CR1) = val;

  /* Clear residual status flags (W1C) */

  SPI_REG32(LS_SPI_IO_SR1) = LS_SPI_SR1_W1C_FLAGS;

  /* CR3 TSIZE: single frame (TSIZE+1 = 1) */

  SPI_REG32(LS_SPI_IO_CR3) = 0;

  /* Wait TXFIFO writable */

  if (spi2_wait_flag(LS_SPI_SR1_TXA, 0) != 0)
    {
      printf("[MCP3204] TXA timeout\n");
      spi2_abort();
      return -1;
    }

  /* Write TX byte */

  SPI_REG32(LS_SPI_IO_DR) = tx;

  /* Start transfer: CSTART only, no AUTOSUS */

  val = SPI_REG32(LS_SPI_IO_CR1);
  val |= LS_SPI_CR1_CSTART;
  SPI_REG32(LS_SPI_IO_CR1) = val;

  /* Wait EOT */

  if (spi2_wait_flag(LS_SPI_SR1_EOT, 1) != 0)
    {
      printf("[MCP3204] EOT timeout: SR1=0x%08x CR1=0x%08x\n",
             SPI_REG32(LS_SPI_IO_SR1), SPI_REG32(LS_SPI_IO_CR1));
      spi2_abort();
      return -1;
    }

  /* Wait RXFIFO has data */

  if (spi2_wait_flag(LS_SPI_SR1_RXA, 0) != 0)
    {
      printf("[MCP3204] RXA timeout\n");
      spi2_abort();
      return -1;
    }

  if (rx != NULL)
    {
      *rx = (uint8_t)SPI_REG32(LS_SPI_IO_DR);
    }
  else
    {
      (void)(uint8_t)SPI_REG32(LS_SPI_IO_DR);
    }

  return 0;
}

static int mcp3204_init(void)
{
  int ret;
  uint32_t brint;

  printf("[MCP3204] Hardware SPI2 init\n");

  /* Open CS GPIO */

  ret = pinctrl_set_gpio_function(MCP3204_CS_PIN);
  if (ret < 0)
    {
      printf("[MCP3204] ERROR: pinctrl CS GPIO%d: %d\n", MCP3204_CS_PIN, ret);
      return ret;
    }

  g_fd_cs = open("/dev/gpio67", O_RDWR);
  if (g_fd_cs < 0)
    {
      printf("[MCP3204] ERROR: open CS GPIO%d: %d\n", MCP3204_CS_PIN, errno);
      return -errno;
    }

  ret = ioctl(g_fd_cs, GPIOC_SETPINTYPE, (unsigned long)GPIO_OUTPUT_PIN);
  if (ret < 0)
    {
      printf("[MCP3204] ERROR: CS set output: %d\n", errno);
      close(g_fd_cs);
      g_fd_cs = -1;
      return -errno;
    }

  /* CS high (deselect) */

  ioctl(g_fd_cs, GPIOC_WRITE, 1);

  /* Enable SPI2/3 module clock gate (CHIP_CTRL05 bits[18:17]) */

  CFG5_REG |= (0x3u << 17);

  /* CFG3: master, full duplex, software CS mode */

  SPI_REG32(LS_SPI_IO_CFG3) = LS_SPI_CFG3_MSTR | LS_SPI_CFG3_DIE |
                               LS_SPI_CFG3_DOE | LS_SPI_CFG3_SSMODE_SW;

  /* CFG1: SPI mode 0, 8-bit frame */

  SPI_REG32(LS_SPI_IO_CFG1) = LS_SPI_CFG1_DSIZE_8BIT;

  /* CFG2: baud rate divider = APB / SPI clock */

  brint = SPI_APB_HZ / SPI_CLOCK_HZ;
  if (brint < 2)
    {
      brint = 2;
    }

  if (brint > 255)
    {
      brint = 255;
    }

  SPI_REG32(LS_SPI_IO_CFG2) = brint << LS_SPI_CFG2_BRINT_SHIFT;

  /* CR1: enable SPI (must be after CFG writes) */

  SPI_REG32(LS_SPI_IO_CR1) = LS_SPI_CR1_SPE;

  printf("[MCP3204] SPI2 base=0x%lx, mode=0, sclk=%u Hz\n",
         (unsigned long)SPI2_BASE, SPI_CLOCK_HZ);
  printf("[MCP3204] SCK=GPIO64 MISO=GPIO65 MOSI=GPIO66 CS=GPIO67\n");
  printf("[MCP3204] Vref=%u mV\n", MCP3204_VREF_MV);
  return 0;
}

static void mcp3204_deinit(void)
{
  if (g_fd_cs >= 0)
    {
      ioctl(g_fd_cs, GPIOC_WRITE, 1);
      close(g_fd_cs);
      g_fd_cs = -1;
    }
}

static int mcp3204_read_raw(uint8_t channel, uint16_t *raw)
{
  uint8_t rx_hi = 0;
  uint8_t rx_lo = 0;

  if (channel >= MCP3204_CHANNEL_NUM || raw == NULL)
    {
      return -EINVAL;
    }

  /* CS low */

  ioctl(g_fd_cs, GPIOC_WRITE, 0);
  up_udelay(1);

  /* Start bit + single-ended + D2=0 */

  if (spi2_xfer_byte(0x06, NULL) != 0 ||
      spi2_xfer_byte((uint8_t)(channel << 6), &rx_hi) != 0 ||
      spi2_xfer_byte(0x00, &rx_lo) != 0)
    {
      ioctl(g_fd_cs, GPIOC_WRITE, 1);
      return -1;
    }

  /* CS high */

  ioctl(g_fd_cs, GPIOC_WRITE, 1);
  up_udelay(1);

  /* 12-bit result */

  *raw = (uint16_t)((((uint16_t)rx_hi & 0x0FU) << 8) | rx_lo);
  return 0;
}

static int mcp3204_read_average(uint8_t channel, uint16_t *raw)
{
  uint32_t sum = 0;
  uint16_t value = 0;
  int ret;
  int i;

  for (i = 0; i < MCP3204_SAMPLE_COUNT; i++)
    {
      ret = mcp3204_read_raw(channel, &value);
      if (ret != 0)
        {
          return ret;
        }

      sum += value;
      up_mdelay(2);
    }

  *raw = (uint16_t)((sum + (MCP3204_SAMPLE_COUNT / 2)) / MCP3204_SAMPLE_COUNT);
  return 0;
}

static uint32_t mcp3204_raw_to_mv(uint16_t raw)
{
  return ((uint32_t)raw * MCP3204_VREF_MV + (MCP3204_ADC_MAX / 2)) /
         MCP3204_ADC_MAX;
}

/****************************************************************************
 * Private Functions - PWM
 ****************************************************************************/

static int pwm_set_voltage(int index, float voltage)
{
  int fd;
  struct pwm_info_s info;
  int duty;

  fd = open(g_pwm_paths[index], O_RDONLY);
  if (fd < 0)
    {
      printf("[ADC] ERROR: open %s: %d\n", g_pwm_paths[index], errno);
      return -errno;
    }

  if (ioctl(fd, PWMIOC_GETCHARACTERISTICS,
            (unsigned long)(uintptr_t)&info) < 0)
    {
      printf("[ADC] ERROR: PWMIOC_GETCHARACTERISTICS: %d\n", errno);
      close(fd);
      return -errno;
    }

  info.frequency = 50;
  duty = (int)(voltage / 3.3f * PWM_MAX_DUTY);
  if (duty < 0)
    {
      duty = 0;
    }

  if (duty > PWM_MAX_DUTY)
    {
      duty = PWM_MAX_DUTY;
    }

  info.duty = duty;

  if (ioctl(fd, PWMIOC_SETCHARACTERISTICS,
            (unsigned long)(uintptr_t)&info) < 0)
    {
      printf("[ADC] ERROR: PWMIOC_SETCHARACTERISTICS: %d\n", errno);
      close(fd);
      return -errno;
    }

  close(fd);
  return 0;
}

