static int oled_write_cmd(int fd_i2c, uint8_t cmd)
{
  uint8_t buf[2] = { OLED_CMD_MODE, cmd };
  struct i2c_msg_s msg;
  struct i2c_transfer_s xfer;

  msg.frequency = 400000;
  msg.addr = OLED_I2C_ADDR;
  msg.flags = 0;
  msg.buffer = buf;
  msg.length = 2;

  xfer.msgv = &msg;
  xfer.msgc = 1;

  return ioctl(fd_i2c, I2C_TRANSFER, (unsigned long)(uintptr_t)&xfer);
}

static int oled_write_data(int fd_i2c, const uint8_t *data, int len)
{
  uint8_t buf[129];
  struct i2c_msg_s msg;
  struct i2c_transfer_s xfer;

  if (len > 128)
    {
      len = 128;
    }

  buf[0] = OLED_DATA_MODE;
  memcpy(&buf[1], data, len);

  msg.frequency = 400000;
  msg.addr = OLED_I2C_ADDR;
  msg.flags = 0;
  msg.buffer = buf;
  msg.length = len + 1;

  xfer.msgv = &msg;
  xfer.msgc = 1;

  return ioctl(fd_i2c, I2C_TRANSFER, (unsigned long)(uintptr_t)&xfer);
}

static int oled_init_device(void)
{
  int fd;
  int ret;
  int i;

  static const uint8_t init_cmds[] =
  {
    0xAE, 0xD5, 0x80, 0xA8, 0x3F, 0xD3, 0x00, 0x40,
    0x8D, 0x14, 0x20, 0x02, 0xA1, 0xC8, 0xDA, 0x12,
    0x81, 0xCF, 0xD9, 0xF1, 0xDB, 0x40, 0xA4, 0xA6, 0xAF
  };

  fd = open(OLED_I2C_PATH, O_RDWR);
  if (fd < 0)
    {
      printf("[ADC] ERROR: open %s: %d\n", OLED_I2C_PATH, errno);
      return -errno;
    }

  for (i = 0; i < (int)sizeof(init_cmds); i++)
    {
      ret = oled_write_cmd(fd, init_cmds[i]);
      if (ret < 0)
        {
          printf("[ADC] ERROR: OLED cmd[%d]: %d\n", i, ret);
          close(fd);
          return ret;
        }
    }

  /* Clear display */

  {
    uint8_t zeros[128];
    int page;

    memset(zeros, 0, sizeof(zeros));
    for (page = 0; page < OLED_PAGES; page++)
      {
        oled_write_cmd(fd, 0xB0 + page);
        oled_write_cmd(fd, 0x00);
        oled_write_cmd(fd, 0x10);
        oled_write_data(fd, zeros, 128);
      }
  }

  printf("[ADC] OLED init done\n");
  close(fd);
  return 0;
}

static void oled_text(int page, int col, const char *text, uint8_t *buf)
{
  int i;

  for (i = 0; text[i] != '\0' && (col + i) < 16; i++)
    {
      int idx = text[i] - ' ';
      if (idx >= 0 && idx < 96)
        {
          memcpy(&buf[(col + i) * 8], g_oled_font[idx], 8);
        }
    }
}

static int oled_show_adc_data(uint16_t *raw_values, uint32_t *mv_values)
{
  int fd;
  uint8_t buf[128];
  char text[17];
  int ret;
  int i;

  fd = open(OLED_I2C_PATH, O_RDWR);
  if (fd < 0)
    {
      return -errno;
    }

  /* Page 0: Title */

  memset(buf, 0, 128);
  oled_text(0, 0, "ADC Monitor", buf);
  oled_write_cmd(fd, 0xB0);
  oled_write_cmd(fd, 0x00);
  oled_write_cmd(fd, 0x10);
  ret = oled_write_data(fd, buf, 128);
  if (ret < 0)
    {
      close(fd);
      return ret;
    }

  /* Pages 1-3: CH1/CH2/CH3 */

  for (i = 0; i < ADC_NUM_CHANNELS; i++)
    {
      snprintf(text, sizeof(text), "%s %4u %u.%03uV",
               g_channel_labels[i], raw_values[i],
               mv_values[i] / 1000, mv_values[i] % 1000);

      memset(buf, 0, 128);
      oled_text(i + 1, 0, text, buf);

      oled_write_cmd(fd, 0xB0 + i + 1);
      oled_write_cmd(fd, 0x00);
      oled_write_cmd(fd, 0x10);
      ret = oled_write_data(fd, buf, 128);
      if (ret < 0)
        {
          close(fd);
          return ret;
        }
    }

  close(fd);
  return 0;
}

