{
  int ret;
  uint32_t brint;
  uint32_t cfg5_val;
  uint32_t sr1;
  uint32_t cfg3;
  uint32_t cr1;

  printf("[MCP3204] Hardware SPI2 init\n");

  /* Open CS GPIO */

  ret = pinctrl_set_gpio_function(MCP3204_CS_PIN);
  if (ret < 0)
    {
      printf("[MCP3204] ERROR: pinctrl CS GPIO%d: %d\n", MCP3204_CS_PIN, ret);
      return ret;
    }

  g_fd_cs = open("/dev/gpio67", O_RDWR);
  if (g_fd_cs < 0)
    {
      printf("[MCP3204] ERROR: open CS GPIO%d: %d\n", MCP3204_CS_PIN, errno);
      return -errno;
    }

  ret = ioctl(g_fd_cs, GPIOC_SETPINTYPE, (unsigned long)GPIO_OUTPUT_PIN);
  if (ret < 0)
    {
      printf("[MCP3204] ERROR: CS set output: %d\n", errno);
      close(g_fd_cs);
      g_fd_cs = -1;
      return -errno;
    }

  /* CS high (deselect) */

  ioctl(g_fd_cs, GPIOC_WRITE, 1);

  /* Enable SPI2/3 module clock gate (CHIP_CTRL05 bits[18:17]) */

  cfg5_val = CFG5_REG;
  printf("[MCP3204] CFG5 before: 0x%08x\n", cfg5_val);
  CFG5_REG = cfg5_val | (0x3u << 17);
  printf("[MCP3204] CFG5 after:  0x%08x\n", CFG5_REG);

  /* Read back SR1 before config */

  sr1 = SPI_REG32(LS_SPI_IO_SR1);
  printf("[MCP3204] SR1 before cfg: 0x%08x\n", sr1);

  /* CFG3: master, full duplex, software CS mode */

  cfg3 = LS_SPI_CFG3_MSTR | LS_SPI_CFG3_DIE |
         LS_SPI_CFG3_DOE | LS_SPI_CFG3_SSMODE_SW;
  SPI_REG32(LS_SPI_IO_CFG3) = cfg3;
  printf("[MCP3204] CFG3 wrote: 0x%08x, readback: 0x%08x\n",
         cfg3, SPI_REG32(LS_SPI_IO_CFG3));

  /* CFG1: SPI mode 0, 8-bit frame */

  SPI_REG32(LS_SPI_IO_CFG1) = LS_SPI_CFG1_DSIZE_8BIT;
  printf("[MCP3204] CFG1 readback: 0x%08x\n", SPI_REG32(LS_SPI_IO_CFG1));

  /* CFG2: baud rate divider = APB / SPI clock */

  brint = SPI_APB_HZ / SPI_CLOCK_HZ;
  if (brint < 2)
    {
      brint = 2;
    }

  if (brint > 255)
    {
      brint = 255;
    }

  SPI_REG32(LS_SPI_IO_CFG2) = brint << LS_SPI_CFG2_BRINT_SHIFT;
  printf("[MCP3204] CFG2 readback: 0x%08x (brint=%u)\n",
         SPI_REG32(LS_SPI_IO_CFG2), brint);

  /* CR1: enable SPI (must be after CFG writes) */

  SPI_REG32(LS_SPI_IO_CR1) = LS_SPI_CR1_SPE;
  cr1 = SPI_REG32(LS_SPI_IO_CR1);
  printf("[MCP3204] CR1 readback: 0x%08x\n", cr1);

  /* Check SR1 after init */

  sr1 = SPI_REG32(LS_SPI_IO_SR1);
  printf("[MCP3204] SR1 after init: 0x%08x (TXA=%d RXA=%d RXE=%d EOT=%d)\n",
         sr1,
         (sr1 & LS_SPI_SR1_TXA) ? 1 : 0,
         (sr1 & LS_SPI_SR1_RXA) ? 1 : 0,
         (sr1 & LS_SPI_SR1_RXE) ? 1 : 0,
         (sr1 & LS_SPI_SR1_EOT) ? 1 : 0);

  printf("[MCP3204] SPI2 base=0x%lx, mode=0, sclk=%lu Hz\n",
         (unsigned long)SPI2_BASE, SPI_CLOCK_HZ);
  printf("[MCP3204] SCK=GPIO64 MISO=GPIO65 MOSI=GPIO66 CS=GPIO67\n");
  printf("[MCP3204] Vref=%u mV\n", MCP3204_VREF_MV);
  return 0;
