/****************************************************************************
 * Private Functions - Software PWM (GPIO bit-bang)
 ****************************************************************************/

#define SERVO_PERIOD_US    20000  /* 20ms = 50Hz */

/* Init servo GPIO pins */

static int servo_init(void)
{
  int i;
  int ret;

  for (i = 0; i < PWM_SERVO_COUNT; i++)
    {
      ret = pinctrl_set_gpio_function(g_servo_gpios[i]);
      if (ret < 0)
        {
          printf("[ADC] ERROR: pinctrl GPIO%d: %d\n", g_servo_gpios[i], ret);
          return ret;
        }

      g_servo_fds[i] = open("/dev/gpioXX", O_RDWR);

      /* Open GPIO device */

      {
        char path[32];
        snprintf(path, sizeof(path), "/dev/gpio%d", g_servo_gpios[i]);
        g_servo_fds[i] = open(path, O_RDWR);
      }

      if (g_servo_fds[i] < 0)
        {
          printf("[ADC] ERROR: open GPIO%d: %d\n", g_servo_gpios[i], errno);
          return -errno;
        }

      ret = ioctl(g_servo_fds[i], GPIOC_SETPINTYPE,
                  (unsigned long)GPIO_OUTPUT_PIN);
      if (ret < 0)
        {
          printf("[ADC] ERROR: GPIOC_SETPINTYPE GPIO%d: %d\n",
                 g_servo_gpios[i], errno);
          close(g_servo_fds[i]);
          g_servo_fds[i] = -1;
          return -errno;
        }

      /* Output low initially */

      ioctl(g_servo_fds[i], GPIOC_WRITE, 0);
    }

  printf("[ADC] Servo GPIO init: %d/%d/%d/%d\n",
         g_servo_gpios[0], g_servo_gpios[1],
         g_servo_gpios[2], g_servo_gpios[3]);
  return 0;
}

/* voltage_mv: target voltage in millivolts (0-3300)
 * pulse_us = voltage_mv / 3300 * 20000 (SERVO_PERIOD_US)
 */

static int servo_set_voltage(int index, int voltage_mv)
{
  int pulse_us;
  int fd;

  if (index < 0 || index >= PWM_SERVO_COUNT)
    {
      return -EINVAL;
    }

  fd = g_servo_fds[index];
  if (fd < 0)
    {
      return -ENODEV;
    }

  /* Convert voltage to pulse width: pulse_us = V / 3.3V * 20000 */

  pulse_us = (int)((uint32_t)voltage_mv * SERVO_PERIOD_US / 3300);
  if (pulse_us < 0)
    {
      pulse_us = 0;
    }

  if (pulse_us > SERVO_PERIOD_US)
    {
      pulse_us = SERVO_PERIOD_US;
    }

  /* Output one PWM cycle: HIGH for pulse_us, LOW for remainder */

  ioctl(fd, GPIOC_WRITE, 1);
  up_udelay(pulse_us);
  ioctl(fd, GPIOC_WRITE, 0);
  up_udelay(SERVO_PERIOD_US - pulse_us);

  return 0;
}

static void servo_deinit(void)
{
  int i;

  for (i = 0; i < PWM_SERVO_COUNT; i++)
    {
      if (g_servo_fds[i] >= 0)
        {
          ioctl(g_servo_fds[i], GPIOC_WRITE, 0);
          close(g_servo_fds[i]);
          g_servo_fds[i] = -1;
        }
    }
}

