# SPI ADC 驱动设计文档（MCP3204 范例）

## 1. 功能概述

通过硬件 SPI 控制器读取 MCP3204 12 位 ADC 的模拟电压值。

### MCP3204 特性
- 12 位 SAR ADC
- 4 通道单端输入（CH0~CH3）
- SPI 接口，最高 1.2MHz
- 参考电压 VREF 由外部提供

## 2. SPI 时序要求

### 2.1 SPI 模式

MCP3204 使用 **SPI Mode 0**（CPOL=0, CPHA=0）：
- 空闲时 SCK 为低电平
- 数据在 SCK 上升沿采样
- 数据在 SCK 下降沿变化

### 2.2 传输时序

```
CS:  ‾‾‾\___________________________________/‾‾‾
SCK: ____|‾|_|‾|_|‾|_|‾|_|‾|_|‾|_|‾|_|‾|_|‾|____
MOSI:    |S|D|D|D|D|D|D|D|D|x|x|x|x|x|x|x|x|
MISO:    |x|N|D11|D10|D9|D8|D7|D6|D5|D4|D3|D2|D1|D0|x|x|
```

### 2.3 命令字节格式

| 字节 | 内容 | 说明 |
|------|------|------|
| Byte 1 | `0x06` | Start bit=1, Single-ended=1, D2=0 |
| Byte 2 | `channel << 6` | D2=0, D1/D0=通道号 |
| Byte 3 | `0x00` | 无关紧要，用于接收数据 |

### 2.4 接收数据格式

| 字节 | 位内容 |
|------|--------|
| Byte 1 响应 | `null, D11, D10, D9, D8, D7, D6, D5`（延迟 1 位） |
| Byte 2 响应 | `D5, D4, D3, D2, D1, D0, x, x` |
| Byte 3 响应 | 无效数据 |

**注意**：硬件 SPI 存在 1 位流水线延迟，第一个字节的响应在第二个字节传输时才读出。

## 3. 硬件 SPI 控制器配置

### 3.1 初始化流程

```c
/* Step 1: 使能 SPI 时钟门控 */
CFG5_REG |= (0x3u << <clock_gate_bit>);

/* Step 2: 配置 CFG3 - 主模式、全双工、软件 CS */
SPI_REG32(CFG3_OFFSET) = MSTR | DIE | DOE | SSMODE_SW;

/* Step 3: 配置 CFG1 - 8-bit 帧、SPI Mode 0 */
SPI_REG32(CFG1_OFFSET) = DSIZE_8BIT;

/* Step 4: 配置 CFG2 - 波特率分频 */
uint32_t brint = APB_HZ / TARGET_CLOCK_HZ;
SPI_REG32(CFG2_OFFSET) = brint << BRINT_SHIFT;

/* Step 5: 使能 SPI */
SPI_REG32(CR1_OFFSET) = SPE;
```

### 3.2 单字节传输函数

```c
static int spi_xfer_byte(uint8_t tx, uint8_t *rx)
{
  uint32_t val, sr1;
  uint32_t i;

  /* 1. 使能 SPI */
  val = SPI_REG32(CR1_OFFSET);
  val |= SPE;
  SPI_REG32(CR1_OFFSET) = val;

  /* 2. 终止挂起的传输 */
  val = SPI_REG32(CR1_OFFSET);
  val &= ~(CSTART | AUTOSUS);
  SPI_REG32(CR1_OFFSET) = val;

  /* 3. 清空 FIFO */
  SPI_REG32(CR4_OFFSET) = 0;
  SPI_REG32(CR3_OFFSET) = 0;
  up_udelay(5);

  /* 4. 清除状态标志 */
  SPI_REG32(SR1_OFFSET) = W1C_FLAGS;
  up_udelay(1);

  /* 5. 排空 RXFIFO */
  for (i = 0; i < 4; i++)
    {
      sr1 = SPI_REG32(SR1_OFFSET);
      if (sr1 & RXE) break;
      (void)(uint8_t)SPI_REG32(DR_OFFSET);
    }

  /* 6. 发送数据 */
  SPI_REG32(CR3_OFFSET) = 0;
  SPI_REG32(DR_OFFSET) = tx;

  /* 7. 启动传输 */
  val = SPI_REG32(CR1_OFFSET);
  val |= CSTART;
  SPI_REG32(CR1_OFFSET) = val;

  /* 8. 等待 RX 数据 */
  for (i = 0; i < TIMEOUT_US; i++)
    {
      sr1 = SPI_REG32(SR1_OFFSET);
      if (sr1 & RXA)
        {
          if (rx) *rx = (uint8_t)SPI_REG32(DR_OFFSET);
          else     (void)(uint8_t)SPI_REG32(DR_OFFSET);

          val = SPI_REG32(CR1_OFFSET);
          val &= ~(CSTART | AUTOSUS);
          SPI_REG32(CR1_OFFSET) = val;
          return 0;
        }
      up_udelay(1);
    }

  /* 9. 超时 fallback：尝试直接读 DR */
  sr1 = SPI_REG32(SR1_OFFSET);
  if (!(sr1 & RXE))
    {
      if (rx) *rx = (uint8_t)SPI_REG32(DR_OFFSET);
      else     (void)(uint8_t)SPI_REG32(DR_OFFSET);

      val = SPI_REG32(CR1_OFFSET);
      val &= ~(CSTART | AUTOSUS);
      SPI_REG32(CR1_OFFSET) = val;
      return 0;
    }

  /* 10. 失败：中止传输 */
  spi_abort();
  return -1;
}
```

### 3.3 关键注意事项

> ⚠️ **超时 fallback 必须保留**：SPI 控制器可能在 RXA 标志未置位时已有数据在 DR 中。
> 删除 fallback 会导致 SPI 通信完全失败（所有读取返回 0xff）。

## 4. 片选（CS）控制

使用 GPIO 软件控制 CS：

```c
/* CS 拉低 - 开始传输 */
ioctl(cs_fd, GPIOC_WRITE, 0);
up_udelay(1);

/* 执行 SPI 传输 */
spi_xfer_byte(tx1, NULL);
spi_xfer_byte(tx2, &rx_hi);
spi_xfer_byte(tx3, &rx_lo);

/* CS 拉高 - 结束传输 */
ioctl(cs_fd, GPIOC_WRITE, 1);
up_udelay(1);
```

## 5. MCP3204 读取完整流程

```c
int mcp3204_read(uint8_t channel, uint16_t *raw)
{
  uint8_t rx_hi = 0, rx_lo = 0;

  /* CS 低 */
  ioctl(cs_fd, GPIOC_WRITE, 0);
  up_udelay(1);

  /* 发送 3 字节命令 */
  if (spi_xfer_byte(0x06, NULL) != 0 ||               /* Start + Single-ended */
      spi_xfer_byte((channel << 6), &rx_hi) != 0 ||   /* 通道号 */
      spi_xfer_byte(0x00, &rx_lo) != 0)               /* 接收数据 */
    {
      ioctl(cs_fd, GPIOC_WRITE, 1);
      return -1;
    }

  /* CS 高 */
  ioctl(cs_fd, GPIOC_WRITE, 1);
  up_udelay(1);

  /* 过滤无效数据 */
  if (rx_hi == 0xff || rx_lo == 0xff)
    return -1;

  /* 提取 12 位 ADC 值 */
  *raw = ((uint16_t)(rx_hi & 0x0F) << 8) | rx_lo;
  return 0;
}
```

## 6. 电压换算

```c
uint32_t adc_to_voltage_mv(uint16_t raw, uint32_t vref_mv)
{
  return ((uint32_t)raw * vref_mv + (ADC_MAX / 2)) / ADC_MAX;
}
```

> ⚠️ **使用整数运算**：LoongArch 默认无 FPU，禁止使用 float/double。

## 7. 防误码与重试

```c
int mcp3204_read_average(uint8_t channel, uint16_t *raw, int samples)
{
  uint32_t sum = 0;
  int valid = 0;

  for (int i = 0; i < samples * 8; i++)  /* 最多重试 8 倍 */
    {
      uint16_t value;
      if (mcp3204_read(channel, &value) != 0)
        {
          up_mdelay(2);
          continue;  /* 跳过坏数据，继续采样 */
        }

      sum += value;
      if (++valid >= samples)
        break;

      up_mdelay(2);
    }

  if (valid == 0) return -1;

  *raw = (sum + valid / 2) / valid;
  return 0;
}
```

## 8. 调试技巧

1. **所有读取返回 0xff**：
   - 检查 SPI 时钟门控是否使能（CFG5）
   - 检查引脚复用是否配置为 SPI 功能
   - 确认 `spi_xfer_byte` 包含超时 fallback 代码

2. **读数不随输入变化**：
   - 检查 CS 是否正确控制（GPIO 方向、电平）
   - 用示波器观察 SCK/MOSI/MISO 波形

3. **读数偏差较大**：
   - 检查 VREF 电压是否稳定
   - 增加采样平均次数
   - 添加 0xff 过滤逻辑

# I2C 光照传感器驱动设计文档（BH1750 范例）

## 1. 功能概述

通过 I2C 总线读取 BH1750 环境光传感器的光照强度值。

### BH1750 特性
- I2C 接口，7-bit 地址 `0x23`（ADDR 引脚低）或 `0x5C`（ADDR 引脚高）
- 分辨率：1 lux
- 测量范围：1~65535 lux
- 两种测量模式：连续/单次 × 高/低分辨率

## 2. I2C 总线配置

### 2.1 I2C 时序参数

| 参数 | 标准模式 | 快速模式 |
|------|---------|---------|
| 时钟频率 | 100 kHz | 400 kHz |
| SCL 高电平 | 4.0 μs | 0.6 μs |
| SCL 低电平 | 4.7 μs | 1.3 μs |

### 2.2 NuttX I2C API

```c
/* 打开 I2C 设备 */
int fd = open("/dev/i2c<N>", O_RDWR);

/* 构造传输消息 */
struct i2c_msg_s msg;
msg.addr   = <slave_addr>;     /* 7-bit 地址，无需左移 */
msg.flags  = 0;                /* 写操作 */
msg.buffer = tx_buf;
msg.length = tx_len;

struct i2c_transfer_s xfer;
xfer.msgv = &msg;
xfer.msgc = 1;

/* 执行传输 */
ioctl(fd, I2CIOC_TRANSFER, &xfer);
```

> ⚠️ **注意**：NuttX 的 `I2CIOC_TRANSFER`（非 `I2C_TRANSFER`），地址无需左移。

## 3. BH1750 命令集

| 命令 | 字节 | 说明 |
|------|------|------|
| 断电 | `0x00` | 进入低功耗模式 |
| 通电 | `0x01` | 等待测量指令 |
| 重置 | `0x07` | 重置数据寄存器 |
| 连续高分辨率 | `0x10` | 连续模式，1 lux 分辨率 |
| 连续高分辨率2 | `0x11` | 连续模式，0.5 lux 分辨率 |
| 连续低分辨率 | `0x13` | 连续模式，4 lux 分辨率 |
| 单次高分辨率 | `0x20` | 单次模式，1 lux 分辨率 |
| 单次高分辨率2 | `0x21` | 单次模式，0.5 lux 分辨率 |
| 单次低分辨率 | `0x23` | 单次模式，4 lux 分辨率 |

## 4. 初始化流程

```c
int bh1750_init(int fd)
{
  uint8_t cmd;
  struct i2c_msg_s msg;
  struct i2c_transfer_s xfer;

  /* Step 1: 上电 */
  cmd = BH1750_POWER_ON;
  msg.addr   = BH1750_ADDR;
  msg.flags  = 0;
  msg.buffer = &cmd;
  msg.length = 1;
  xfer.msgv  = &msg;
  xfer.msgc  = 1;
  ioctl(fd, I2CIOC_TRANSFER, &xfer);

  /* Step 2: 重置 */
  cmd = BH1750_RESET;
  msg.buffer = &cmd;
  msg.length = 1;
  ioctl(fd, I2CIOC_TRANSFER, &xfer);

  up_mdelay(10);
  return 0;
}
```

## 5. 读取流程

### 5.1 单次读取

```c
int bh1750_read_once(int fd, uint16_t *lux)
{
  uint8_t cmd;
  uint8_t buf[2];
  struct i2c_msg_s msgs[2];
  struct i2c_transfer_s xfer;

  /* Step 1: 发送单次测量命令 */
  cmd = BH1750_ONE_HRES;
  msgs[0].addr   = BH1750_ADDR;
  msgs[0].flags  = 0;           /* 写 */
  msgs[0].buffer = &cmd;
  msgs[0].length = 1;

  xfer.msgv = &msgs[0];
  xfer.msgc = 1;
  ioctl(fd, I2CIOC_TRANSFER, &xfer);

  /* Step 2: 等待测量完成（高分辨率约 180ms） */
  up_mdelay(180);

  /* Step 3: 读取 2 字节结果 */
  msgs[0].addr   = BH1750_ADDR;
  msgs[0].flags  = I2C_M_READ;  /* 读 */
  msgs[0].buffer = buf;
  msgs[0].length = 2;

  xfer.msgv = &msgs[0];
  xfer.msgc = 1;
  ioctl(fd, I2CIOC_TRANSFER, &xfer);

  /* Step 4: 合并高低字节 */
  *lux = ((uint16_t)buf[0] << 8) | buf[1];

  return 0;
}
```

### 5.2 数值换算

```c
/* BH1750 原始值 → 实际 lux（整数运算） */
uint32_t bh1750_raw_to_lux(uint16_t raw)
{
  /* 原始值 / 1.2 ≈ 实际 lux */
  /* 用整数：raw * 10 / 12 */
  return ((uint32_t)raw * 10 + 6) / 12;
}
```

## 6. 连续读取模式

```c
int bh1750_start_continuous(int fd)
{
  uint8_t cmd = BH1750_CONT_HRES;
  struct i2c_msg_s msg;
  struct i2c_transfer_s xfer;

  msg.addr   = BH1750_ADDR;
  msg.flags  = 0;
  msg.buffer = &cmd;
  msg.length = 1;
  xfer.msgv  = &msg;
  xfer.msgc  = 1;

  return ioctl(fd, I2CIOC_TRANSFER, &xfer);
}

int bh1750_read_continuous(int fd, uint16_t *lux)
{
  uint8_t buf[2];
  struct i2c_msg_s msg;
  struct i2c_transfer_s xfer;

  msg.addr   = BH1750_ADDR;
  msg.flags  = I2C_M_READ;
  msg.buffer = buf;
  msg.length = 2;
  xfer.msgv  = &msg;
  xfer.msgc  = 1;

  int ret = ioctl(fd, I2CIOC_TRANSFER, &xfer);
  if (ret < 0) return ret;

  *lux = ((uint16_t)buf[0] << 8) | buf[1];
  return 0;
}
```

## 7. 注意事项

1. **I2C 地址**：BH1750 的 7-bit 地址为 `0x23`（ADDR 脚接 GND）或 `0x5C`（ADDR 脚接 VCC）。NuttX 中直接使用 7-bit 地址，无需左移。
2. **测量等待时间**：高分辨率模式需等待 180ms，低分辨率需等待 24ms。
3. **时钟频率**：BH1750 支持最高 400kHz（快速模式）。
4. **上拉电阻**：I2C 总线需要外部上拉电阻（4.7kΩ 典型值）。
5. **无 FPU**：lux 换算使用整数运算 `raw * 10 / 12` 替代 `raw / 1.2`。

## 8. 调试技巧

1. **I2C 通信失败**：
   - 用 `i2cdetect` 工具扫描总线，确认设备地址
   - 检查 SDA/SCL 上拉电阻
   - 确认 I2C 时钟频率设置

2. **读数始终为 0**：
   - 确认已发送上电命令
   - 确认已发送测量命令并等待足够时间

3. **读数异常偏大/偏小**：
   - 检查遮光/漏光情况
   - 确认换算公式正确

# I2C OLED 显示屏驱动设计文档（SSD1306 范例）

## 1. 功能概述

通过 I2C 总线控制 SSD1306 OLED 显示屏，支持：
- 初始化配置
- 清屏/填充
- 字符/字符串显示
- 像素级绘图

### SSD1306 特性
- I2C 地址：`0x3C`（SA0=0）或 `0x3D`（SA0=1）
- 分辨率：128×64 像素
- 显存：128×64 / 8 = 1024 字节（8 页 × 128 列）
- 两种数据模式：命令（`0x00`）和数据（`0x40`）

## 2. I2C 通信格式

SSD1306 I2C 数据帧格式：

```
[START] [ADDR+W] [CONTROL] [DATA] [STOP]
```

- **CONTROL 字节**：
  - `0x00`：后续为命令字节
  - `0x40`：后续为显示数据
  - `0x80`：后续为单个命令（Co=1, D/C=0）
  - `0xC0`：后续为单个数据（Co=1, D/C=1）

### 2.1 发送命令

```c
int oled_send_cmd(int fd, uint8_t cmd)
{
  uint8_t buf[2] = { 0x00, cmd };  /* CONTROL=0x00, CMD */
  struct i2c_msg_s msg;
  struct i2c_transfer_s xfer;

  msg.addr   = OLED_I2C_ADDR;
  msg.flags  = 0;
  msg.buffer = buf;
  msg.length = 2;
  xfer.msgv  = &msg;
  xfer.msgc  = 1;

  return ioctl(fd, I2CIOC_TRANSFER, &xfer);
}
```

### 2.2 发送数据

```c
int oled_send_data(int fd, const uint8_t *data, int len)
{
  /* 需要先发 CONTROL 字节 0x40 */
  uint8_t *buf = malloc(len + 1);
  buf[0] = 0x40;
  memcpy(&buf[1], data, len);

  struct i2c_msg_s msg;
  struct i2c_transfer_s xfer;

  msg.addr   = OLED_I2C_ADDR;
  msg.flags  = 0;
  msg.buffer = buf;
  msg.length = len + 1;
  xfer.msgv  = &msg;
  xfer.msgc  = 1;

  int ret = ioctl(fd, I2CIOC_TRANSFER, &xfer);
  free(buf);
  return ret;
}
```

## 3. 初始化序列

```c
int oled_init(int fd)
{
  /* 关闭显示 */
  oled_send_cmd(fd, 0xAE);  /* Display OFF */

  /* 设置时钟分频 */
  oled_send_cmd(fd, 0xD5);  /* Set Display Clock */
  oled_send_cmd(fd, 0x80);  /* 分频比=1, 频率=100Hz */

  /* 设置多路复用率 */
  oled_send_cmd(fd, 0xA8);  /* Set Multiplex Ratio */
  oled_send_cmd(fd, 0x3F);  /* 64-1 (1/64 duty) */

  /* 设置显示偏移 */
  oled_send_cmd(fd, 0xD3);  /* Set Display Offset */
  oled_send_cmd(fd, 0x00);  /* 无偏移 */

  /* 设置起始行 */
  oled_send_cmd(fd, 0x40);  /* Set Start Line = 0 */

  /* 电荷泵设置 */
  oled_send_cmd(fd, 0x8D);  /* Charge Pump */
  oled_send_cmd(fd, 0x14);  /* 使能电荷泵 */

  /* 寻址模式：页寻址 */
  oled_send_cmd(fd, 0x20);  /* Set Memory Addressing Mode */
  oled_send_cmd(fd, 0x02);  /* Page Addressing Mode */

  /* 段重映射：列127映射到SEG0 */
  oled_send_cmd(fd, 0xA1);  /* Set Segment Re-map */

  /* COM 输出扫描方向：从 COM[N-1] 到 COM0 */
  oled_send_cmd(fd, 0xC8);  /* Set COM Output Scan Direction */

  /* COM 引脚硬件配置 */
  oled_send_cmd(fd, 0xDA);  /* Set COM Pins */
  oled_send_cmd(fd, 0x12);  /* Alternative COM config */

  /* 对比度 */
  oled_send_cmd(fd, 0x81);  /* Set Contrast */
  oled_send_cmd(fd, 0xCF);  /* 对比度=207 */

  /* 预充电周期 */
  oled_send_cmd(fd, 0xD9);  /* Set Pre-charge Period */
  oled_send_cmd(fd, 0xF1);

  /* VCOMH 取消选择电平 */
  oled_send_cmd(fd, 0xDB);  /* Set VCOMH Deselect Level */
  oled_send_cmd(fd, 0x40);  /* 0.83 × VCC */

  /* 全局显示开启 */
  oled_send_cmd(fd, 0xA4);  /* Entire Display ON (resume) */

  /* 正常显示（非反色） */
  oled_send_cmd(fd, 0xA6);  /* Normal Display */

  /* 开启显示 */
  oled_send_cmd(fd, 0xAF);  /* Display ON */

  return 0;
}
```

## 4. 页寻址模式

SSD1306 页寻址模式下的显存结构：

```
Page 0: [COM0: bit0 of each byte]   COL0 COL1 ... COL127
Page 1: [COM8: bit0 of each byte]   COL0 COL1 ... COL127
...
Page 7: [COM56: bit0 of each byte]  COL0 COL1 ... COL127
```

每页 128 字节，共 8 页 × 128 = 1024 字节。

### 4.1 设置光标位置

```c
void oled_set_cursor(int fd, uint8_t page, uint8_t col)
{
  oled_send_cmd(fd, 0xB0 + page);  /* 设置页地址 */
  oled_send_cmd(fd, 0x00 + (col & 0x0F));  /* 列地址低 4 位 */
  oled_send_cmd(fd, 0x10 + (col >> 4));    /* 列地址高 4 位 */
}
```

## 5. 显示函数

### 5.1 清屏

```c
void oled_clear(int fd)
{
  uint8_t zeros[128];
  memset(zeros, 0, 128);

  for (int page = 0; page < 8; page++)
    {
      oled_set_cursor(fd, page, 0);
      oled_send_data(fd, zeros, 128);
    }
}
```

### 5.2 显示字符

```c
/* 6×8 字体，每字符 6 字节（含间距） */
static const uint8_t font_6x8[][6] = {
  /* ASCII 32~126 的字模数据 */
  /* ... */
};

void oled_putchar(int fd, uint8_t page, uint8_t col, char ch)
{
  if (ch < 32 || ch > 126) ch = ' ';
  oled_set_cursor(fd, page, col);
  oled_send_data(fd, font_6x8[ch - 32], 6);
}

void oled_puts(int fd, uint8_t page, uint8_t col, const char *str)
{
  while (*str)
    {
      oled_putchar(fd, page, col, *str);
      col += 6;
      if (col > 122)  /* 超出右边界，换行 */
        {
          col = 0;
          page++;
          if (page >= 8) return;
        }
      str++;
    }
}
```

### 5.3 显示数值

```c
void oled_show_number(int fd, uint8_t page, uint8_t col,
                      uint32_t value, int decimals)
{
  char buf[16];
  /* 整数转字符串（无 FPU，不使用 sprintf 浮点） */
  int len = 0;
  uint32_t tmp = value;

  /* 提取各位数字 */
  do
    {
      buf[len++] = '0' + (tmp % 10);
      tmp /= 10;
    }
  while (tmp > 0 && len < 15);

  /* 反转 */
  for (int i = 0; i < len / 2; i++)
    {
      char t = buf[i];
      buf[i] = buf[len - 1 - i];
      buf[len - 1 - i] = t;
    }

  buf[len] = '\0';
  oled_puts(fd, page, col, buf);
}
```

## 6. 显存缓冲模式

对于频繁更新的显示，可使用显存缓冲区减少 I2C 传输次数：

```c
static uint8_t g_framebuf[8][128];  /* 1024 字节显存 */

void oled_pixel(int x, int y, int on)
{
  if (x >= 128 || y >= 64) return;
  if (on)
    g_framebuf[y / 8][x] |= (1 << (y % 8));
  else
    g_framebuf[y / 8][x] &= ~(1 << (y % 8));
}

void oled_refresh(int fd)
{
  for (int page = 0; page < 8; page++)
    {
      oled_set_cursor(fd, page, 0);
      oled_send_data(fd, g_framebuf[page], 128);
    }
}
```

## 7. 注意事项

1. **I2C 地址**：SSD1306 默认地址 `0x3C`。NuttX 中直接使用 7-bit 地址。
2. **传输长度限制**：单次 I2C 传输建议不超过 128+1 字节（CONTROL + 128 字节数据）。
3. **初始化顺序**：必须先关闭显示（0xAE），配置完成后再开启（0xAF）。
4. **电荷泵**：使用内部 DC-DC 时必须使能电荷泵（0x8D, 0x14）。
5. **字体数据**：需预先准备字模数组，常用 6×8 或 8×16 字体。
6. **无 FPU**：数值显示使用整数运算，禁止 `sprintf("%f", ...)`。

## 8. 调试技巧

1. **屏幕无显示**：
   - 检查 I2C 地址是否正确
   - 确认电荷泵已使能
   - 确认显示已开启（0xAF）

2. **显示乱码**：
   - 检查寻址模式是否正确设置
   - 确认段重映射和 COM 扫描方向

3. **部分区域不显示**：
   - 检查页地址和列地址设置
   - 确认数据传输长度正确

/****************************************************************************
 * gpio_led_template.c
 *
 * GPIO LED 驱动模板 - 龙芯 2K300 NuttX 平台
 *
 * 使用方法：
 *   1. 替换 <PIN_NUMBER> 为实际 GPIO 引脚号
 *   2. 替换 DEVICE_NAME 为实际设备名称
 *   3. 根据原理图确认 LED 是高电平驱动还是低电平驱动
 *
 * 编译条件：
 *   CONFIG_GPIO=y
 *   CONFIG_IOEXPANDER=y
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <sys/ioctl.h>
#include <stdio.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdint.h>
#include <nuttx/ioexpander/gpio.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* 配置项 - 根据实际硬件修改 */

#define LED_PIN         <PIN_NUMBER>       /* GPIO 引脚号 */
#define LED_GPIO_PATH   "/dev/gpio<PIN_NUMBER>"  /* GPIO 设备路径 */
#define LED_BLINK_MS    500                /* 闪烁间隔（毫秒） */
#define LED_ACTIVE_HIGH 1                  /* 1=高电平亮，0=低电平亮 */

/* pinctrl 设置函数（需在板级代码中实现） */

extern int pinctrl_set_gpio_function(int pin);

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int gpio_led_demo(void)
{
  int fd;
  int ret;
  int state = 0;

  printf("[LED] GPIO LED Demo on pin %d\n", LED_PIN);

  /* Step 1: 设置引脚为 GPIO 模式 */

  ret = pinctrl_set_gpio_function(LED_PIN);
  if (ret < 0)
    {
      printf("[LED] ERROR: pinctrl pin %d: %d\n", LED_PIN, ret);
      return ret;
    }

  /* Step 2: 打开 GPIO 设备 */

  fd = open(LED_GPIO_PATH, O_RDWR);
  if (fd < 0)
    {
      printf("[LED] ERROR: open %s: %d\n", LED_GPIO_PATH, errno);
      return -errno;
    }

  /* Step 3: 设置为输出模式 */

  ret = ioctl(fd, GPIOC_SETPINTYPE, (unsigned long)GPIO_OUTPUT_PIN);
  if (ret < 0)
    {
      printf("[LED] ERROR: set output: %d\n", errno);
      close(fd);
      return -errno;
    }

  /* Step 4: 心跳灯循环 */

  printf("[LED] Blinking at %d ms interval...\n", LED_BLINK_MS);

  for (int i = 0; i < 20; i++)
    {
      state ^= 1;
      int value = LED_ACTIVE_HIGH ? state : !state;
      ioctl(fd, GPIOC_WRITE, value);
      up_mdelay(LED_BLINK_MS);
    }

  /* Step 5: 关闭 */

  ioctl(fd, GPIOC_WRITE, LED_ACTIVE_HIGH ? 0 : 1);  /* 熄灭 */
  close(fd);

  printf("[LED] Done.\n");
  return 0;
}

/****************************************************************************
 * gpio_key_template.c
 *
 * GPIO 按键驱动模板 - 龙芯 2K300 NuttX 平台
 *
 * 使用方法：
 *   1. 替换 <PIN_NUMBER> 为实际 GPIO 引脚号
 *   2. 替换 <IRQ_NUMBER> 为实际中断号（通常与 GPIO 编号相关）
 *   3. 根据原理图确认按键触发电平（按下=0 或 按下=1）
 *
 * 编译条件：
 *   CONFIG_GPIO=y
 *   CONFIG_IOEXPANDER=y
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <sys/ioctl.h>
#include <stdio.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdint.h>
#include <nuttx/ioexpander/gpio.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* 配置项 - 根据实际硬件修改 */

#define KEY_PIN         <PIN_NUMBER>       /* GPIO 引脚号 */
#define KEY_GPIO_PATH   "/dev/gpio<PIN_NUMBER>"  /* GPIO 设备路径 */
#define KEY_IRQ         <IRQ_NUMBER>       /* 中断号 */
#define KEY_ACTIVE_LOW  1                  /* 1=按下为低电平，0=按下为高电平 */
#define DEBOUNCE_MS     20                 /* 消抖时间 */

/* pinctrl 设置函数（需在板级代码中实现） */

extern int pinctrl_set_gpio_function(int pin);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static volatile int g_key_pressed = 0;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: key_interrupt
 *
 * Description: GPIO 中断回调函数
 *
 ****************************************************************************/

static int key_interrupt(int irq, void *context, void *arg)
{
  g_key_pressed = 1;
  return OK;
}

/****************************************************************************
 * Name: key_read_debounced
 *
 * Description: 带消抖的按键读取
 *
 * 返回值: 1=确认按下, 0=未按下, -1=抖动中
 *
 ****************************************************************************/

static int key_read_debounced(int fd)
{
  int val1, val2;

  ioctl(fd, GPIOC_READ, &val1);
  up_mdelay(DEBOUNCE_MS);
  ioctl(fd, GPIOC_READ, &val2);

  if (val1 != val2)
    {
      return -1;  /* 抖动 */
    }

#if KEY_ACTIVE_LOW
  return (val1 == 0) ? 1 : 0;
#else
  return (val1 != 0) ? 1 : 0;
#endif
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: gpio_key_poll_demo
 *
 * Description: 轮询方式读取按键
 *
 ****************************************************************************/

int gpio_key_poll_demo(void)
{
  int fd;
  int ret;

  printf("[KEY] GPIO Key Poll Demo on pin %d\n", KEY_PIN);

  /* 设置引脚为 GPIO 模式 */

  ret = pinctrl_set_gpio_function(KEY_PIN);
  if (ret < 0)
    {
      printf("[KEY] ERROR: pinctrl pin %d: %d\n", KEY_PIN, ret);
      return ret;
    }

  /* 打开 GPIO 设备 */

  fd = open(KEY_GPIO_PATH, O_RDWR);
  if (fd < 0)
    {
      printf("[KEY] ERROR: open %s: %d\n", KEY_GPIO_PATH, errno);
      return -errno;
    }

  /* 设置为输入模式 */

  ret = ioctl(fd, GPIOC_SETPINTYPE, (unsigned long)GPIO_INPUT_PIN);
  if (ret < 0)
    {
      printf("[KEY] ERROR: set input: %d\n", errno);
      close(fd);
      return -errno;
    }

  /* 轮询读取 */

  printf("[KEY] Polling for key press (press any key 5 times)...\n");

  int count = 0;
  while (count < 5)
    {
      int pressed = key_read_debounced(fd);
      if (pressed == 1)
        {
          count++;
          printf("[KEY] Key pressed! (%d/5)\n", count);
          /* 等待释放 */
          int val;
          do
            {
              ioctl(fd, GPIOC_READ, &val);
              up_mdelay(10);
            }
          while (
#if KEY_ACTIVE_LOW
            val == 0
#else
            val != 0
#endif
          );
        }
      up_mdelay(10);
    }

  close(fd);
  printf("[KEY] Done.\n");
  return 0;
}

/****************************************************************************
 * Name: gpio_key_irq_demo
 *
 * Description: 中断方式读取按键
 *
 ****************************************************************************/

int gpio_key_irq_demo(void)
{
  int fd;
  int ret;

  printf("[KEY] GPIO Key IRQ Demo on pin %d (IRQ %d)\n", KEY_PIN, KEY_IRQ);

  /* 设置引脚为 GPIO 模式 */

  ret = pinctrl_set_gpio_function(KEY_PIN);
  if (ret < 0)
    {
      printf("[KEY] ERROR: pinctrl pin %d: %d\n", KEY_PIN, ret);
      return ret;
    }

  /* 打开 GPIO 设备 */

  fd = open(KEY_GPIO_PATH, O_RDWR);
  if (fd < 0)
    {
      printf("[KEY] ERROR: open %s: %d\n", KEY_GPIO_PATH, errno);
      return -errno;
    }

  /* 设置为输入模式 */

  ioctl(fd, GPIOC_SETPINTYPE, (unsigned long)GPIO_INPUT_PIN);

  /* 注册中断 */

  ret = irq_attach(KEY_IRQ, key_interrupt, NULL);
  if (ret < 0)
    {
      printf("[KEY] ERROR: irq_attach: %d\n", ret);
      close(fd);
      return ret;
    }

  up_enable_irq(KEY_IRQ);

  /* 等待中断 */

  printf("[KEY] Waiting for key interrupt...\n");

  int count = 0;
  while (count < 5)
    {
      if (g_key_pressed)
        {
          g_key_pressed = 0;
          count++;
          printf("[KEY] Key interrupt! (%d/5)\n", count);
          up_mdelay(DEBOUNCE_MS);  /* 消抖 */
        }
      up_mdelay(10);
    }

  up_disable_irq(KEY_IRQ);
  close(fd);

  printf("[KEY] Done.\n");
  return 0;
}

/****************************************************************************
 * spi_template.c
 *
 * SPI ADC 驱动模板（MCP3204） - 龙芯 2K300 NuttX 平台
 *
 * 使用方法：
 *   1. 替换 <SPI_BASE_PHYS> 为 SPI 控制器物理地址
 *   2. 替换 <CS_PIN> 为片选 GPIO 引脚号
 *   3. 替换 <CLOCK_GATE_BIT> 为时钟门控位偏移
 *   4. 根据实际 ADC 型号修改命令字节和数据提取逻辑
 *
 * 编译条件：
 *   CONFIG_SPI=y
 *   CONFIG_GPIO=y
 *   CONFIG_IOEXPANDER=y
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <sys/ioctl.h>
#include <stdio.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <stdint.h>
#include <nuttx/arch.h>
#include <nuttx/ioexpander/gpio.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* SPI 控制器地址 */

#define SPI_BASE_PHYS           <SPI_BASE_PHYS>
#define SPI2_BASE               (0x8000000000000000UL | SPI_BASE_PHYS)

/* 系统配置寄存器（时钟门控） */

#define GENERAL_CFG5_ADDR       (0x8000000000000000UL | <CFG5_PHYS_ADDR>)

/* SPI 寄存器偏移量 */

#define LS_SPI_IO_CR1           0x00
#define LS_SPI_IO_CR3           0x08
#define LS_SPI_IO_CR4           0x0c
#define LS_SPI_IO_SR1           0x14
#define LS_SPI_IO_CFG1          0x20
#define LS_SPI_IO_CFG2          0x24
#define LS_SPI_IO_CFG3          0x28
#define LS_SPI_IO_DR            0x40

/* CR1 位定义 */

#define LS_SPI_CR1_SPE          (1U << 0)
#define LS_SPI_CR1_CSTART       (1U << 1)
#define LS_SPI_CR1_AUTOSUS      (1U << 2)

/* CFG1 位定义 */

#define LS_SPI_CFG1_DSIZE_8BIT  (7U << 8)

/* CFG2 位定义 */

#define LS_SPI_CFG2_BRINT_SHIFT 8

/* CFG3 位定义 */

#define LS_SPI_CFG3_MSTR        (1U << 0)
#define LS_SPI_CFG3_DIE         (1U << 2)
#define LS_SPI_CFG3_DOE         (1U << 3)
#define LS_SPI_CFG3_SSMODE_SW   (1U << 8)

/* SR1 位定义 */

#define LS_SPI_SR1_RXA          (1U << 0)
#define LS_SPI_SR1_TXA          (1U << 1)
#define LS_SPI_SR1_RXE          (1U << 4)
#define LS_SPI_SR1_EOT          (1U << 15)

#define LS_SPI_SR1_W1C_FLAGS    (LS_SPI_SR1_EOT | (1U << 11) | \
                                 (1U << 10) | (1U << 9) | (1U << 8))

/* 时钟配置 */

#define SPI_APB_HZ              (200UL * 1000000UL)
#define SPI_CLOCK_HZ            1000000UL
#define SPI_WAIT_TIMEOUT_US     10000U

/* 片选 GPIO */

#define CS_PIN                  <CS_PIN>
#define CS_GPIO_PATH            "/dev/gpio<CS_PIN>"

/* ADC 参数 */

#define ADC_MAX_VALUE           4095U       /* 12-bit ADC */
#define ADC_VREF_MV             <VREF_MV>   /* 参考电压（mV） */
#define ADC_SAMPLE_COUNT        8           /* 平均采样次数 */

/* 寄存器访问宏 */

#define SPI_REG32(off) (*(volatile uint32_t *)(SPI2_BASE + (off)))
#define CFG5_REG      (*(volatile uint32_t *)GENERAL_CFG5_ADDR)

/* pinctrl 设置函数 */

extern int pinctrl_set_gpio_function(int pin);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static int g_fd_cs = -1;

/****************************************************************************
 * Private Functions - SPI2 Hardware Controller
 ****************************************************************************/

/****************************************************************************
 * Name: spi2_abort
 *
 * Description: 中止 SPI 传输，清空 FIFO
 *
 ****************************************************************************/

static void spi2_abort(void)
{
  uint32_t val;
  uint32_t i;

  val = SPI_REG32(LS_SPI_IO_CR1);
  val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
  SPI_REG32(LS_SPI_IO_CR1) = val;

  SPI_REG32(LS_SPI_IO_CR4) = 0;
  SPI_REG32(LS_SPI_IO_CR3) = 0;
  up_udelay(10);

  SPI_REG32(LS_SPI_IO_SR1) = LS_SPI_SR1_W1C_FLAGS;

  for (i = 0; i < 4; i++)
    {
      if (SPI_REG32(LS_SPI_IO_SR1) & LS_SPI_SR1_RXE)
        {
          break;
        }

      (void)(uint8_t)SPI_REG32(LS_SPI_IO_DR);
    }

  ioctl(g_fd_cs, GPIOC_WRITE, 1);
  up_udelay(1);
}

/****************************************************************************
 * Name: spi2_xfer_byte
 *
 * Description: SPI 单字节全双工传输
 *
 * ⚠️ 警告：超时 fallback 代码不可删除！
 *    SPI 控制器可能在 RXA 标志未置位时已有数据在 DR 中。
 *    删除 fallback 会导致所有读取返回 0xff。
 *
 ****************************************************************************/

static int spi2_xfer_byte(uint8_t tx, uint8_t *rx)
{
  uint32_t val;
  uint32_t sr1;
  uint32_t i;

  val = SPI_REG32(LS_SPI_IO_CR1);
  val |= LS_SPI_CR1_SPE;
  SPI_REG32(LS_SPI_IO_CR1) = val;

  val = SPI_REG32(LS_SPI_IO_CR1);
  val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
  SPI_REG32(LS_SPI_IO_CR1) = val;

  SPI_REG32(LS_SPI_IO_CR4) = 0;
  SPI_REG32(LS_SPI_IO_CR3) = 0;
  up_udelay(5);

  SPI_REG32(LS_SPI_IO_SR1) = LS_SPI_SR1_W1C_FLAGS;
  up_udelay(1);

  for (i = 0; i < 4; i++)
    {
      sr1 = SPI_REG32(LS_SPI_IO_SR1);
      if (sr1 & LS_SPI_SR1_RXE)
        {
          break;
        }

      (void)(uint8_t)SPI_REG32(LS_SPI_IO_DR);
    }

  SPI_REG32(LS_SPI_IO_CR3) = 0;
  SPI_REG32(LS_SPI_IO_DR) = tx;

  val = SPI_REG32(LS_SPI_IO_CR1);
  val |= LS_SPI_CR1_CSTART;
  SPI_REG32(LS_SPI_IO_CR1) = val;

  for (i = 0; i < SPI_WAIT_TIMEOUT_US; i++)
    {
      sr1 = SPI_REG32(LS_SPI_IO_SR1);
      if (sr1 & LS_SPI_SR1_RXA)
        {
          if (rx != NULL)
            {
              *rx = (uint8_t)SPI_REG32(LS_SPI_IO_DR);
            }
          else
            {
              (void)(uint8_t)SPI_REG32(LS_SPI_IO_DR);
            }

          val = SPI_REG32(LS_SPI_IO_CR1);
          val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
          SPI_REG32(LS_SPI_IO_CR1) = val;
          return 0;
        }

      up_udelay(1);
    }

  /* ⚠️ 超时 fallback：尝试直接读 DR（数据可能已在 FIFO 中） */

  sr1 = SPI_REG32(LS_SPI_IO_SR1);
  if (!(sr1 & LS_SPI_SR1_RXE))
    {
      if (rx != NULL)
        {
          *rx = (uint8_t)SPI_REG32(LS_SPI_IO_DR);
        }
      else
        {
          (void)(uint8_t)SPI_REG32(LS_SPI_IO_DR);
        }

      val = SPI_REG32(LS_SPI_IO_CR1);
      val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
      SPI_REG32(LS_SPI_IO_CR1) = val;
      return 0;
    }

  spi2_abort();
  return -1;
}

/****************************************************************************
 * Name: spi2_init
 *
 * Description: 初始化 SPI2 控制器和片选 GPIO
 *
 ****************************************************************************/

static int spi2_init(void)
{
  int ret;
  uint32_t brint;

  printf("[SPI] SPI2 hardware init\n");

  /* 设置 CS 引脚为 GPIO */

  ret = pinctrl_set_gpio_function(CS_PIN);
  if (ret < 0)
    {
      printf("[SPI] ERROR: pinctrl CS pin %d: %d\n", CS_PIN, ret);
      return ret;
    }

  g_fd_cs = open(CS_GPIO_PATH, O_RDWR);
  if (g_fd_cs < 0)
    {
      printf("[SPI] ERROR: open CS %s: %d\n", CS_GPIO_PATH, errno);
      return -errno;
    }

  ret = ioctl(g_fd_cs, GPIOC_SETPINTYPE, (unsigned long)GPIO_OUTPUT_PIN);
  if (ret < 0)
    {
      printf("[SPI] ERROR: CS set output: %d\n", errno);
      close(g_fd_cs);
      g_fd_cs = -1;
      return -errno;
    }

  ioctl(g_fd_cs, GPIOC_WRITE, 1);  /* CS 高（未选中） */

  /* 使能 SPI2 时钟门控 */

  CFG5_REG |= (0x3u << <CLOCK_GATE_BIT>);

  /* 配置 SPI 控制器 */

  SPI_REG32(LS_SPI_IO_CFG3) = LS_SPI_CFG3_MSTR | LS_SPI_CFG3_DIE |
                               LS_SPI_CFG3_DOE | LS_SPI_CFG3_SSMODE_SW;
  SPI_REG32(LS_SPI_IO_CFG1) = LS_SPI_CFG1_DSIZE_8BIT;

  /* 波特率分频 */

  brint = SPI_APB_HZ / SPI_CLOCK_HZ;
  if (brint < 2) brint = 2;
  if (brint > 255) brint = 255;
  SPI_REG32(LS_SPI_IO_CFG2) = brint << LS_SPI_CFG2_BRINT_SHIFT;

  /* 使能 SPI */

  SPI_REG32(LS_SPI_IO_CR1) = LS_SPI_CR1_SPE;

  printf("[SPI] SPI2 init done, clock=%lu Hz\n", SPI_CLOCK_HZ);
  return 0;
}

/****************************************************************************
 * Name: spi2_deinit
 *
 * Description: 释放 SPI 资源
 *
 ****************************************************************************/

static void spi2_deinit(void)
{
  if (g_fd_cs >= 0)
    {
      ioctl(g_fd_cs, GPIOC_WRITE, 1);
      close(g_fd_cs);
      g_fd_cs = -1;
    }
}

/****************************************************************************
 * Name: mcp3204_read
 *
 * Description: 读取 MCP3204 指定通道的 ADC 原始值
 *
 * MCP3204 命令格式：
 *   Byte1: 0x06 (Start=1, Single-ended=1, D2=0)
 *   Byte2: channel << 6
 *   Byte3: 0x00 (dummy)
 *
 * 返回数据：
 *   rx_hi: [null, D11, D10, D9, D8, D7, D6, D5]
 *   rx_lo: [D5, D4, D3, D2, D1, D0, x, x]
 *
 ****************************************************************************/

static int mcp3204_read(uint8_t channel, uint16_t *raw)
{
  uint8_t rx_hi = 0;
  uint8_t rx_lo = 0;

  ioctl(g_fd_cs, GPIOC_WRITE, 0);
  up_udelay(1);

  if (spi2_xfer_byte(0x06, NULL) != 0 ||
      spi2_xfer_byte((uint8_t)(channel << 6), &rx_hi) != 0 ||
      spi2_xfer_byte(0x00, &rx_lo) != 0)
    {
      ioctl(g_fd_cs, GPIOC_WRITE, 1);
      return -1;
    }

  ioctl(g_fd_cs, GPIOC_WRITE, 1);
  up_udelay(1);

  /* 过滤无效数据（0xff = MISO 悬空） */

  if (rx_hi == 0xff || rx_lo == 0xff)
    {
      return -1;
    }

  *raw = (uint16_t)(((uint16_t)(rx_hi & 0x0F) << 8) | rx_lo);
  return 0;
}

/****************************************************************************
 * Name: mcp3204_read_average
 *
 * Description: 多次采样取平均，自动跳过无效数据
 *
 ****************************************************************************/

static int mcp3204_read_average(uint8_t channel, uint16_t *raw)
{
  uint32_t sum = 0;
  uint16_t value;
  int valid = 0;
  int i;

  for (i = 0; i < ADC_SAMPLE_COUNT * 8; i++)
    {
      if (mcp3204_read(channel, &value) != 0)
        {
          up_mdelay(2);
          continue;
        }

      sum += value;
      if (++valid >= ADC_SAMPLE_COUNT)
        {
          break;
        }

      up_mdelay(2);
    }

  if (valid == 0)
    {
      return -1;
    }

  *raw = (uint16_t)((sum + (valid / 2)) / valid);
  return 0;
}

/****************************************************************************
 * Name: adc_to_voltage_mv
 *
 * Description: ADC 原始值转换为电压（mV），纯整数运算
 *
 ****************************************************************************/

static uint32_t adc_to_voltage_mv(uint16_t raw)
{
  return ((uint32_t)raw * ADC_VREF_MV + (ADC_MAX_VALUE / 2)) / ADC_MAX_VALUE;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int spi_adc_demo(void)
{
  int ret;
  uint16_t raw;
  uint32_t mv;

  printf("[SPI] === SPI ADC Demo (MCP3204 CH0) ===\n");

  ret = spi2_init();
  if (ret < 0)
    {
      printf("[SPI] ERROR: SPI2 init: %d\n", ret);
      return ret;
    }

  for (int round = 0; round < 10; round++)
    {
      ret = mcp3204_read_average(0, &raw);
      if (ret != 0)
        {
          printf("[SPI] %3d: CH0 read error\n", round + 1);
          continue;
        }

      mv = adc_to_voltage_mv(raw);
      printf("[SPI] %3d: CH0 raw=%4u voltage=%u.%03u V\n",
             round + 1, raw, mv / 1000, mv % 1000);

      up_mdelay(500);
    }

  spi2_deinit();
  printf("[SPI] Done.\n");
  return 0;
}

