/* 片选 GPIO */

#define CS_PIN                  <CS_PIN>
#define CS_GPIO_PATH            "/dev/gpio<CS_PIN>"

/* ADC 参数 */

#define ADC_MAX_VALUE           4095U       /* 12-bit ADC */
