/****************************************************************************
 * i2c_light_sensor_template.c
 *
 * I2C 光照传感器驱动模板（BH1750） - 龙芯 2K300 NuttX 平台
 *
 * 使用方法：
 *   1. 替换 <I2C_BUS> 为实际 I2C 总线路径（如 /dev/i2c1）
 *   2. 替换 <SLAVE_ADDR> 为实际从机地址（BH1750: 0x23 或 0x5C）
 *   3. 根据传感器型号修改命令字节和换算公式
 *
 * 编译条件：
 *   CONFIG_I2C=y
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <sys/ioctl.h>
#include <stdio.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <stdint.h>
#include <string.h>
#include <nuttx/i2c/i2c_master.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* 配置项 - 根据实际硬件修改 */

#define I2C_BUS_PATH        "<I2C_BUS>"         /* I2C 设备路径 */
#define BH1750_ADDR         <SLAVE_ADDR>        /* 7-bit 地址，无需左移 */

/* BH1750 命令字节 */

#define BH1750_POWER_ON     0x01
#define BH1750_POWER_OFF    0x00
#define BH1750_RESET        0x07
#define BH1750_CONT_HRES    0x10  /* 连续高分辨率模式 */
#define BH1750_CONT_LRES    0x13  /* 连续低分辨率模式 */
#define BH1750_ONE_HRES     0x20  /* 单次高分辨率模式 */
#define BH1750_ONE_LRES     0x23  /* 单次低分辨率模式 */

/* 测量等待时间（ms） */

#define BH1750_WAIT_HRES    180   /* 高分辨率等待时间 */
#define BH1750_WAIT_LRES    24    /* 低分辨率等待时间 */

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bh1750_send_cmd
 *
 * Description: 向 BH1750 发送单字节命令
 *
 ****************************************************************************/

static int bh1750_send_cmd(int fd, uint8_t cmd)
{
  struct i2c_msg_s msg;
  struct i2c_transfer_s xfer;

  msg.addr   = BH1750_ADDR;
  msg.flags  = 0;           /* 写操作 */
  msg.buffer = &cmd;
  msg.length = 1;

  xfer.msgv  = &msg;
  xfer.msgc  = 1;

  return ioctl(fd, I2CIOC_TRANSFER, &xfer);
}

/****************************************************************************
 * Name: bh1750_read_data
 *
 * Description: 从 BH1750 读取 2 字节数据
 *
 ****************************************************************************/

static int bh1750_read_data(int fd, uint8_t *buf, int len)
{
  struct i2c_msg_s msg;
  struct i2c_transfer_s xfer;

  msg.addr   = BH1750_ADDR;
  msg.flags  = I2C_M_READ;
  msg.buffer = buf;
  msg.length = len;

  xfer.msgv  = &msg;
  xfer.msgc  = 1;

  return ioctl(fd, I2CIOC_TRANSFER, &xfer);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bh1750_init
 *
 * Description: 初始化 BH1750 传感器
 *
 ****************************************************************************/

int bh1750_init(int fd)
{
  int ret;

  /* 上电 */

  ret = bh1750_send_cmd(fd, BH1750_POWER_ON);
  if (ret < 0)
    {
      printf("[BH1750] ERROR: power on: %d\n", ret);
      return ret;
    }

  /* 重置 */

  ret = bh1750_send_cmd(fd, BH1750_RESET);
  if (ret < 0)
    {
      printf("[BH1750] ERROR: reset: %d\n", ret);
      return ret;
    }

  up_mdelay(10);
  return 0;
}

/****************************************************************************
 * Name: bh1750_read_once
 *
 * Description: 单次测量模式读取光照强度
 *
 *   1. 发送单次高分辨率测量命令
 *   2. 等待测量完成（180ms）
 *   3. 读取 2 字节原始数据
 *   4. 换算为 lux 值
 *
 * Input Parameters:
 *   fd  - I2C 设备文件描述符
 *   lux - 输出：光照强度（lux）
 *
 * Returned Value:
 *   0 on success, negative errno on failure.
 *
 ****************************************************************************/

int bh1750_read_once(int fd, uint32_t *lux)
{
  int ret;
  uint8_t buf[2];
  uint16_t raw;

  /* 发送单次高分辨率测量命令 */

  ret = bh1750_send_cmd(fd, BH1750_ONE_HRES);
  if (ret < 0)
    {
      printf("[BH1750] ERROR: start measure: %d\n", ret);
      return ret;
    }

  /* 等待测量完成 */

  up_mdelay(BH1750_WAIT_HRES);

  /* 读取 2 字节结果 */

  ret = bh1750_read_data(fd, buf, 2);
  if (ret < 0)
    {
      printf("[BH1750] ERROR: read data: %d\n", ret);
      return ret;
    }

  /* 合并高低字节 */

  raw = ((uint16_t)buf[0] << 8) | buf[1];

  /* 换算为 lux（原始值 / 1.2，用整数：raw * 10 / 12） */

  *lux = ((uint32_t)raw * 10 + 6) / 12;

  return 0;
}

/****************************************************************************
 * Name: bh1750_start_continuous
 *
 * Description: 启动连续测量模式
 *
 ****************************************************************************/

int bh1750_start_continuous(int fd)
{
  return bh1750_send_cmd(fd, BH1750_CONT_HRES);
}

/****************************************************************************
 * Name: bh1750_read_continuous
 *
 * Description: 从连续模式读取光照强度
 *
 ****************************************************************************/

int bh1750_read_continuous(int fd, uint32_t *lux)
{
  int ret;
  uint8_t buf[2];
  uint16_t raw;

  ret = bh1750_read_data(fd, buf, 2);
  if (ret < 0)
    {
      return ret;
    }

  raw = ((uint16_t)buf[0] << 8) | buf[1];
  *lux = ((uint32_t)raw * 10 + 6) / 12;

  return 0;
}

/****************************************************************************
 * Name: bh1750_demo
 *
 * Description: BH1750 光照传感器演示
 *
 ****************************************************************************/

int i2c_light_sensor_demo(void)
{
  int fd;
  int ret;
  uint32_t lux;

  printf("[BH1750] === I2C Light Sensor Demo ===\n");

  /* 打开 I2C 设备 */

  fd = open(I2C_BUS_PATH, O_RDWR);
  if (fd < 0)
    {
      printf("[BH1750] ERROR: open %s: %d\n", I2C_BUS_PATH, errno);
      return -errno;
    }

  /* 初始化传感器 */

  ret = bh1750_init(fd);
  if (ret < 0)
    {
      close(fd);
      return ret;
    }

  /* 循环读取 */

  printf("[BH1750] Reading light intensity...\n");

  for (int i = 0; i < 10; i++)
    {
      ret = bh1750_read_once(fd, &lux);
      if (ret < 0)
        {
          printf("[BH1750] %3d: read error\n", i + 1);
          continue;
        }

      printf("[BH1750] %3d: %lu lux\n", i + 1, (unsigned long)lux);
      up_mdelay(500);
    }

  close(fd);
  printf("[BH1750] Done.\n");
  return 0;
}

