/****************************************************************************
 * i2c_oled_template.c
 *
 * I2C OLED 显示屏驱动模板（SSD1306） - 龙芯 2K300 NuttX 平台
 *
 * 使用方法：
 *   1. 替换 <I2C_BUS> 为实际 I2C 总线路径（如 /dev/i2c1）
 *   2. 替换 <SLAVE_ADDR> 为实际从机地址（SSD1306: 0x3C 或 0x3D）
 *   3. 根据屏幕分辨率修改 OLED_WIDTH / OLED_HEIGHT
 *
 * 编译条件：
 *   CONFIG_I2C=y
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <sys/ioctl.h>
#include <stdio.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <stdint.h>
#include <string.h>
#include <nuttx/i2c/i2c_master.h>
#include <nuttx/arch.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* 配置项 - 根据实际硬件修改 */

#define I2C_BUS_PATH        "<I2C_BUS>"         /* I2C 设备路径 */
#define OLED_I2C_ADDR       <SLAVE_ADDR>        /* 7-bit 地址 */

/* OLED 参数 */

#define OLED_WIDTH          128
#define OLED_HEIGHT         64
#define OLED_PAGES          (OLED_HEIGHT / 8)

/* I2C 控制字节 */

#define OLED_CMD_MODE       0x00    /* 后续为命令 */
#define OLED_DATA_MODE      0x40    /* 后续为数据 */

/****************************************************************************
 * Private Data
 ****************************************************************************/

static int g_oled_fd = -1;

/* 6x8 字体表（ASCII 32~126） */

static const uint8_t g_font_6x8[][6] =
{
  { 0x00, 0x00, 0x00, 0x00, 0x00, 0x00 },  /* ' ' */
  { 0x00, 0x00, 0x5F, 0x00, 0x00, 0x00 },  /* '!' */
  { 0x00, 0x07, 0x00, 0x07, 0x00, 0x00 },  /* '"' */
  /* ... 完整字体表需补充 ASCII 35~126 ... */
  { 0x3E, 0x51, 0x49, 0x45, 0x3E, 0x00 },  /* '0' */
  { 0x00, 0x42, 0x7F, 0x40, 0x00, 0x00 },  /* '1' */
  { 0x42, 0x61, 0x51, 0x49, 0x46, 0x00 },  /* '2' */
  { 0x21, 0x41, 0x45, 0x4B, 0x31, 0x00 },  /* '3' */
  { 0x18, 0x14, 0x12, 0x7F, 0x10, 0x00 },  /* '4' */
  { 0x27, 0x45, 0x45, 0x45, 0x39, 0x00 },  /* '5' */
  { 0x3C, 0x4A, 0x49, 0x49, 0x30, 0x00 },  /* '6' */
  { 0x01, 0x71, 0x09, 0x05, 0x03, 0x00 },  /* '7' */
  { 0x36, 0x49, 0x49, 0x49, 0x36, 0x00 },  /* '8' */
  { 0x06, 0x49, 0x49, 0x29, 0x1E, 0x00 },  /* '9' */
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: oled_send
 *
 * Description: 向 OLED 发送数据（命令或显示数据）
 *
 ****************************************************************************/

static int oled_send(uint8_t ctrl, const uint8_t *data, int len)
{
  uint8_t *buf;
  struct i2c_msg_s msg;
  struct i2c_transfer_s xfer;
  int ret;

  buf = malloc(len + 1);
  if (buf == NULL)
    {
      return -ENOMEM;
    }

  buf[0] = ctrl;
  memcpy(&buf[1], data, len);

  msg.addr   = OLED_I2C_ADDR;
  msg.flags  = 0;
  msg.buffer = buf;
  msg.length = len + 1;

  xfer.msgv  = &msg;
  xfer.msgc  = 1;

  ret = ioctl(g_oled_fd, I2CIOC_TRANSFER, &xfer);
  free(buf);
  return ret;
}

static int oled_send_cmd(uint8_t cmd)
{
  return oled_send(OLED_CMD_MODE, &cmd, 1);
}

static int oled_send_cmds(const uint8_t *cmds, int len)
{
  return oled_send(OLED_CMD_MODE, cmds, len);
}

static int oled_send_data(const uint8_t *data, int len)
{
  return oled_send(OLED_DATA_MODE, data, len);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: oled_init
 *
 * Description: 初始化 SSD1306 OLED 显示屏
 *
 * 初始化序列：
 *   1. 关闭显示
 *   2. 设置时钟分频、多路复用率
 *   3. 设置显示偏移、起始行
 *   4. 使能电荷泵
 *   5. 设置寻址模式（页寻址）
 *   6. 设置段重映射、COM 扫描方向
 *   7. 设置对比度、预充电、VCOMH
 *   8. 开启显示
 *
 ****************************************************************************/

int oled_init(int fd)
{
  g_oled_fd = fd;

  static const uint8_t init_cmds[] =
  {
    0xAE,       /* Display OFF */
    0xD5, 0x80, /* Set Display Clock: div=1, freq=100Hz */
    0xA8, 0x3F, /* Set Multiplex Ratio: 64-1 (1/64 duty) */
    0xD3, 0x00, /* Set Display Offset: 0 */
    0x40,       /* Set Start Line: 0 */
    0x8D, 0x14, /* Charge Pump: enable */
    0x20, 0x02, /* Memory Addressing Mode: Page */
    0xA1,       /* Segment Re-map: col127 -> SEG0 */
    0xC8,       /* COM Scan Direction: COM[N-1] -> COM0 */
    0xDA, 0x12, /* COM Pins: alternative config */
    0x81, 0xCF, /* Contrast: 207 */
    0xD9, 0xF1, /* Pre-charge Period */
    0xDB, 0x40, /* VCOMH Deselect: 0.83 x VCC */
    0xA4,       /* Entire Display ON (resume) */
    0xA6,       /* Normal Display (not inverted) */
    0xAF,       /* Display ON */
  };

  return oled_send_cmds(init_cmds, sizeof(init_cmds));
}

/****************************************************************************
 * Name: oled_set_cursor
 *
 * Description: 设置页地址和列地址（页寻址模式）
 *
 ****************************************************************************/

void oled_set_cursor(uint8_t page, uint8_t col)
{
  uint8_t cmds[3];
  cmds[0] = 0xB0 + page;        /* Page address */
  cmds[1] = 0x00 + (col & 0x0F); /* Column low nibble */
  cmds[2] = 0x10 + (col >> 4);   /* Column high nibble */
  oled_send_cmds(cmds, 3);
}

/****************************************************************************
 * Name: oled_clear
 *
 * Description: 清屏（全黑）
 *
 ****************************************************************************/

void oled_clear(void)
{
  uint8_t zeros[OLED_WIDTH];
  memset(zeros, 0, OLED_WIDTH);

  for (int page = 0; page < OLED_PAGES; page++)
    {
      oled_set_cursor(page, 0);
      oled_send_data(zeros, OLED_WIDTH);
    }
}

/****************************************************************************
 * Name: oled_fill
 *
 * Description: 全屏填充指定字节
 *
 ****************************************************************************/

void oled_fill(uint8_t data)
{
  uint8_t buf[OLED_WIDTH];
  memset(buf, data, OLED_WIDTH);

  for (int page = 0; page < OLED_PAGES; page++)
    {
      oled_set_cursor(page, 0);
      oled_send_data(buf, OLED_WIDTH);
    }
}

/****************************************************************************
 * Name: oled_putchar
 *
 * Description: 在指定位置显示一个字符（6x8 字体）
 *
 ****************************************************************************/

void oled_putchar(uint8_t page, uint8_t col, char ch)
{
  if (ch < '0' || ch > '9')
    {
      /* 仅支持数字 0-9，其他字符显示空白 */
      uint8_t space[6] = { 0 };
      oled_set_cursor(page, col);
      oled_send_data(space, 6);
      return;
    }

  oled_set_cursor(page, col);
  oled_send_data(g_font_6x8[ch - '0' + 4], 6);  /* 偏移量4对应'0' */
}

/****************************************************************************
 * Name: oled_puts
 *
 * Description: 在指定位置显示字符串
 *
 ****************************************************************************/

void oled_puts(uint8_t page, uint8_t col, const char *str)
{
  while (*str)
    {
      oled_putchar(page, col, *str);
      col += 6;
      if (col > OLED_WIDTH - 6)
        {
          col = 0;
          page++;
          if (page >= OLED_PAGES) return;
        }
      str++;
    }
}

/****************************************************************************
 * Name: oled_show_number
 *
 * Description: 在指定位置显示整数（无 FPU，纯整数运算）
 *
 ****************************************************************************/

void oled_show_number(uint8_t page, uint8_t col, uint32_t value)
{
  char buf[12];
  int len = 0;
  uint32_t tmp = value;

  /* 提取各位数字 */

  do
    {
      buf[len++] = '0' + (tmp % 10);
      tmp /= 10;
    }
  while (tmp > 0 && len < 11);

  /* 反转 */

  for (int i = 0; i < len / 2; i++)
    {
      char t = buf[i];
      buf[i] = buf[len - 1 - i];
      buf[len - 1 - i] = t;
    }

  buf[len] = '\0';
  oled_puts(page, col, buf);
}

/****************************************************************************
 * Name: oled_show_voltage
 *
 * Description: 显示电压值（mV → V），如 3375 → "3.375"
 *
 ****************************************************************************/

void oled_show_voltage(uint8_t page, uint8_t col, uint32_t voltage_mv)
{
  uint32_t integer = voltage_mv / 1000;
  uint32_t frac = voltage_mv % 1000;

  oled_show_number(page, col, integer);

  /* 小数点 */

  uint8_t dot_col = col;
  uint32_t tmp = integer;
  do
    {
      dot_col += 6;
      tmp /= 10;
    }
  while (tmp > 0);

  /* 这里简化处理，实际需要自定义小数点像素 */

  oled_putchar(page, dot_col, '.');
  oled_show_number(page, dot_col + 6, frac);
}

/****************************************************************************
 * Name: oled_deinit
 *
 * Description: 关闭显示
 *
 ****************************************************************************/

void oled_deinit(void)
{
  oled_send_cmd(0xAE);  /* Display OFF */
  g_oled_fd = -1;
}

/****************************************************************************
 * Name: i2c_oled_demo
 *
 * Description: OLED 显示演示
 *
 ****************************************************************************/

int i2c_oled_demo(void)
{
  int fd;

  printf("[OLED] === I2C OLED Demo (SSD1306) ===\n");

  /* 打开 I2C 设备 */

  fd = open(I2C_BUS_PATH, O_RDWR);
  if (fd < 0)
    {
      printf("[OLED] ERROR: open %s: %d\n", I2C_BUS_PATH, errno);
      return -errno;
    }

  /* 初始化 OLED */

  int ret = oled_init(fd);
  if (ret < 0)
    {
      printf("[OLED] ERROR: init: %d\n", ret);
      close(fd);
      return ret;
    }

  /* 清屏 */

  oled_clear();

  /* 显示文字 */

  oled_puts(0, 0, "Hello 2K300!");
  oled_puts(2, 0, "OLED OK");

  /* 显示数值 */

  oled_show_number(4, 0, 12345);

  /* 显示电压 */

  oled_show_voltage(6, 0, 3375);  /* 3.375V */

  printf("[OLED] Display updated.\n");

  up_mdelay(5000);

  /* 关闭 */

  oled_deinit();
  close(fd);

  printf("[OLED] Done.\n");
  return 0;
}

