85	static int oled_write(uint8_t mode, const uint8_t *data, uint16_t len)
86	{
87	  uint8_t buf[1 + len];
88	  struct i2c_msg_s msg;
89	  struct i2c_transfer_s xfer;
90	
91	  buf[0] = mode;
92	  memcpy(&buf[1], data, len);
93	
94	  msg.addr   = OLED_I2C_ADDR;
95	  msg.flags  = 0;
96	  msg.buffer = buf;
97	  msg.length = 1 + len;
98	  xfer.msgv  = &msg;
99	  xfer.msgc  = 1;
100	
101	  return ioctl(g_oled_fd, I2CIOC_TRANSFER, &xfer);
102	}
