104	static int oled_cmd(uint8_t cmd)
105	{
106	  return oled_write(OLED_CMD_MODE, &cmd, 1);
107	}
108	
109	static int oled_data(const uint8_t *data, uint16_t len)
110	{
111	  return oled_write(OLED_DATA_MODE, data, len);
112	}
