164	int oled_clear(void)
165	{
166	  uint8_t zero[OLED_WIDTH];
167	  int page;
168	
169	  memset(zero, 0, sizeof(zero));
170	
171	  for (page = 0; page < OLED_PAGES; page++)
172	    {
173	      oled_cmd(0xB0 + page);  /* Page address */
174	      oled_cmd(0x00);          /* Column low nibble = 0 */
175	      oled_cmd(0x10);          /* Column high nibble = 0 */
176	      oled_data(zero, OLED_WIDTH);
177	    }
178	
179	  return 0;
180	}
