51	  int state = 0;
52	
53	  printf("[LED] GPIO LED Demo on pin %d\n", LED_PIN);
54	
55	  /* Step 1: 设置引脚为 GPIO 模式 */
56	
57	  ret = pinctrl_set_gpio_function(LED_PIN);
58	  if (ret < 0)
59	    {
60	      printf("[LED] ERROR: pinctrl pin %d: %d\n", LED_PIN, ret);
61	      return ret;
62	    }
63	
64	  /* Step 2: 打开 GPIO 设备 */
65	
66	  fd = open(LED_GPIO_PATH, O_RDWR);
67	  if (fd < 0)
68	    {
69	      printf("[LED] ERROR: open %s: %d\n", LED_GPIO_PATH, errno);
70	      return -errno;
71	    }
72	
73	  /* Step 3: 设置为输出模式 */
74	
75	  ret = ioctl(fd, GPIOC_SETPINTYPE, (unsigned long)GPIO_OUTPUT_PIN);
76	  if (ret < 0)
77	    {
78	      printf("[LED] ERROR: set output: %d\n", errno);
79	      close(fd);
80	      return -errno;
81	    }
82	
83	  /* Step 4: 心跳灯循环 */
84	
85	  printf("[LED] Blinking at %d ms interval...\n", LED_BLINK_MS);
86	
87	  for (int i = 0; i < 20; i++)
88	    {
89	      state ^= 1;
