102	  ls_pinmux_pin_setup(64, LS_PINMUX_MODE_AS_MAIN_FUNC);
103	  ls_pinmux_pin_setup(65, LS_PINMUX_MODE_AS_MAIN_FUNC);
104	  ls_pinmux_pin_setup(66, LS_PINMUX_MODE_AS_MAIN_FUNC);
